  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el Tribunal Constitucional, señale la opción CORRECTA.', 'Art. 160 CE (Presidente), art. 164.1 (publicación en el BOE con votos particulares, sin recurso) y art. 162.1.a (50 Diputados o 50 Senadores).', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2022-1 (n.º 23) · Arts. 160, 162 y 164 CE', 'El Presidente del Tribunal Constitucional será nombrado entre sus miembros por el Rey, a propuesta del mismo Tribunal en pleno y por un período de tres años.', null, '6d9fab05bbca3158a4823f09528e7085f89a26a7b49f7a2de63b9ebd97dafedf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6d9fab05bbca3158a4823f09528e7085f89a26a7b49f7a2de63b9ebd97dafedf')
  returning id
), o as (
