  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sus sentencias se publican en el Diario Oficial del Tribunal, sin los votos particulares.', false), ('B', 'Su Presidente es nombrado por el Rey entre sus miembros, a propuesta del propio Tribunal en pleno, por tres años.', true), ('C', 'Contra sus sentencias cabe recurso ante el Pleno en el plazo de tres días.', false), ('D', 'Pueden interponer recurso de inconstitucionalidad 40 Senadores.', false)) as v(label, body, ok)
)
