with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 22 del Convenio Europeo de Derechos Humanos, ¿por qué mayoría elige la Asamblea Parlamentaria a los jueces del Tribunal Europeo de Derechos Humanos y de cuántos candidatos consta la lista de cada Alta Parte Contratante?', 'El art. 22 CEDH: elección por la Asamblea Parlamentaria, por mayoría absoluta de votos, de una terna presentada por cada Estado.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Réplica 2022-1 (n.º 4) · Art. 22 CEDH', 'Los Jueces serán elegidos por la Asamblea Parlamentaria en razón de cada Alta Parte Contratante, por mayoría absoluta de votos, de una lista de tres candidatos presentada por esa Alta Parte Contratante', null, 'bb3064b82fa7c5b689223baed689196161b83dcf584facd8e00fd825e7cddb02', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bb3064b82fa7c5b689223baed689196161b83dcf584facd8e00fd825e7cddb02')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por mayoría de dos tercios, de una lista de dos candidatos.', false), ('B', 'Por mayoría simple, de una lista de cinco candidatos.', false), ('C', 'Por mayoría absoluta de votos, de una lista de tres candidatos.', true), ('D', 'Por mayoría absoluta de votos, de una lista de cuatro candidatos.', false)) as v(label, body, ok)
)
