  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con los delitos y las formas de participación intentada del Código Penal, señale la afirmación INCORRECTA.', 'El art. 18.2, párrafo segundo, CP castiga como inducción la provocación seguida de la perpetración del delito.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2022-1 (n.º 42) · Arts. 10, 12, 17 y 18 CP', 'Si a la provocación hubiese seguido la perpetración del delito, se castigará como inducción.', null, 'be4858b126456ca894778a645574e7e6c6d3b6ca81b26f52ef72b8161e2fda21', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'be4858b126456ca894778a645574e7e6c6d3b6ca81b26f52ef72b8161e2fda21')
