with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes compromisos incluye el artículo 1 de la Carta Social Europea (revisada), dedicado al derecho al trabajo?', 'El art. 1 (derecho al trabajo) incluye el pleno empleo, el trabajo libremente elegido, los servicios gratuitos de empleo y la orientación, formación y readaptación profesionales. La remuneración y las vacaciones están en los arts. 2 y 4.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-9719'), 'Réplica 2022-1 (n.º 5) · Art. 1 Carta Social Europea revisada', 'Para garantizar el ejercicio efectivo del derecho al trabajo, las Partes se comprometen: […] 3. a establecer o mantener servicios gratuitos de empleo para todos los trabajadores;', null, '51d0be8e7124db5e607f1f9124744d7a679acf3557dd8801a95f1d5eb87b3bea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '51d0be8e7124db5e607f1f9124744d7a679acf3557dd8801a95f1d5eb87b3bea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Garantizar un salario mínimo interprofesional revisado anualmente.', false), ('B', 'Establecer o mantener servicios gratuitos de empleo para todos los trabajadores.', true), ('C', 'Asegurar a los trabajadores vacaciones pagadas de al menos cuatro semanas.', false), ('D', 'Reconocer el derecho a la igualdad de retribución por un trabajo de igual valor.', false)) as v(label, body, ok)
)
