with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 de la Carta de las Naciones Unidas, ¿cuál de los siguientes figura entre los órganos principales de la Organización?', 'El art. 7 enumera seis órganos principales: Asamblea General, Consejo de Seguridad, Consejo Económico y Social, Consejo de Administración Fiduciaria, Corte Internacional de Justicia y Secretaría. Los demás citados son órganos subsidiarios, de tratados o ajenos a la Carta.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/un-charter/full-text'), 'Réplica 2022-1 (n.º 1) · Art. 7 Carta de las Naciones Unidas', 'Se establecen como órganos principales de las Naciones Unidas: una Asamblea General, un Consejo de Seguridad, un Consejo Económico y Social, un Consejo de Administración Fiduciaria, una Corte Internacional de Justicia, una Secretaría.', null, '5f38afc983c44b6ea8a0ac350c2a6841600bc493d0a5c0d58a17a7ec547ed297', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f38afc983c44b6ea8a0ac350c2a6841600bc493d0a5c0d58a17a7ec547ed297')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
