with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto a la igualdad entre mujeres y hombres y a los derechos del niño en la Carta de los Derechos Fundamentales de la Unión Europea, señale la afirmación INCORRECTA.', 'El art. 23, párrafo segundo, permite mantener o adoptar medidas que supongan ventajas concretas a favor del sexo menos representado.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016P/TXT'), 'Réplica 2022-1 (n.º 10) · Arts. 23 y 24 Carta de los Derechos Fundamentales de la UE', 'El principio de igualdad no impide el mantenimiento o la adopción de medidas que supongan ventajas concretas en favor del sexo menos representado.', null, 'cc885d1fb1b5bd97ad73da8e942364c164bff6bec097da355d571adee52fc23a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc885d1fb1b5bd97ad73da8e942364c164bff6bec097da355d571adee52fc23a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los niños pueden expresar su opinión libremente, y esta se tendrá en cuenta en los asuntos que les afecten en función de su edad y madurez.', false), ('B', 'El principio de igualdad obliga a suprimir cualquier medida que conceda ventajas concretas al sexo menos representado.', true), ('C', 'El interés superior del niño será una consideración primordial en los actos que le afecten, tanto de autoridades públicas como de instituciones privadas.', false), ('D', 'La igualdad entre mujeres y hombres debe garantizarse en todos los ámbitos, incluidos el empleo, el trabajo y la retribución.', false)) as v(label, body, ok)
)
