  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Reconoce a toda persona el derecho a un recurso efectivo ante los tribunales nacionales competentes frente a actos que violen sus derechos fundamentales.', false), ('B', 'Su preámbulo recuerda que los Estados Miembros se han comprometido a asegurar el respeto de los derechos y libertades en cooperación con el Consejo de Europa.', true), ('C', 'Prohíbe que nadie sea detenido, preso o desterrado de forma arbitraria.', false), ('D', 'Su preámbulo parte de que la libertad, la justicia y la paz en el mundo tienen por base el reconocimiento de la dignidad intrínseca de todos los miembros de la familia humana.', false)) as v(label, body, ok)
)
