insert into public.sources (title, url, kind, publisher, published_on) values ('Protocolo facultativo de la Convención contra la tortura y otros tratos o penas crueles, inhumanos o degradantes (Nueva York, 18 de diciembre de 2002). Instrumento de ratificación, BOE núm. 148, de 22 de junio de 2006', 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128', 'web_oficial'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado (BOE-A-2006-11128)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gcexamen-2022-1', 'Examen réplica 2022, ejercicio 1 · Prueba de conocimientos (100 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gcexamen-2022-1' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos del Protocolo Facultativo de la Convención contra la Tortura, ¿qué se entiende por privación de libertad?', 'El art. 4.2 adopta un concepto amplio: autoridad judicial, administrativa u otra autoridad pública; institución pública o privada; imposibilidad de salir libremente.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Réplica 2022-1 (n.º 9) · Art. 4.2 Protocolo Facultativo de la Convención contra la Tortura', 'A los efectos del presente Protocolo, por privación de libertad se entiende cualquier forma de detención o encarcelamiento o de custodia de una persona, por orden de una autoridad judicial o administrativa o de otra autoridad pública, en una institución pública o privada de la cual no pueda salir libremente.', null, '227c4af628862caf7b2bcec919e259b8348ecf038b20c2df8025a054fd3b85cd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '227c4af628862caf7b2bcec919e259b8348ecf038b20c2df8025a054fd3b85cd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente el internamiento acordado por un juez en un establecimiento penitenciario.', false), ('B', 'La custodia de una persona en una institución pública, quedando excluidas las privadas.', false), ('C', 'Cualquier forma de detención, encarcelamiento o custodia de una persona, ordenada por una autoridad judicial, administrativa u otra autoridad pública, en una institución pública o privada de la que no pueda salir libremente.', true), ('D', 'Cualquier estancia en una institución, aunque la persona pueda abandonarla cuando quiera.', false)) as v(label, body, ok)
)
