with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO es un principio específico de la interoperabilidad del artículo 4 del Esquema Nacional de Interoperabilidad?', 'El art. 4 del RD 4/2010 recoge tres principios específicos: cualidad integral, carácter multidimensional y enfoque de soluciones multilaterales.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331'), 'Réplica 2022-1 (n.º 89) · Art. 4 RD 4/2010 (ENI)', 'a) La interoperabilidad como cualidad integral. […] b) Carácter multidimensional de la interoperabilidad. […] c) Enfoque de soluciones multilaterales.', null, '17e44a64b1033ba830cfa637c7f508f3d91e8a702699069e3c39c52826766a9f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '17e44a64b1033ba830cfa637c7f508f3d91e8a702699069e3c39c52826766a9f')
  returning id
), o as (
