  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 18 del TUE, ¿qué afirmación es CORRECTA en materia de PESC y de PCSD?', 'El art. 18 TUE: nombramiento por el Consejo Europeo por mayoría cualificada con la aprobación del Presidente de la Comisión; preside el Consejo de Asuntos Exteriores y es Vicepresidente de la Comisión.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Réplica 2022-1 (n.º 28) · Art. 18.2 TUE (Alto Representante y PCSD)', 'El Alto Representante estará al frente de la política exterior y de seguridad común de la Unión. Contribuirá con sus propuestas a elaborar dicha política y la ejecutará como mandatario del Consejo. Actuará del mismo modo en relación con la política común de seguridad y defensa.', null, 'ae81acd542c438e352fe46fd1a1c18d3ae711c291398ac9ce297cd8a3fa7e0fb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae81acd542c438e352fe46fd1a1c18d3ae711c291398ac9ce297cd8a3fa7e0fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Alto Representante es nombrado por el Parlamento Europeo por mayoría absoluta.', false), ('B', 'El Consejo de Asuntos Exteriores lo preside el Presidente del Consejo Europeo.', false), ('C', 'El Alto Representante no forma parte de la Comisión.', false), ('D', 'El Alto Representante está al frente de la política exterior y de seguridad común y actúa del mismo modo en la política común de seguridad y defensa.', true)) as v(label, body, ok)
)
