with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el mercado interior y los objetivos de la Unión del artículo 3 del TUE, señale la opción CORRECTA.', 'El art. 3.3 TUE: mercado interior, desarrollo sostenible, economía social de mercado altamente competitiva y estabilidad de precios; el espacio del art. 3.2 es sin fronteras interiores.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016M/TXT'), 'Réplica 2022-1 (n.º 29) · Art. 3.3 TUE (mercado interior)', 'La Unión establecerá un mercado interior. Obrará en pro del desarrollo sostenible de Europa basado en un crecimiento económico equilibrado y en la estabilidad de los precios, en una economía social de mercado altamente competitiva', null, 'e5c37a3f523e7066610c935f994834fe19d860673762f0372ec036e3ada1e4d5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e5c37a3f523e7066610c935f994834fe19d860673762f0372ec036e3ada1e4d5')
  returning id
