with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3.2 del TUE, el espacio de libertad, seguridad y justicia que la Unión ofrece a sus ciudadanos es un espacio:', 'El art. 3.2 TUE define el espacio de libertad, seguridad y justicia sin fronteras interiores. Las orientaciones estratégicas de su programación legislativa las define el Consejo Europeo (art. 68 TFUE).', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016M/TXT'), 'Réplica 2022-1 (n.º 30) · Art. 3.2 TUE (espacio de libertad, seguridad y justicia)', 'La Unión ofrecerá a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores, en el que esté garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia.', null, '2efa8261697748de4cccec8d11ef6dcba73d180af5d867e13498e9a15ce80fd1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2efa8261697748de4cccec8d11ef6dcba73d180af5d867e13498e9a15ce80fd1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sin fronteras interiores, con libre circulación de personas y medidas adecuadas de control de las fronteras exteriores, asilo, inmigración y lucha contra la delincuencia.', true), ('B', 'Sin fronteras exteriores, en el que cada Estado mantiene sus controles en las fronteras interiores.', false), ('C', 'Limitado a los Estados que forman parte de la zona del euro.', false), ('D', 'Reservado a la cooperación judicial en materia civil.', false)) as v(label, body, ok)
)
