with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la historia oficial de la Guardia Civil, en su primera misión internacional (1847) una unidad de Caballería del Cuerpo:', 'Portugal, en guerra civil, pidió ayuda a España y al Reino Unido para pacificar el norte; la Caballería de la Guardia Civil patrulló Oporto.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-1 (n.º 80) · Historia GC: la consolidación (1847)', 'Habría de transcurrir poco tiempo para que la Guardia Civil desempeñase su primera misión internacional; en 1847 un Portugal en guerra civil, con el fin de pacificar el norte del país, solicita la ayuda de España y el Reino Unido. Una unidad de Caballería de la Guardia Civil se encarga de patrullar y garantizar la seguridad ciudadana en la ciudad de Oporto.', null, 'a826ca27a50931b31100f2e0247015addb4403b29f3066a4233972d6022e70f9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a826ca27a50931b31100f2e0247015addb4403b29f3066a4233972d6022e70f9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Custodió la embajada española en Londres.', false), ('B', 'Patrulló y garantizó la seguridad ciudadana en Oporto, durante la guerra civil portuguesa.', true), ('C', 'Protegió la frontera de Cuba durante la Guerra de los Diez Años.', false), ('D', 'Intervino en la Primavera de los Pueblos en París.', false)) as v(label, body, ok)
)
