with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la historia oficial de la Guardia Civil, ¿dónde recibieron su instrucción los primeros guardias reclutados en el verano de 1844?', 'La instrucción de los primeros guardias se hizo en Leganés y Vicálvaro; la Compañía de Guardias Jóvenes es de 1853 y la Academia de Úbeda, de los años cuarenta del siglo XX.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-1 (n.º 94) · Historia GC: la fundación (instrucción de los primeros guardias)', 'En el verano de 1844 se inició el reclutamiento de los primeros aspirantes, muy superiores en número a las plazas ofertadas, en lo que fue una muy rigurosa selección que había de complementarse con una instrucción minuciosa y exigente de los nuevos guardias en las instalaciones del Ejército de Madrid, en Leganés y Vicálvaro.', null, '7ce482ba0ea1b832af2bd8d9624816d20fae53e70bf9d7fa7b37306ba4e3c586', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7ce482ba0ea1b832af2bd8d9624816d20fae53e70bf9d7fa7b37306ba4e3c586')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el Colegio de Guardias Jóvenes de Valdemoro.', false), ('B', 'En la Academia de Úbeda.', false), ('C', 'En las instalaciones del Ejército de Madrid, en Leganés y Vicálvaro.', true), ('D', 'En el Colegio Infanta María Teresa de Madrid.', false)) as v(label, body, ok)
)
