with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la historia oficial de la Guardia Civil, tras la «Sanjurjada» de agosto de 1932, la Dirección General del Cuerpo se transformó en Inspección General y pasó a depender:', 'La Dirección General, dependiente del Ministerio de la Guerra, pasó a ser Inspección General dependiente del Ministerio de la Gobernación.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-1 (n.º 95) · Historia GC: la Segunda República (dependencia del Cuerpo)', 'La conocida como Sanjurjada tiene como consecuencia que la Dirección General de la Guardia Civil dependiente del Ministerio de la Guerra se transforme en Inspección General para pasar a depender del Ministerio de Gobernación.', null, '5e5dd0e5a440c1a96a148a054318f6581590bbec5240b4ebd559338562402b60', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5e5dd0e5a440c1a96a148a054318f6581590bbec5240b4ebd559338562402b60')
  returning id
), o as (
