with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la historia oficial de la Guardia Civil, ¿cuál de los siguientes NO figuraba en el objeto primordial del Instituto fijado por el Reglamento para el Servicio de 9 de octubre de 1844?', 'El Reglamento para el Servicio fijó como objeto primordial la conservación del orden público, la protección de las personas y las propiedades y el auxilio a la ejecución de las leyes.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-1 (n.º 96) · Historia GC: la fundación (Reglamento para el Servicio de 1844)', 'El 9 de octubre de 1844 se aprobaba el Reglamento para el Servicio de la Guardia Civil, estableciendo las obligaciones y facultades de la Guardia Civil, su dependencia orgánica, vinculada en lo referido a su servicio peculiar al Ministerio de la Gobernación, y el objeto primordial de la Institución: “la conservación del orden público, la protección de las personas y las propiedades (...) y el auxilio que reclame la ejecución de las leyes”.', null, '0f7c09c095611f346fd9cb40cccd349152b2cd8f9a6e5ee2dab34378d4b5efe2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0f7c09c095611f346fd9cb40cccd349152b2cd8f9a6e5ee2dab34378d4b5efe2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La conservación del orden público.', false), ('B', 'La recaudación de las contribuciones del Estado.', true), ('C', 'La protección de las personas y las propiedades.', false), ('D', 'El auxilio que reclame la ejecución de las leyes.', false)) as v(label, body, ok)
)
