select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes textos fundacionales de la Guardia Civil NO se aprobó en 1844?', 'El Real Decreto de creación es de 28 de marzo de 1844, el Reglamento para el Servicio de 9 de octubre y el Reglamento Militar de 15 de octubre de 1844; la Cartilla, de 20 de diciembre de 1845.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 3, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-1 (n.º 97) · Historia GC: la fundación (textos fundacionales)', 'Surge así el 20 de diciembre de 1845, de la propia mano del Duque de Ahumada, un documento que constituye el auténtico código moral de la Institución: la “Cartilla del Guardia Civil”', null, 'd8f10def0d8eda7585b902acb0e0f9824c256ee5e7b3e0dd210f00c2078e9fab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd8f10def0d8eda7585b902acb0e0f9824c256ee5e7b3e0dd210f00c2078e9fab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
