with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el IGN, la información sobre el plano, que es insuficiente en la mayoría de los casos y debe completarse con información altimétrica, se denomina:', 'La planimetría representa los detalles del terreno sobre el plano prescindiendo del relieve; la altimetría añade las altitudes respecto de un plano de referencia.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.ign.es/resources/acercaDe/libDigPub/tu-amigo-el-mapa.pdf'), 'Réplica 2022-1 (n.º 91) · IGN · Amigo mapa (planimetría y altimetría)', 'La información sobre el plano (planimetría) es insuficiente en la mayoría de los casos, por lo que es necesario disponer de una información altimétrica complementaria que nos señale altitudes sobre un plano de referencia.', null, 'd4e2daf79996a469b56eb1d51b2e47320aa5c0782eedb15bde05443455306629', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd4e2daf79996a469b56eb1d51b2e47320aa5c0782eedb15bde05443455306629')
  returning id
