with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dos curvas de nivel consecutivas A (620 m) y B, de mayor cota, con equidistancia de 10 m y pendiente constante, están separadas 8 mm en el mapa. ¿Cuál es la cota de un punto P situado entre ellas a 3,2 mm de la curva A?', 'Con pendiente constante, la cota se interpola linealmente: desnivel = 10 m × 3,2 / 8 = 4 m; cota de P = 620 + 4 = 624 m.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 3, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/cartografia-bach/representacin_del_relieve.html'), 'Réplica 2022-1 (n.º 93) · IGN · Atlas didáctico (curvas de nivel y equidistancia; cálculo de cotas)', 'En un mismo mapa la distancia vertical que separa dos curvas de nivel consecutivas suele ser constante y se denomina equidistancia.', null, '29f004074d2a77b42297add9ca81219cb649c41f1da54a8ae9453039b21a7795', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '29f004074d2a77b42297add9ca81219cb649c41f1da54a8ae9453039b21a7795')
  returning id
