with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el Defensor del Pueblo, en el ejercicio de sus funciones, conoce una conducta presumiblemente delictiva, ¿a quién debe comunicarlo de inmediato según el artículo 25 de la Ley Orgánica 3/1981?', 'El art. 25.1 LODP: comunicación inmediata al Fiscal General del Estado, que le informará periódicamente del trámite.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Réplica 2022-1 (n.º 25) · Art. 25.1 LO 3/1981', 'Cuando el Defensor del Pueblo, en razón del ejercicio de las funciones propias de su cargo, tenga conocimiento de una conducta o hechos presumiblemente delictivos lo pondrá de inmediato en conocimiento del Fiscal General del Estado.', null, '606e2b8f028aa9a4ca4a5b4849524aaf53bb29e6dfc01e714e8e03ddf1f9a057', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '606e2b8f028aa9a4ca4a5b4849524aaf53bb29e6dfc01e714e8e03ddf1f9a057')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Juez de Guardia del lugar de los hechos.', false), ('B', 'A las Cortes Generales.', false), ('C', 'Al Fiscal General del Estado.', true), ('D', 'Al Ministro de Justicia.', false)) as v(label, body, ok)
)
