with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con las clases de visados del artículo 25 bis de la LO 4/2000, señale la opción CORRECTA.', 'Art. 25 bis.2: la temporada permite hasta nueve meses en doce; el de estudios se refiere a actividades no remuneradas laboralmente; el de residencia no permite trabajar.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-1 (n.º 67) · Art. 25 bis.2 LO 4/2000', 'b) Visado de estancia, que habilita para una estancia ininterrumpida o estancias sucesivas por un período o suma de períodos cuya duración total no exceda de tres meses por semestre a partir de la fecha de la primera entrada.', null, 'a4243c3d284d32fa229dfdef47fa0052757dd510de6a24897d2b8d0a754c69ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a4243c3d284d32fa229dfdef47fa0052757dd510de6a24897d2b8d0a754c69ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El visado de estudios habilita para realizar trabajos de investigación remunerados laboralmente.', false), ('B', 'El visado de residencia y trabajo de temporada permite trabajar hasta seis meses dentro de un periodo de doce meses seguidos.', false), ('C', 'El visado de residencia habilita para residir y ejercer actividad laboral.', false), ('D', 'El visado de estancia permite estancias que no excedan en total de tres meses por semestre desde la primera entrada.', true)) as v(label, body, ok)
)
