with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando las Fuerzas y Cuerpos de Seguridad localizan a un extranjero indocumentado cuya minoría de edad no puede establecerse con seguridad, ¿quién dispone la determinación de su edad según el artículo 35.3 de la LO 4/2000?', 'El hecho se comunica de inmediato al Ministerio Fiscal, que dispone la determinación de la edad; determinada la minoría, el Fiscal pone al menor a disposición de los servicios de protección de la Comunidad Autónoma (art. 35.4).', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-1 (n.º 68) · Art. 35.3 LO 4/2000', 'poniéndose el hecho en conocimiento inmediato del Ministerio Fiscal, que dispondrá la determinación de su edad', null, '300637682811ef4750d32259f371efd1395f68769af8a155043b38df20f82382', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '300637682811ef4750d32259f371efd1395f68769af8a155043b38df20f82382')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez de menores.', false), ('B', 'La Delegación del Gobierno.', false), ('C', 'El Ministerio Fiscal.', true), ('D', 'La entidad pública de protección de menores.', false)) as v(label, body, ok)
)
