with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5.2.d) de la LO 2/1986, los miembros de las Fuerzas y Cuerpos de Seguridad NO deben utilizar las armas:', 'El art. 5.2.d) limita el uso de las armas a riesgos racionalmente graves para la vida o integridad propia o de terceros, o a graves riesgos para la seguridad ciudadana, conforme a congruencia, oportunidad y proporcionalidad.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2022-1 (n.º 77) · Art. 5.2.d LO 2/1986', 'd) Solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana', null, '7da4554de9d3169f0bd5789f99a2a390138ab10162f43405653c608b682ae0c9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7da4554de9d3169f0bd5789f99a2a390138ab10162f43405653c608b682ae0c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando lo consideren conveniente para asegurar la detención de cualquier sospechoso.', true), ('B', 'Cuando exista un riesgo racionalmente grave para su vida.', false), ('C', 'Ante un peligro racionalmente grave para la integridad física de otras personas.', false), ('D', 'En circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana.', false)) as v(label, body, ok)
)
