with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes funciones NO es común a la Guardia Civil y al Cuerpo Nacional de Policía, sino propia de la Guardia Civil?', 'El art. 12.1.B) atribuye a la Guardia Civil, entre otras, armas y explosivos, resguardo fiscal y vigilancia del tráfico interurbano; las demás son funciones comunes del art. 11.1.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2022-1 (n.º 78) · Arts. 11 y 12 LO 2/1986', 'B) Serán ejercidas por la Guardia Civil: […] c) La vigilancia del tráfico, tránsito y transporte en las vías públicas interurbanas.', null, '6c1337a5d51e739086811578d4566af97d712763f72b6a2f55ac93069683e807', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6c1337a5d51e739086811578d4566af97d712763f72b6a2f55ac93069683e807')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Velar por el cumplimiento de las leyes y disposiciones generales.', false), ('B', 'Auxiliar y proteger a las personas y asegurar la conservación y custodia de los bienes en peligro.', false), ('C', 'La vigilancia del tráfico, tránsito y transporte en las vías públicas interurbanas.', true), ('D', 'Prevenir la comisión de actos delictivos.', false)) as v(label, body, ok)
)
