insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de «Habeas Corpus» (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gcexamen-2022-1', 'Examen réplica 2022, ejercicio 1 · Prueba de conocimientos (100 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gcexamen-2022-1' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el juez de habeas corpus estima que la privación de libertad es ilegal, ¿cuál de las siguientes medidas puede acordar en el acto según el artículo 8.2 de la Ley Orgánica 6/1984?', 'El art. 8.2 prevé la puesta en libertad, la continuación en otro lugar o con otros custodios, y la puesta inmediata a disposición judicial si ha vencido el plazo. La responsabilidad de los autores se persigue deduciendo testimonio (art. 9).', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Réplica 2022-1 (n.º 53) · Art. 8.2 LO 6/1984', 'b) Que continúe la situación de privación de libertad de acuerdo con las disposiciones legales aplicables al caso, pero, si lo considerase necesario, en establecimiento distinto, o bajo la custodia de personas distintas a las que hasta entonces la detentaban.', null, '380f036609c0bb12cb6a118863839454f61c067b962d18919bc8c5bb264bbc44', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '380f036609c0bb12cb6a118863839454f61c067b962d18919bc8c5bb264bbc44')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La imposición de una multa a los agentes que practicaron la detención.', false), ('B', 'La inmediata apertura de juicio oral contra los responsables.', false), ('C', 'Que la privación de libertad continúe, pero en otro establecimiento o bajo la custodia de personas distintas.', true), ('D', 'La suspensión de funciones de los agentes actuantes.', false)) as v(label, body, ok)
)
