with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 60.1 de la Ley Orgánica 3/2007, quienes se incorporen al servicio activo procedentes del permiso de maternidad o paternidad tendrán preferencia en la adjudicación de plazas en los cursos de formación:', 'El art. 60.1 fija la preferencia durante un año, también para quienes reingresen de excedencia por guarda legal y atención a personas mayores dependientes o con discapacidad.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2022-1 (n.º 12) · Art. 60.1 LO 3/2007', 'se otorgará preferencia, durante un año, en la adjudicación de plazas para participar en los cursos de formación a quienes se hayan incorporado al servicio activo procedentes del permiso de maternidad o paternidad', null, 'c8e76b94d0140f2467cc5e918b8ec515897ce5637417a510aacc8815ccac23bc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c8e76b94d0140f2467cc5e918b8ec515897ce5637417a510aacc8815ccac23bc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Durante seis meses.', false), ('B', 'Durante dos años.', false), ('C', 'Mientras dure la reducción de jornada que, en su caso, disfruten.', false), ('D', 'Durante un año.', true)) as v(label, body, ok)
)
