with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, ¿dónde se encomendará a uno de sus órganos directivos el desarrollo de las funciones relacionadas con el principio de igualdad entre mujeres y hombres (Unidades de Igualdad)?', 'El art. 77 crea las Unidades de Igualdad en todos los Ministerios.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2022-1 (n.º 13) · Art. 77 LO 3/2007 (Unidades de Igualdad)', 'En todos los Ministerios se encomendará a uno de sus órganos directivos el desarrollo de las funciones relacionadas con el principio de igualdad entre mujeres y hombres en el ámbito de las materias de su competencia', null, '835c9df1900622dd8ea3689157b9f6d30bd1a20e44095a742829515cf37d9cb3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '835c9df1900622dd8ea3689157b9f6d30bd1a20e44095a742829515cf37d9cb3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo en el Ministerio con competencias en materia de igualdad.', false), ('B', 'En todas las Delegaciones del Gobierno.', false), ('C', 'En todos los Ministerios.', true), ('D', 'En los organismos públicos con más de doscientos empleados.', false)) as v(label, body, ok)
)
