with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los controles en vías, lugares o establecimientos públicos del artículo 17.2 de la LO 4/2015, señale la afirmación INCORRECTA.', 'El art. 17.2 vincula los controles a delitos de especial gravedad o generadores de alarma social, no a cualquier infracción.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2022-1 (n.º 70) · Art. 17.2 LO 4/2015', 'Para la prevención de delitos de especial gravedad o generadores de alarma social, así como para el descubrimiento y detención de quienes hubieran participado en su comisión y proceder a la recogida de los instrumentos, efectos o pruebas, se podrán establecer controles en las vías, lugares o establecimientos públicos, siempre que resulte indispensable proceder a la identificación de personas que se encuentren en ellos, al registro de vehículos o al control superficial de efectos personales.', null, 'e702aa69c13eb7adff97ea9039786564d11913debeaaae1c9546900727429ad3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e702aa69c13eb7adff97ea9039786564d11913debeaaae1c9546900727429ad3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pueden establecerse para prevenir delitos de especial gravedad o generadores de alarma social.', false), ('B', 'Sirven para descubrir y detener a quienes hubieran participado en esos delitos.', false), ('C', 'Exigen que resulte indispensable identificar personas, registrar vehículos o controlar superficialmente efectos personales.', false), ('D', 'Pueden establecerse para prevenir cualquier infracción administrativa leve.', true)) as v(label, body, ok)
)
