with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21.2 de la Ley 39/2015, el plazo máximo para notificar la resolución expresa que fije la norma reguladora del procedimiento no podrá exceder, con carácter general, de:', 'El art. 21.2 LPAC: el plazo es el de la norma reguladora, sin exceder de seis meses salvo ley o Derecho de la UE; si no hay plazo, tres meses (art. 21.3).', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Réplica 2022-1 (n.º 57) · Art. 21.2 Ley 39/2015', 'Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor o así venga previsto en el Derecho de la Unión Europea.', null, '74692a87ce1c4209bcb0c132586a7514ebf9a3f3c8743d960ecb727d74f97abf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '74692a87ce1c4209bcb0c132586a7514ebf9a3f3c8743d960ecb727d74f97abf')
