with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 6/2020, la ley se aplica a los prestadores de servicios electrónicos de confianza residentes o domiciliados en otro Estado que tengan un establecimiento permanente en España:', 'El art. 2 se aplica a los prestadores públicos y privados establecidos en España y a los establecidos permanentemente en España desde otro Estado cuyos servicios no estén supervisados por otra autoridad de la UE.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046'), 'Réplica 2022-1 (n.º 87) · Art. 2 Ley 6/2020', 'Así mismo, se aplicará a los prestadores residentes o domiciliados en otro Estado que tengan un establecimiento permanente situado en España, siempre que ofrezcan servicios no supervisados por la autoridad competente de otro país de la Unión Europea.', null, '86525f8147b98dc3ac77f96c59939018f4565b4cae877847bb56703084f74621', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86525f8147b98dc3ac77f96c59939018f4565b4cae877847bb56703084f74621')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso, con independencia de quién supervise sus servicios.', false), ('B', 'Solo si son prestadores públicos.', false), ('C', 'Solo si sus servicios están supervisados por la autoridad de otro país de la Unión.', false), ('D', 'Siempre que ofrezcan servicios no supervisados por la autoridad competente de otro país de la Unión Europea.', true)) as v(label, body, ok)
)
