with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 26 de la Ley 5/2014, de Seguridad Privada, señale la opción CORRECTA.', 'El art. 26.2: vigilante de explosivos exige la habilitación previa de vigilante de seguridad; guarda de caza y guardapesca marítimo, la de guarda rural.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Réplica 2022-1 (n.º 72) · Art. 26.2 Ley 5/2014', 'Para habilitarse como vigilante de explosivos será necesario haber obtenido previamente la habilitación como vigilante de seguridad. […] Para habilitarse como guarda de caza o guardapesca marítimo será necesario haberlo hecho previamente como guarda rural.', null, '75dd787ebc2933eb4c9651cbafea6953e6e6e92afee68ebe091981b28df0596b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '75dd787ebc2933eb4c9651cbafea6953e6e6e92afee68ebe091981b28df0596b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Para habilitarse como escolta privado es necesario haberlo hecho previamente como guarda rural.', false), ('B', 'Para habilitarse como vigilante de explosivos es necesario haberlo hecho previamente como vigilante de seguridad.', true), ('C', 'Para habilitarse como guarda de caza es necesario haberlo hecho previamente como vigilante de seguridad.', false), ('D', 'Para habilitarse como guarda rural es necesario haberlo hecho previamente como guardapesca marítimo.', false)) as v(label, body, ok)
)
