  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿A qué personal de seguridad privada corresponde la vigilancia y protección de los establecimientos de acuicultura y de las zonas marítimas con fines pesqueros?', 'El art. 34 atribuye a los guardas de caza las fincas de caza y la pesca fluvial, y a los guardapescas marítimos la acuicultura y las zonas marítimas pesqueras.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Réplica 2022-1 (n.º 73) · Art. 34 Ley 5/2014', 'Corresponde a los guardapescas marítimos desempeñar las funciones previstas en el apartado 1 para los guardas rurales y, además, las de vigilancia y protección de los establecimientos de acuicultura y zonas marítimas con fines pesqueros.', null, 'bdd281c27fe294c0c040fe1d8184a407384ff97ddee72791dfb399ea9975d6e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bdd281c27fe294c0c040fe1d8184a407384ff97ddee72791dfb399ea9975d6e2')
  returning id
), o as (
