with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el Consejo previsto en el artículo 9 del Tratado del Atlántico Norte, señale la afirmación INCORRECTA.', 'El art. 9 crea un Consejo con representación de todas las Partes, organizado para reunirse rápidamente en cualquier momento y facultado para crear órganos subsidiarios, en especial un comité de defensa.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1982-12535'), 'Réplica 2022-1 (n.º 34) · Art. 9 Tratado del Atlántico Norte (Consejo)', 'Las Partes establecen por la presente disposición un Consejo, en el que cada una de ellas estará representada, para conocer de las cuestiones relativas a la aplicación del Tratado. El Consejo estará organizado de manera que pueda reunirse rápidamente en cualquier momento. El Consejo establecerá cuantos órganos subsidiarios puedan ser necesarios; y en especial establecerá inmediatamente un comité de defensa', null, '4fad30ed23f03a60f7e14119c9a292ffb85372364a4b780a16955d75412f51c2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4fad30ed23f03a60f7e14119c9a292ffb85372364a4b780a16955d75412f51c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Está presidido por el Comandante Supremo Aliado y solo se reúne una vez al año.', true), ('B', 'En él está representada cada una de las Partes.', false), ('C', 'Debe estar organizado de manera que pueda reunirse rápidamente en cualquier momento.', false), ('D', 'Debe establecer de inmediato un comité de defensa.', false)) as v(label, body, ok)
)
