with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué órgano de los Servicios Centrales de la Dirección General de la Guardia Civil, al mando de un oficial general, es responsable de facilitar la labor de los órganos de evaluación aportando la documentación de los evaluados?', 'El art. 23 de la Orden PRE/422/2013 atribuye esta función a la Secretaría Permanente para la Clasificación y Evaluación, dependiente del Mando de Personal.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906'), 'Réplica 2022-1 (n.º 79) · Art. 23 Orden PRE/422/2013', 'La Secretaría Permanente para la Clasificación y Evaluación, al mando de un Oficial General de la Guardia Civil, es el órgano responsable de facilitar la labor de los órganos de evaluación, para lo cual aportará la documentación de los miembros a evaluar', null, 'd9b3130f016a3592c5e6e3274f3da4667f87ef5a15f86b23709f1c4ecfdb33f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd9b3130f016a3592c5e6e3274f3da4667f87ef5a15f86b23709f1c4ecfdb33f2')
