insert into public.sources (title, url, kind, publisher, published_on) values ('Pacto Internacional de Derechos Civiles y Políticos (Instrumento de Ratificación de España) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10733', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gcexamen-2022-1', 'Examen réplica 2022, ejercicio 1 · Prueba de conocimientos (100 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gcexamen-2022-1' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En materia de pena de muerte, el artículo 6 del Pacto Internacional de Derechos Civiles y Políticos establece que:', 'El art. 6.5 fija el límite en los dieciocho años y excluye a las mujeres en estado de gravidez; el 6.4 permite amnistía, indulto o conmutación en todos los casos; el 6.2 la reserva a los más graves delitos.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10733'), 'Réplica 2022-1 (n.º 7) · Art. 6 PIDCP', 'No se impondrá la pena de muerte por delitos cometidos por personas de menos de dieciocho años de edad, ni se la aplicará a las mujeres en estado de gravidez.', null, 'd30fac8c4b7083b213bdfce085867a730dd85f81073530c6aee5e8807480ab58', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd30fac8c4b7083b213bdfce085867a730dd85f81073530c6aee5e8807480ab58')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No se impondrá por delitos cometidos por menores de veintiún años.', false), ('B', 'Solo podrá conmutarse en los casos de delitos políticos.', false), ('C', 'No se impondrá por delitos cometidos por menores de dieciocho años ni se aplicará a mujeres embarazadas.', true), ('D', 'Podrá imponerse por cualquier delito en los países que no la hayan abolido.', false)) as v(label, body, ok)
)
