insert into public.sources (title, url, kind, publisher, published_on) values ('Pacto Internacional de Derechos Económicos, Sociales y Culturales (Instrumento de Ratificación de España) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10734', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
