  select 'Respecto de los funcionarios de las Unidades Orgánicas de Policía Judicial, señale la afirmación INCORRECTA según el Real Decreto 769/1987.', 'El art. 16 impide removerlos o apartarlos de la investigación hasta que finalice, salvo decisión o autorización del juez o fiscal competente.', 'gcexamen_2022_1', (select id from public.topics where slug = 'gcexamen-2022-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14578'), 'Réplica 2022-1 (n.º 56) · Arts. 15-17 RD 769/1987', 'Los funcionarios de las Unidades Orgánicas de la Policía Judicial no podrán ser removidos o apartados de la investigación concreta que se les hubiere encomendado, hasta que finalice la misma o la fase procesal que la originó, si no es por decisión o con la autorización del Juez o Fiscal competente.', null, '1b287fb72016bb1ebcc141efdcef11d8f51cda5578adb6601391f657d85a913e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1b287fb72016bb1ebcc141efdcef11d8f51cda5578adb6601391f657d85a913e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Su jefe de unidad puede apartarlos de una investigación concreta en cualquier momento sin necesidad de autorización judicial o fiscal.', true), ('B', 'Deben guardar rigurosa reserva sobre la evolución y resultados de las investigaciones encomendadas.', false), ('C', 'La reserva no impide, salvo prohibición expresa del juez o fiscal, el intercambio interno de información en la unidad.', false), ('D', 'Si deben cesar en su destino por causas legales, su cese se comunica a la autoridad judicial o fiscal.', false)) as v(label, body, ok)
)
