with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Civil, el domicilio de los diplomáticos residentes por razón de su cargo en el extranjero que gocen del derecho de extraterritorialidad es:', 'Regla especial del art. 40, párrafo segundo, del Código Civil.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2022-2 (n.º 37) · Art. 40 Código Civil', 'El domicilio de los diplomáticos residentes por razón de su cargo en el extranjero, que gocen del derecho de extraterritorialidad, será el último que hubieren tenido en territorio español.', null, '03de23e79b7060bea13d108736f67348d83f475234315cfd2827215a45556452', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '03de23e79b7060bea13d108736f67348d83f475234315cfd2827215a45556452')
  returning id
), o as (
