with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el matrimonio en el Código Civil, señale la opción CORRECTA:', 'Art. 46 CC. El matrimonio en peligro de muerte no requiere previa tramitación del acta o expediente (art. 52), el secreto exige causa grave suficientemente probada (art. 54) y la promesa incumplida obliga a resarcir gastos y obligaciones contraídas (art. 43).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2022-2 (n.º 38) · Arts. 43, 46, 52 y 54 Código Civil', 'No pueden contraer matrimonio: […] Los menores de edad no emancipados.', null, '646a19f93e1bcdf050b9e30af17bc7896cfc66ce7a481a25dde0337870d1a69e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '646a19f93e1bcdf050b9e30af17bc7896cfc66ce7a481a25dde0337870d1a69e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El matrimonio en peligro de muerte exige la previa tramitación del acta o expediente matrimonial.', false), ('B', 'El Ministro de Justicia puede autorizar el matrimonio secreto por cualquier causa.', false), ('C', 'El incumplimiento sin causa de la promesa cierta de matrimonio no genera obligación alguna de resarcir gastos.', false), ('D', 'Los menores que no estén emancipados no pueden casarse.', true)) as v(label, body, ok)
)
