with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los alimentos entre parientes en el Código Civil, señale la opción CORRECTA:', 'Art. 148 CC. La cuantía se proporciona al caudal de quien los da y a las necesidades de quien los recibe (art. 146), la educación se incluye aun después de la mayoría de edad si no ha terminado la formación por causa no imputable (art. 142) y no son compensables (art. 151).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2022-2 (n.º 39) · Arts. 142, 146, 148 y 151 Código Civil', 'La obligación de dar alimentos será exigible desde que los necesitare, para subsistir, la persona que tenga derecho a percibirlos, pero no se abonarán sino desde la fecha en que se interponga la demanda.', null, 'f9e69b539862ffb1bd34103de3f8f604b76bcbdbcfcd15cbcc91117d91111b83', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f9e69b539862ffb1bd34103de3f8f604b76bcbdbcfcd15cbcc91117d91111b83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Su cuantía es proporcionada únicamente a las necesidades de quien los recibe.', false), ('B', 'Incluyen la educación e instrucción del alimentista solo mientras sea menor de edad.', false), ('C', 'Son exigibles desde que los necesite para subsistir quien tiene derecho a ellos, pero solo se abonan desde la fecha en que se interponga la demanda.', true), ('D', 'Pueden compensarse con lo que el alimentista deba a quien ha de prestarlos.', false)) as v(label, body, ok)
)
