with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la mayor edad y la emancipación en el Código Civil, señale la opción INCORRECTA:', 'El art. 243 CC permite a los progenitores revocar ese consentimiento. Las demás reproducen los arts. 240 y 246 (numeración dada por la Ley 8/2021).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2022-2 (n.º 40) · Arts. 240-246 Código Civil', 'Se reputará para todos los efectos como emancipado al hijo mayor de dieciséis años que, con el consentimiento de los progenitores, viviere independientemente de estos. Los progenitores podrán revocar este consentimiento.', null, '8c32ddaef6384bc5050321a8bcf131656a7aa7f1e12ed5ab1d5a0b95d2ac94ae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8c32ddaef6384bc5050321a8bcf131656a7aa7f1e12ed5ab1d5a0b95d2ac94ae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La mayor edad empieza a los dieciocho años cumplidos.', false), ('B', 'Al hijo mayor de dieciséis años que vive independientemente con el consentimiento de sus progenitores se le reputa emancipado, y ese consentimiento es irrevocable.', true), ('C', 'En el cómputo de los años de la mayoría de edad se incluye completo el día del nacimiento.', false), ('D', 'El mayor de edad puede realizar todos los actos de la vida civil, salvo las excepciones establecidas en casos especiales por el Código.', false)) as v(label, body, ok)
)
