with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la información oficial del CCN-CERT, ¿cuál de los siguientes NO figura entre los incidentes prioritarios para el CCN-CERT?', 'Son prioritarios los incidentes que afectan a información clasificada, el ciberespionaje, la interrupción de servicios IT, la exfiltración de datos, los servicios comprometidos, la toma de control de sistemas, el robo y publicación de información, el ciberdelito y la suplantación de identidad.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/sobre-nosotros/mision-y-objetivos.html'), 'Réplica 2022-2 (n.º 88) · CCN-CERT: incidentes prioritarios', '¿Cuáles son los incidentes prioritarios para CCN-CERT? Incidentes que afecten a información clasificada Ciberespionaje: APTs, campañas de malware, incidentes especiales Interrupción de los Servicios IT Exfiltración de datos Existencia de algún servicio comprometido Toma de control de algún sistema Robo y publicación o venta de información sustraído Ciberdelito Suplantación de identidad', null, 'a5ff57f4d6f75321f0d8f3f0a80a31da4a3d8e150f87343bb5af92ec267fd838', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a5ff57f4d6f75321f0d8f3f0a80a31da4a3d8e150f87343bb5af92ec267fd838')
  returning id
), o as (
