with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la información oficial del CCN-CERT, las Administraciones Públicas deben notificar obligatoriamente al CCN-CERT, en cumplimiento del Esquema Nacional de Seguridad, los incidentes catalogados con nivel de peligrosidad:', 'La FAQ del CCN-CERT remite a la Guía CCN-STIC 817: son de obligada notificación los incidentes de peligrosidad Alto, Muy Alto y Crítico.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/sobre-nosotros/mision-y-objetivos.html'), 'Réplica 2022-2 (n.º 89) · CCN-CERT: notificación obligatoria', 'Las Administraciones Públicas y en virtud del cumplimiento del Esquema Nacional de Seguridad, deben notificar al CCN-CERT todos aquellos incidentes que sean catalogados con un nivel de peligrosidad de Alto, Muy Alto y Crítico.', null, '91fca5d95c164f16d250247f33688bc79b5f9ce77aa5b5f7c5d6cf86c8aa87fa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91fca5d95c164f16d250247f33688bc79b5f9ce77aa5b5f7c5d6cf86c8aa87fa')
  returning id
