with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los partidos políticos en la Constitución Española, señale la opción INCORRECTA:', 'La defensa de los intereses económicos y sociales propios es la función que el art. 7 CE atribuye a sindicatos y asociaciones empresariales, no a los partidos (art. 6).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2022-2 (n.º 15) · Art. 6 CE', 'Los partidos políticos expresan el pluralismo político, concurren a la formación y manifestación de la voluntad popular y son instrumento fundamental para la participación política. Su creación y el ejercicio de su actividad son libres dentro del respeto a la Constitución y a la ley. Su estructura interna y funcionamiento deberán ser democráticos.', null, '496c2cfa8fd746d7e5aee77f543a75ef814884d072e8b75bebab2d7c0e77f32c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '496c2cfa8fd746d7e5aee77f543a75ef814884d072e8b75bebab2d7c0e77f32c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Expresan el pluralismo político y son instrumento fundamental para la participación política.', false), ('B', 'Su estructura interna y funcionamiento deberán ser democráticos.', false), ('C', 'Su creación y el ejercicio de su actividad son libres dentro del respeto a la Constitución y a la ley.', false), ('D', 'Contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios.', true)) as v(label, body, ok)
)
