with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 97 de la Constitución, ¿cuál de las siguientes NO es una función del Gobierno?', 'La potestad legislativa corresponde a las Cortes Generales (art. 66.2 CE); el art. 97 atribuye al Gobierno la dirección de la política, de la Administración civil y militar y de la defensa, la función ejecutiva y la potestad reglamentaria.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2022-2 (n.º 17) · Art. 97 CE', 'El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.', null, '5fb1257b776e9bab7b9b6bde1ddb8857fff6f3847f91bb7c97c4d74a48853623', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5fb1257b776e9bab7b9b6bde1ddb8857fff6f3847f91bb7c97c4d74a48853623')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dirigir la política interior y exterior.', false), ('B', 'Dirigir la Administración militar.', false), ('C', 'Ejercer la potestad reglamentaria de acuerdo con la Constitución y las leyes.', false), ('D', 'Ejercer la potestad legislativa del Estado.', true)) as v(label, body, ok)
)
