  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 103.1 de la Constitución, la Administración Pública actúa de acuerdo con los principios de:', 'El art. 103.1 CE enumera cinco principios: eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2022-2 (n.º 18) · Art. 103.1 CE', 'La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.', null, 'ae3ea7b4fd77e5f5051f1cdb6d866206fb2c09fd31b736aaa5429e140216fe87', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae3ea7b4fd77e5f5051f1cdb6d866206fb2c09fd31b736aaa5429e140216fe87')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
