with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, señale la opción CORRECTA:', 'Art. 21.4.ª CP. La grave adicción es atenuante (21.2.ª), el miedo insuperable es eximente (art. 20.6.º) y la reparación debe ser anterior al juicio oral (21.5.ª).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2022-2 (n.º 42) · Art. 21 Código Penal', '4.ª La de haber procedido el culpable, antes de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades.', null, 'a4f44339e990fe02face3567f3565acb59c9e4fe355a25e54a356c79533428c0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a4f44339e990fe02face3567f3565acb59c9e4fe355a25e54a356c79533428c0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Actuar a causa de grave adicción a las drogas tóxicas es siempre una circunstancia eximente.', false), ('B', 'Obrar impulsado por un miedo insuperable es una circunstancia atenuante.', false), ('C', 'La reparación del daño a la víctima es atenuante aunque se produzca después del juicio oral.', false), ('D', 'La confesión de la infracción a las autoridades antes de conocer que el procedimiento judicial se dirige contra el culpable es una circunstancia atenuante.', true)) as v(label, body, ok)
)
