  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La autoridad que, en el ejercicio de su competencia y a sabiendas de su ilegalidad, nombra para un cargo público a una persona que no reúne los requisitos legales, comete un delito incluido en el capítulo del Código Penal dedicado a:', 'El art. 405 CP (nombramientos ilegales) está en el capítulo I del título XIX, junto a la prevaricación del art. 404.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2022-2 (n.º 46) · Art. 405 Código Penal', 'CAPÍTULO I. De la prevaricación de los funcionarios públicos y otros comportamientos injustos […] A la autoridad o funcionario público que, en el ejercicio de su competencia y a sabiendas de su ilegalidad, propusiere, nombrare o diere posesión para el ejercicio de un determinado cargo público a cualquier persona sin que concurran los requisitos legalmente establecidos para ello', null, '68ea3c7e9923e1c6b326e32f39d3ad0b5d9b9d2e4ceaaeff625ceaa1ba54acc4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '68ea3c7e9923e1c6b326e32f39d3ad0b5d9b9d2e4ceaaeff625ceaa1ba54acc4')
  returning id
