with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las libertades de expresión e información y de reunión y asociación en la Carta de los Derechos Fundamentales de la UE, señale la opción INCORRECTA:', 'El art. 12.1 menciona «especialmente» los ámbitos político, sindical y cívico. Las demás opciones reproducen los arts. 11.1, 11.2 y 12.2.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016P/TXT'), 'Réplica 2022-2 (n.º 9) · Arts. 11-12 Carta de los Derechos Fundamentales de la UE', 'Toda persona tiene derecho a la libertad de reunión pacífica y a la libertad de asociación en todos los niveles, especialmente en los ámbitos político, sindical y cívico', null, '8c1e22238abee27f75576ca1876af98e11206e488fc0a0aadffa7e20e8e36b02', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8c1e22238abee27f75576ca1876af98e11206e488fc0a0aadffa7e20e8e36b02')
