  select 'En relación con los derechos de la Declaración Universal de Derechos Humanos, señale la opción INCORRECTA:', 'El art. 14.2 DUDH excluye el asilo frente a acciones judiciales realmente originadas por delitos comunes o por actos contrarios a los propósitos y principios de la ONU. Las demás reproducen los arts. 23.1, 21.1 y 13.1.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Réplica 2022-2 (n.º 3) · Art. 14 DUDH', '1. En caso de persecución, toda persona tiene derecho a buscar asilo, y a disfrutar de él, en cualquier país. 2. Este derecho no podrá ser invocado contra una acción judicial realmente originada por delitos comunes o por actos opuestos a los propósitos y principios de las Naciones Unidas', null, 'c3e77c7eb5cf58ff990d6209e8b4343f3b5264e081de2f046c9e140d1c5d3e8b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c3e77c7eb5cf58ff990d6209e8b4343f3b5264e081de2f046c9e140d1c5d3e8b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda persona tiene derecho al trabajo, a su libre elección y a la protección contra el desempleo.', false), ('B', 'Toda persona tiene derecho a participar en el gobierno de su país, directamente o por medio de representantes libremente escogidos.', false), ('C', 'Toda persona tiene derecho a circular libremente y a elegir su residencia en el territorio de un Estado.', false), ('D', 'El derecho de asilo puede invocarse en todo caso, incluso frente a una acción judicial originada por delitos comunes.', true)) as v(label, body, ok)
)
