with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el objeto y ámbito de aplicación de la Directiva 2012/27/UE, relativa a la eficiencia energética, señale la opción INCORRECTA:', 'El art. 1.2 obliga a notificar esas disposiciones a la Comisión. Las demás reproducen el art. 1.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504'), 'Réplica 2022-2 (n.º 85) · Art. 1 Directiva 2012/27/UE', 'Cuando las disposiciones de la legislación nacional establezcan medidas más estrictas, los Estados miembros notificarán dichas disposiciones a la Comisión.', 'La Directiva 2012/27/UE fue derogada con efectos de 12/10/2025 por la Directiva (UE) 2023/1791; el temario vigente sigue citándola, y se pregunta por su último texto consolidado.', 'f9c3cd3dc5aafb4b93a01a3d47f02f44664e3bdd605111be90ce26bf1e56478c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f9c3cd3dc5aafb4b93a01a3d47f02f44664e3bdd605111be90ce26bf1e56478c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si un Estado miembro establece medidas más estrictas, debe notificarlas al Parlamento Europeo.', true), ('B', 'Sus requisitos son mínimos y no impiden que un Estado miembro mantenga o introduzca medidas más estrictas.', false), ('C', 'Las medidas nacionales más estrictas deben ser compatibles con el Derecho de la Unión.', false), ('D', 'Establece normas para eliminar barreras en el mercado de la energía que obstaculizan la eficiencia en el abastecimiento y el consumo.', false)) as v(label, body, ok)
)
