with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 4 del Tratado de Funcionamiento de la Unión Europea, ¿cuál de los siguientes NO es un ámbito principal de competencia compartida entre la Unión y los Estados miembros?', 'La política comercial común es competencia exclusiva de la Unión (art. 3.1.e TFUE); las demás figuran en el art. 4.2 como competencias compartidas.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016E/TXT'), 'Réplica 2022-2 (n.º 30) · Art. 4.2 TFUE', 'e) la política comercial común. […] 2. Las competencias compartidas entre la Unión y los Estados miembros se aplicarán a los siguientes ámbitos principales: […] f) la protección de los consumidores; […] i) la energía; j) el espacio de libertad, seguridad y justicia;', null, '47b3689ea95cdc893dd0aefb08e44b5b538c9c6943748ea623547fda5e56ab4b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47b3689ea95cdc893dd0aefb08e44b5b538c9c6943748ea623547fda5e56ab4b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La política comercial común.', true), ('B', 'El espacio de libertad, seguridad y justicia.', false), ('C', 'La protección de los consumidores.', false), ('D', 'La energía.', false)) as v(label, body, ok)
)
