with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO es una institución ni un órgano de la Unión Europea?', 'El art. 13.1 TUE enumera las siete instituciones (entre ellas el BCE y el Tribunal de Cuentas) y el art. 300 TFUE crea dos órganos consultivos: el Comité Económico y Social y el Comité de las Regiones. El órgano de la primera opción no existe en la Unión.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Réplica 2022-2 (n.º 32) · Art. 13.1 TUE y art. 300 TFUE', 'Las instituciones de la Unión son: El Parlamento Europeo, El Consejo Europeo, El Consejo, La Comisión Europea (denominada en lo sucesivo "Comisión"), El Tribunal de Justicia de la Unión Europea, El Banco Central Europeo, El Tribunal de Cuentas.', null, 'd10082ce10eb1279fda49d1dbf047b0173666283c283d90fbeea68c71e876bf9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd10082ce10eb1279fda49d1dbf047b0173666283c283d90fbeea68c71e876bf9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Tribunal de Cuentas.', false), ('B', 'El Consejo Europeo de Derechos Sociales y Culturales.', true), ('C', 'El Banco Central Europeo.', false), ('D', 'El Comité de las Regiones.', false)) as v(label, body, ok)
)
