with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las disposiciones del Tratado de la Unión Europea relativas a los principios democráticos, señale la opción INCORRECTA:', 'El art. 10.4 TUE: los partidos políticos a escala europea contribuyen a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión. Las demás reproducen los arts. 10.3, 9 y 11.3.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016M/TXT'), 'Réplica 2022-2 (n.º 26) · Arts. 9-11 TUE', '4. Los partidos políticos a escala europea contribuirán a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión.', null, 'f1326f5d3ca44f79b449bb391cc5229537ea6be56471c6032a44c795eb47fd7d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f1326f5d3ca44f79b449bb391cc5229537ea6be56471c6032a44c795eb47fd7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Todo ciudadano tiene derecho a participar en la vida democrática de la Unión.', false), ('B', 'La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla.', false), ('C', 'Los partidos políticos a escala europea contribuyen a expresar la voluntad de los Gobiernos de los Estados miembros.', true), ('D', 'La Comisión Europea mantendrá amplias consultas con las partes interesadas para garantizar la coherencia y la transparencia de las acciones de la Unión.', false)) as v(label, body, ok)
)
