select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los principios que rigen las competencias de la Unión según el artículo 5 del Tratado de la Unión Europea, señale la opción CORRECTA:', 'Principio de atribución (art. 5.2 TUE). La subsidiariedad opera en los ámbitos que no son de competencia exclusiva, la delimitación se rige por la atribución (subsidiariedad y proporcionalidad rigen el ejercicio) y los Parlamentos nacionales también velan por la subsidiariedad.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016M/TXT'), 'Réplica 2022-2 (n.º 27) · Art. 5 TUE', 'En virtud del principio de atribución, la Unión actúa dentro de los límites de las competencias que le atribuyen los Estados miembros en los Tratados para lograr los objetivos que éstos determinan. Toda competencia no atribuida a la Unión en los Tratados corresponde a los Estados miembros.', null, '6fb0485a4d0ecbb8f60c5a4f431101f6f80e15fdc64d9e99615a42ab7cbc64a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6fb0485a4d0ecbb8f60c5a4f431101f6f80e15fdc64d9e99615a42ab7cbc64a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda competencia no atribuida a la Unión en los Tratados corresponde a los Estados miembros.', true), ('B', 'El principio de subsidiariedad se aplica también en los ámbitos de competencia exclusiva de la Unión.', false), ('C', 'La delimitación de las competencias de la Unión se rige por el principio de proporcionalidad.', false), ('D', 'Velar por el respeto del principio de subsidiariedad corresponde exclusivamente al Tribunal de Justicia.', false)) as v(label, body, ok)
)
