with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la escala de un mapa, señale la afirmación INCORRECTA:', 'A escala 1:25.000, 1 cm = 25.000 cm = 250 m; 4 cm = 1.000 m = 1 km, no 10 km. Las demás reproducen la explicación del IGN.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.ign.es/resources/acercaDe/libDigPub/tu-amigo-el-mapa.pdf'), 'Réplica 2022-2 (n.º 97) · Escala (IGN), cálculo', 'si en un mapa se indica que la escala es 1:50.000, se está indicando que la relación entre la longitud de una línea en el mapa y su correspondiente en el terreno es 50.000 veces. Entonces, a una línea de un centímetro en el mapa le corresponde en el terreno una longitud de 50.000 veces un centímetro, es decir, 500 metros.', null, 'c1cff72843cb09953484cdd2f390d05e1b858356c77c6bb6f0f0ea6334f0dc1b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c1cff72843cb09953484cdd2f390d05e1b858356c77c6bb6f0f0ea6334f0dc1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En un mapa a escala 1:50.000, un centímetro en el mapa equivale a 500 metros en el terreno.', false), ('B', 'Cuanto mayor es el denominador de la escala, mayor es la extensión de terreno que abarca un mapa del mismo tamaño.', false), ('C', 'Un mapa a escala 1:25.000 representa con más detalle la estructura urbana que uno a escala 1:200.000.', false), ('D', 'En un mapa a escala 1:25.000, una línea de 4 cm en el mapa equivale a 10 km en el terreno.', true)) as v(label, body, ok)
)
