with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Instituto Geográfico Nacional, ¿cuáles son los elementos imprescindibles que deben aparecer en todos los mapas?', 'El IGN señala como imprescindibles la escala (relación métrica entre el mapa y la realidad) y la leyenda.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.ign.es/web/resources/cartografiaEnsenanza/conceptosCarto/descargas/Conceptos_Cartograficos_def.pdf'), 'Réplica 2022-2 (n.º 93) · Elementos de un mapa (IGN)', 'Los elementos imprescindibles que deben aparecer en todos los mapas son: la escala utilizada y la leyenda.', null, '2117acdd05e52118097a66814ee60088fba85b5485af0a829138f56764bc5f3c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2117acdd05e52118097a66814ee60088fba85b5485af0a829138f56764bc5f3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La altitud y la equidistancia.', false), ('B', 'La escala utilizada y la leyenda.', true), ('C', 'La cuadrícula UTM y la declinación magnética.', false), ('D', 'El título y el nombre del autor.', false)) as v(label, body, ok)
)
