with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Instituto Geográfico Nacional, la diferencia de dirección entre el Norte geográfico y el Norte magnético, que varía con el tiempo y figura en los márgenes de sus mapas, se denomina:', 'La declinación magnética es la diferencia entre el Norte geográfico (verdadero) y el Norte magnético que marca la brújula; el IGN la publica en los márgenes de sus mapas con su variación anual. Si es Este se resta del valor de la brújula y si es Oeste se suma.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.ign.es/recursos-educativos/descubre-territorio/brujula.html'), 'Réplica 2022-2 (n.º 90) · Declinación magnética (IGN)', 'deberíamos corregir la brújula del efecto de la declinación magnética. El Norte geográfico y el Norte magnético no tienen exactamente la misma dirección, debido al magnetismo terrestre, y además, esta diferencia varía con el tiempo. En los márgenes de los mapas del Instituto Geográfico Nacional puedes encontrar la declinación magnética del momento en que se realizó el mapa y su variación anual', null, '342cabd3b9c815841bfa3a8ae06005f63702222cc7b1dd9c814cc95d6e3553c8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '342cabd3b9c815841bfa3a8ae06005f63702222cc7b1dd9c814cc95d6e3553c8')
  returning id
), o as (
