with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el glosario del Instituto Geográfico Nacional, señale la definición INCORRECTA:', 'Para el IGN la rambla es un cauce normalmente seco, en ámbitos semiáridos y áridos, que lleva agua cuando llueve.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'Réplica 2022-2 (n.º 91) · Formas del relieve (glosario del IGN)', 'Rambla (Hidrografía) Cauce normalmente seco, en ámbitos semiáridos y áridos, y que presenta aguas corrientes cuando ocurren precipitaciones.', null, 'a4f88648ad18303039fc0ae84e42ed3fd5b018f3e84352d994fca2c224d87827', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a4f88648ad18303039fc0ae84e42ed3fd5b018f3e84352d994fca2c224d87827')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Divisoria de aguas: línea que une los puntos en los que las aguas fluyen hacia cuencas hidrográficas diferentes.', false), ('B', 'Hoz: angostura de un valle profundo o curva que forma un río encajado entre paredes abruptas.', false), ('C', 'Cuenca hidrográfica: espacio entre divisorias de agua recorrido por un río principal y sus afluentes.', false), ('D', 'Rambla: cauce con agua permanente propio de zonas lluviosas.', true)) as v(label, body, ok)
)
