with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Instituto Geográfico Nacional, sobre la altitud señale la opción CORRECTA:', 'La altitud se mide desde el nivel medio del mar (en la península, con referencia en Alicante); la diferencia constante entre curvas de nivel consecutivas es la equidistancia.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'Réplica 2022-2 (n.º 100) · Altitud y su unidad (IGN)', 'Altitud (Relieve) Distancia vertical de un punto de la superficie terrestre respecto al nivel del mar (tomándose como referencia una posición media). Se expresa en "metros sobre el nivel del mar" (m.s.n.m.).', null, '302e748f8771dfa5364809bd336b1f890010b2c135f4062f25da7c85860812f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '302e748f8771dfa5364809bd336b1f890010b2c135f4062f25da7c85860812f2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es la distancia vertical de un punto respecto al nivel del mar y se expresa en metros sobre el nivel del mar (m.s.n.m.).', true), ('B', 'Es la distancia horizontal de un punto al Ecuador y se expresa en grados.', false), ('C', 'Es la distancia de un punto al meridiano de Greenwich y se expresa en kilómetros.', false), ('D', 'Es la diferencia de altura entre dos curvas de nivel consecutivas y se expresa en hectómetros.', false)) as v(label, body, ok)
)
