  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 259 de la Ley de Enjuiciamiento Criminal, quien presencie la perpetración de un delito público debe ponerlo en conocimiento de alguna de estas autoridades más próxima. Señale la que NO menciona el precepto:', 'El art. 259 menciona al Juez de instrucción, de paz, comarcal o municipal o funcionario fiscal más próximo.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-2 (n.º 50) · Art. 259 LECrim', 'está obligado a ponerlo inmediatamente en conocimiento del Juez de instrucción, de paz, comarcal o municipal o funcionario fiscal más próximo al sitio en que se hallare', null, '228aabdf2b039e107b5bfcaf5ec417e16250cc5772a4122cc17a410b8abbdde2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '228aabdf2b039e107b5bfcaf5ec417e16250cc5772a4122cc17a410b8abbdde2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Juez de instrucción.', false), ('B', 'El Juez de paz.', false), ('C', 'El funcionario fiscal.', false), ('D', 'El Juez de lo Penal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el abogado designado no comparece en el centro de detención en plazo y el Colegio de Abogados designa a otro del turno de oficio, ¿cuándo debe comparecer el nuevo abogado?', 'El art. 520.5 LECrim fija tres horas desde la recepción del encargo; el nuevo abogado debe comparecer a la mayor brevedad y dentro de ese mismo plazo.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-2 (n.º 51) · Art. 520.5 LECrim', 'El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo. Si en dicho plazo no compareciera, el Colegio de Abogados designará un nuevo abogado del turno de oficio que deberá comparecer a la mayor brevedad y siempre dentro del plazo indicado', null, 'f40b325725f78c4cb8357554b928c66250603cb7e9354c18353d20f87ef91981', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f40b325725f78c4cb8357554b928c66250603cb7e9354c18353d20f87ef91981')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo máximo de ocho horas desde la detención.', false), ('B', 'En el plazo de veinticuatro horas desde su designación.', false), ('C', 'Lo antes posible y, en todo caso, en un máximo de tres horas desde que recibe el encargo.', true), ('D', 'En el plazo de una hora, bajo apercibimiento de sanción.', false)) as v(label, body, ok)
)
