with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Señale la opción INCORRECTA sobre el ámbito competencial del Defensor del Pueblo:', 'Según el art. 13 LO 3/1981, esas quejas se dirigen al Ministerio Fiscal o se trasladan al Consejo General del Poder Judicial. Las demás opciones reproducen los arts. 14, 12.1 y 12.2.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Réplica 2022-2 (n.º 25) · Arts. 12-14 LO 3/1981', 'Cuando el Defensor del Pueblo reciba quejas referidas al funcionamiento de la Administración de Justicia, deberá dirigirlas al Ministerio Fiscal para que éste investigue su realidad y adopte las medidas oportunas con arreglo a la ley, o bien dé traslado de las mismas al Consejo General del Poder Judicial, según el tipo de reclamación de que se trate', null, 'a377624857f115b9a0ff74c062b5df404fb73dfa744515d8bdc7eede27abf4ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a377624857f115b9a0ff74c062b5df404fb73dfa744515d8bdc7eede27abf4ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vela por el respeto de los derechos del título primero de la Constitución en el ámbito de la Administración Militar, sin interferir en el mando de la Defensa Nacional.', false), ('B', 'Las quejas sobre el funcionamiento de la Administración de Justicia las remite al Ministerio de Justicia o al Tribunal Supremo, según su naturaleza.', true), ('C', 'Puede, en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias de su ley.', false), ('D', 'Los órganos similares de las Comunidades Autónomas coordinan sus funciones con las suyas y él puede solicitar su cooperación.', false)) as v(label, body, ok)
)
