with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué cambio NO están obligados a comunicar a las autoridades competentes, según el artículo 31 de la Ley Orgánica 4/2000, los extranjeros con autorización de residencia temporal?', 'El art. 31.6 LOEX impone comunicar los cambios de nacionalidad, estado civil y domicilio.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-2 (n.º 67) · Art. 31.6 LO 4/2000', 'Los extranjeros con autorización de residencia temporal vendrán obligados a poner en conocimiento de las autoridades competentes los cambios de nacionalidad, estado civil y domicilio.', null, '79220ad731abfa2b96ab106f32f8317295e88365c2ddc19d513f55563a4f7b45', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '79220ad731abfa2b96ab106f32f8317295e88365c2ddc19d513f55563a4f7b45')
