  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2000, ¿cuándo prescriben las infracciones graves?', 'Art. 56.1 LOEX: muy graves a los tres años, graves a los dos años y leves a los seis meses.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-2 (n.º 68) · Art. 56.1 LO 4/2000', 'Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses.', null, '0910403ad7f648abfe673e390e51088a21905d405864b9275ad078350f953154', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0910403ad7f648abfe673e390e51088a21905d405864b9275ad078350f953154')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
