with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al principio básico de actuación de «dedicación profesional» de la Ley Orgánica 2/1986, los miembros de las Fuerzas y Cuerpos de Seguridad deben intervenir en defensa de la Ley y de la seguridad ciudadana:', 'Art. 5.4 LO 2/1986.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2022-2 (n.º 77) · Art. 5.4 LO 2/1986', 'Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana.', null, '7504177dfe69f37deff6d17adf0832c78ee9e4fa00a12121bebe6d53cf7bb2e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7504177dfe69f37deff6d17adf0832c78ee9e4fa00a12121bebe6d53cf7bb2e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo cuando estén de servicio, en cualquier lugar.', false), ('B', 'Siempre, en cualquier tiempo y lugar, se hallen o no de servicio.', true), ('C', 'Solo en su demarcación, se hallen o no de servicio.', false), ('D', 'Solo en su demarcación y cuando estén de servicio.', false)) as v(label, body, ok)
)
