with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el ámbito de actuación de los Cuerpos de Policía de las Comunidades Autónomas, señale la opción CORRECTA:', 'Art. 42 LO 2/1986.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2022-2 (n.º 78) · Art. 42 LO 2/1986', 'Los cuerpos de policía de las comunidades autónomas sólo podrán actuar en el ámbito territorial de la comunidad autónoma respectiva, salvo en situaciones de emergencia, previo requerimiento de las autoridades estatales. No obstante, cuando ejerzan funciones de protección de autoridades públicas de la comunidad autónoma, podrán actuar fuera del ámbito territorial respectivo, previa autorización del Ministerio del Interior', null, '52844e12aa0f0586f46ded20c59d84014cb7407ffc74be3287b07f067018080e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '52844e12aa0f0586f46ded20c59d84014cb7407ffc74be3287b07f067018080e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fuera de su comunidad solo pueden actuar en situaciones de emergencia, previo requerimiento de las autoridades estatales, o en funciones de protección de autoridades autonómicas con autorización del Ministerio del Interior.', true), ('B', 'Pueden actuar fuera de su comunidad cuando lo consideren necesario, con simple comunicación al Ministerio del Interior.', false), ('C', 'Nunca pueden actuar fuera del territorio de su comunidad.', false), ('D', 'Para proteger a autoridades autonómicas fuera de la comunidad basta la autorización del Gobierno autonómico.', false)) as v(label, body, ok)
)
