with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el procedimiento de «Habeas Corpus», señale la opción INCORRECTA:', 'El art. 4 LO 6/1984 dispone que no es preceptiva la intervención de Abogado ni de Procurador. Las demás opciones reproducen los arts. 4, 6 y 7.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Réplica 2022-2 (n.º 52) · Arts. 4, 6 y 7 LO 6/1984', 'El procedimiento se iniciará, salvo cuando se incoe de oficio, por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador.', null, 'b2639cd1fbc90b5e9719bc90bd294f07d57bd452f23b4cf37fff49fa0da9e4e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b2639cd1fbc90b5e9719bc90bd294f07d57bd452f23b4cf37fff49fa0da9e4e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si se inicia por comparecencia, es preceptiva la intervención de Abogado.', true), ('B', 'Puede iniciarse por escrito o por comparecencia, salvo que se incoe de oficio.', false), ('C', 'El auto que acuerda la incoación o deniega la solicitud se notifica, en todo caso, al Ministerio Fiscal.', false), ('D', 'En el auto de incoación el Juez ordena que se ponga de manifiesto ante él a la persona privada de libertad, sin pretexto ni demora, o se constituye en el lugar donde se encuentre.', false)) as v(label, body, ok)
)
