insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gcexamen-2022-2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, una diferencia de trato basada en una característica relacionada con el sexo en el acceso al empleo, cuando por la naturaleza de la actividad esa característica sea un requisito profesional esencial y determinante, con objetivo legítimo y requisito proporcionado:', 'El último párrafo del art. 5 de la LO 3/2007 excluye que haya discriminación en ese supuesto.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2022-2 (n.º 11) · Art. 5 LO 3/2007', 'No constituirá discriminación en el acceso al empleo, incluida la formación necesaria, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional esencial y determinante, siempre y cuando el objetivo sea legítimo y el requisito proporcionado.', null, 'e74653ec956f37b6355431e53026c31251b6fd3f5c0fd818f68be52e080a8a25', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e74653ec956f37b6355431e53026c31251b6fd3f5c0fd818f68be52e080a8a25')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Constituye discriminación indirecta por razón de sexo.', false), ('B', 'Constituye discriminación directa por razón de sexo.', false), ('C', 'Solo es válida si la autoriza previamente la Inspección de Trabajo.', false), ('D', 'No constituye discriminación.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 77 de la Ley Orgánica 3/2007, ¿cuál de estas funciones corresponde a las Unidades de Igualdad de los Ministerios?', 'El art. 77 atribuye a las Unidades de Igualdad recabar información estadística, elaborar estudios, asesorar en el informe de impacto de género, fomentar el conocimiento del principio de igualdad y velar por el cumplimiento de la ley; no funciones sancionadoras ni resolutorias.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2022-2 (n.º 12) · Art. 77 LO 3/2007', 'd) Fomentar el conocimiento por el personal del Departamento del alcance y significado del principio de igualdad mediante la formulación de propuestas de acciones formativas.', null, '0785963d194951f4b21e67e2fb34dc242e837e8430d15c20121f0e1f402b513b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0785963d194951f4b21e67e2fb34dc242e837e8430d15c20121f0e1f402b513b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Imponer sanciones por incumplimiento de los planes de igualdad de las empresas.', false), ('B', 'Fomentar el conocimiento por el personal del Departamento del alcance y significado del principio de igualdad mediante propuestas de acciones formativas.', true), ('C', 'Aprobar los planes de igualdad de las empresas que contraten con el Ministerio.', false), ('D', 'Resolver las reclamaciones de los empleados públicos por acoso sexual.', false)) as v(label, body, ok)
)
