  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿En qué plazo debe notificarse al reclamante la decisión de la Agencia Española de Protección de Datos sobre la admisión o inadmisión a trámite de su reclamación?', 'Art. 65.5 LOPDGDD; si no se notifica, se entiende que prosigue la tramitación.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Réplica 2022-2 (n.º 66) · Art. 65.5 LO 3/2018', 'La decisión sobre la admisión o inadmisión a trámite, así como la que determine, en su caso, la remisión de la reclamación a la autoridad de control principal que se estime competente, deberá notificarse al reclamante en el plazo de tres meses.', null, 'b90e06817ad903c8fa27e34800a062a7d464b0054ea1a8e8a351f5ee699b7343', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b90e06817ad903c8fa27e34800a062a7d464b0054ea1a8e8a351f5ee699b7343')
