with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, el enjuiciamiento de los delitos contra el titular de la Corona, su Consorte o su Sucesor, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, corresponde a:', 'El art. 65.1.º LOPJ atribuye a la Sala de lo Penal de la Audiencia Nacional el enjuiciamiento de los delitos contra el titular de la Corona, su Consorte, su Sucesor, altos organismos de la Nación y forma de Gobierno.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Réplica 2022-2 (n.º 53) · Art. 65.1.º.a LOPJ', 'La Sala de lo Penal de la Audiencia Nacional conocerá: 1.º Del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos: a) Delitos contra el titular de la Corona', null, '3eeb429677911a13d18cfdf29da0a8f04415f04d823820fe0ee09c76bf4503fc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3eeb429677911a13d18cfdf29da0a8f04415f04d823820fe0ee09c76bf4503fc')
  returning id
