  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sala de lo Penal de la Audiencia Nacional.', true), ('B', 'La Sala Segunda del Tribunal Supremo.', false), ('C', 'La Sala de lo Civil y Penal del Tribunal Superior de Justicia de Madrid.', false), ('D', 'La Sala de Apelación de la Audiencia Nacional.', false)) as v(label, body, ok)
)
