with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, ¿quién nombra a los Jueces de Paz y a sus sustitutos?', 'El art. 101 LOPJ: el Pleno del Ayuntamiento elige por mayoría absoluta y la Sala de Gobierno del TSJ nombra, por cuatro años.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Réplica 2022-2 (n.º 54) · Art. 101.1 LOPJ', 'Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente. El nombramiento recaerá en las personas elegidas por el respectivo Ayuntamiento.', null, '50a4da561ac207eca66032cb6fad8d69b1a6c9df4969b09d5450a8a9098950c1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '50a4da561ac207eca66032cb6fad8d69b1a6c9df4969b09d5450a8a9098950c1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Pleno del Ayuntamiento, por mayoría absoluta y sin intervención de otro órgano.', false), ('B', 'La Sala de Gobierno del Tribunal Superior de Justicia correspondiente, entre las personas elegidas por el Ayuntamiento.', true), ('C', 'El Consejo General del Poder Judicial, a propuesta del Alcalde.', false), ('D', 'El Presidente de la Audiencia Provincial, oído el Juez Decano.', false)) as v(label, body, ok)
)
