insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gcexamen-2022-2', 'Examen réplica 2022, ejercicio 2 · Prueba de conocimientos (100 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gcexamen-2022-2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el registro corporal externo y superficial de la Ley Orgánica 4/2015, señale la opción CORRECTA:', 'Art. 20.4. El registro procede cuando haya indicios racionales de que puede conducir al hallazgo de objetos relevantes (20.1); la regla del agente del mismo sexo cede en caso de urgencia (20.2); y el afectado debe ser informado de modo inmediato y comprensible de sus razones (20.3).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2022-2 (n.º 69) · Art. 20 LO 4/2015', '4. Los registros a los que se refiere este artículo podrán llevarse a cabo contra la voluntad del afectado, adoptando las medidas de compulsión indispensables, conforme a los principios de idoneidad, necesidad y proporcionalidad.', null, '6e1d6929f99ed8b7f6be6c2dda51cdb87669f1f523c758be1778a2269a2891c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e1d6929f99ed8b7f6be6c2dda51cdb87669f1f523c758be1778a2269a2891c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo puede practicarse para acreditar la identidad de la persona.', false), ('B', 'Se realiza siempre por un agente del mismo sexo, incluso en situaciones de urgencia por riesgo grave e inminente para los agentes.', false), ('C', 'No es necesario informar al afectado de las razones de su realización.', false), ('D', 'Puede llevarse a cabo contra la voluntad del afectado, con las medidas de compulsión indispensables.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las reuniones y manifestaciones en la Ley Orgánica 4/2015, señale la opción CORRECTA:', 'Art. 23.3. La disolución es el último recurso (23.2), el aviso puede ser verbal si la urgencia lo exige (23.3) y pueden disolverse concentraciones de vehículos y retirarlos (23.1).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2022-2 (n.º 70) · Art. 23 LO 4/2015', 'En caso de que se produzca una alteración de la seguridad ciudadana con armas, artefactos explosivos u objetos contundentes o de cualquier otro modo peligrosos, las Fuerzas y Cuerpos de Seguridad podrán disolver la reunión o manifestación o retirar los vehículos y obstáculos sin necesidad de previo aviso.', null, 'efb464a39ea27dedd1b52acf85618db31ff902e2bec36d533ad41291d8ab518c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'efb464a39ea27dedd1b52acf85618db31ff902e2bec36d533ad41291d8ab518c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si hay una alteración de la seguridad ciudadana con armas u objetos peligrosos, las Fuerzas y Cuerpos de Seguridad pueden disolver la reunión sin previo aviso.', true), ('B', 'La disolución de reuniones y manifestaciones es la primera medida de intervención.', false), ('C', 'El aviso previo de las medidas de intervención debe hacerse siempre por escrito.', false), ('D', 'Las autoridades no pueden retirar los vehículos concentrados en la vía pública.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2015, ¿cuál de las siguientes conductas es una infracción GRAVE?', 'La alegación de datos falsos es grave (art. 36.21); el escalamiento, el consumo de alcohol en la vía pública y la remoción de vallas son leves (art. 37).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2022-2 (n.º 71) · Arts. 36.21 y 37 LO 4/2015', 'Son infracciones graves: […] 21. La alegación de datos o circunstancias falsos para la obtención de las documentaciones previstas en esta Ley, siempre que no constituya infracción penal.', null, '63fde4c7349e7d0e0a9ab08a37336d4364f5c7eca4c971cbb2aad51b0b0610c3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '63fde4c7349e7d0e0a9ab08a37336d4364f5c7eca4c971cbb2aad51b0b0610c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Escalar sin autorización edificios o monumentos con riesgo cierto de daños a personas o bienes.', false), ('B', 'Alegar datos o circunstancias falsos para obtener las documentaciones previstas en la ley, si no constituye infracción penal.', true), ('C', 'Consumir bebidas alcohólicas en la vía pública perturbando gravemente la tranquilidad ciudadana.', false), ('D', 'Retirar sin autorización vallas o encintados colocados por la policía para delimitar perímetros de seguridad.', false)) as v(label, body, ok)
)
