with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 39/2015, ¿cuáles de los siguientes sujetos están obligados, en todo caso, a relacionarse electrónicamente con las Administraciones Públicas?', 'El art. 14.2 obliga, entre otros, a las personas jurídicas y a las entidades sin personalidad jurídica; las personas físicas pueden elegir, salvo que estén obligadas (art. 14.1).', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Réplica 2022-2 (n.º 56) · Art. 14.2 Ley 39/2015', '2. En todo caso, estarán obligados a relacionarse a través de medios electrónicos con las Administraciones Públicas para la realización de cualquier trámite de un procedimiento administrativo, al menos, los siguientes sujetos: a) Las personas jurídicas. b) Las entidades sin personalidad jurídica.', null, '333f6ad5b84f0201f681b2213b485b6263d93b1b356e938a7100d02702a5c67c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '333f6ad5b84f0201f681b2213b485b6263d93b1b356e938a7100d02702a5c67c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Todas las personas físicas mayores de edad.', false), ('B', 'Las personas físicas que lo soliciten expresamente.', false), ('C', 'Las personas físicas residentes en el extranjero.', false), ('D', 'Las entidades sin personalidad jurídica.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el cómputo de plazos en la Ley 39/2015, señale la opción INCORRECTA:', 'Según el art. 30.3, los plazos en días se cuentan a partir del día siguiente al de la notificación o publicación. Las demás reproducen los arts. 30.5, 30.6 y 30.2.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Réplica 2022-2 (n.º 57) · Art. 30 Ley 39/2015', '3. Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate', null, '9563ec4d23f8f9a667623dcb70962c668fbd620f2abd5524dd356bfcb1f575ed', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9563ec4d23f8f9a667623dcb70962c668fbd620f2abd5524dd356bfcb1f575ed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los plazos señalados por días se cuentan desde el mismo día en que se notifica o publica el acto.', true), ('B', 'Si el último día del plazo es inhábil, se entiende prorrogado al primer día hábil siguiente.', false), ('C', 'Un día hábil en el municipio del interesado e inhábil en la sede del órgano, o a la inversa, se considera inhábil en todo caso.', false), ('D', 'Si una ley declara que el plazo se computa por días naturales, debe indicarse así en las notificaciones.', false)) as v(label, body, ok)
)
