  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Registro Central de Penados.', false), ('B', 'El Mapa Nacional de Riesgos de Protección Civil.', true), ('C', 'El inventario de bienes de interés cultural.', false), ('D', 'El registro de entidades de voluntariado de cada municipio.', false)) as v(label, body, ok)
