  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué órgano establece el artículo 9 del Tratado del Atlántico Norte, con representación de todas las Partes, para conocer de las cuestiones relativas a la aplicación del Tratado?', 'El art. 9 crea el Consejo (Consejo del Atlántico Norte), principal órgano político de decisión de la OTAN, que puede establecer órganos subsidiarios.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1982-12535'), 'Réplica 2022-2 (n.º 33) · Art. 9 Tratado del Atlántico Norte', 'Las Partes establecen por la presente disposición un Consejo, en el que cada una de ellas estará representada, para conocer de las cuestiones relativas a la aplicación del Tratado. El Consejo estará organizado de manera que pueda reunirse rápidamente en cualquier momento.', null, '5483353ce7e7695125824240341edf35ef84b397aaadd74b17e1afcec2b65e19', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5483353ce7e7695125824240341edf35ef84b397aaadd74b17e1afcec2b65e19')
  returning id
), o as (
