  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la estructura de los Servicios Centrales de la Dirección General de la Guardia Civil, ¿qué órgano es responsable de la gestión, control y mantenimiento operativo de los equipos y sistemas informáticos y de telecomunicaciones del Cuerpo?', 'El art. 26 de la Orden PRE/422/2013 atribuye esas funciones a la Jefatura de Servicios Técnicos, de la que dependen los Servicios de Informática, de Telecomunicaciones y de Innovación Tecnológica y Seguridad de la Información.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906'), 'Réplica 2022-2 (n.º 79) · Art. 26 Orden PRE/422/2013', 'La Jefatura de Servicios Técnicos, al mando de un Oficial General de la Guardia Civil en situación de servicio activo, es el órgano responsable de la gestión, control y mantenimiento operativo de los equipos y sistemas informáticos, de telecomunicaciones y equipos especiales asignados a la Guardia Civil', null, '7172d9898d092d87a1ea2e375a7878df0491a674289f2eab22e58fe8933afc55', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7172d9898d092d87a1ea2e375a7878df0491a674289f2eab22e58fe8933afc55')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Jefatura de los Servicios de Apoyo.', false), ('B', 'La Jefatura de Información.', false), ('C', 'La Jefatura de Asuntos Económicos.', false), ('D', 'La Jefatura de Servicios Técnicos.', true)) as v(label, body, ok)
)
