with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Pacto Internacional de Derechos Civiles y Políticos, el informe anual del Comité de Derechos Humanos sobre sus actividades se dirige:', 'El art. 45 PIDCP: el Comité presenta su informe anual a la Asamblea General por conducto del ECOSOC.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10733'), 'Réplica 2022-2 (n.º 6) · Art. 45 PIDCP', 'El Comité presentará a la Asamblea General de las Naciones Unidas, por conducto del Consejo Económico y Social, un informe anual sobre sus actividades.', null, '833606235e6545815090c9713c5169cd803036434b33052aaebd18846c33b69d', false
