with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Entre los derechos que los Estados Partes reconocen en el Pacto Internacional de Derechos Económicos, Sociales y Culturales, señale el INCORRECTO:', 'El art. 8.1.a) PIDESC protege los intereses «económicos y sociales» y admite las restricciones que prescriba la ley y sean necesarias en una sociedad democrática. Las demás proceden de los arts. 11.1, 12.1 y 6.1.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10734'), 'Réplica 2022-2 (n.º 5) · Art. 8.1.a PIDESC', 'El derecho de toda persona a fundar sindicatos y a afiliarse al de su elección, con sujeción únicamente a los estatutos de la organización correspondiente para promover y proteger sus intereses económicos y sociales. No podrán imponerse otras restricciones al ejercicio de este derecho que las que prescriba la Ley y que sean necesarias en una sociedad democrática', null, 'c5479de3cfb7306937215c93ce95bb897cfac82dc8e57508fb6ee97d1850c9f0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c5479de3cfb7306937215c93ce95bb897cfac82dc8e57508fb6ee97d1850c9f0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El derecho a un nivel de vida adecuado para sí y su familia, incluso alimentación, vestido y vivienda adecuados.', false), ('B', 'El derecho al disfrute del más alto nivel posible de salud física y mental.', false), ('C', 'El derecho a trabajar, que incluye la oportunidad de ganarse la vida con un trabajo libremente escogido o aceptado.', false), ('D', 'El derecho a fundar sindicatos y afiliarse a ellos para promover intereses políticos, sin que pueda imponerse ninguna restricción a su ejercicio.', true)) as v(label, body, ok)
)
