with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Prevención de Riesgos Laborales, si el Inspector de Trabajo y Seguridad Social ordena la paralización inmediata de unos trabajos por riesgo grave e inminente, la empresa puede impugnarla ante la autoridad laboral:', 'El art. 44.1 PRL fija tres días hábiles para impugnar ante la autoridad laboral; la decisión se cumple de inmediato.', 'gcexamen_2022_2', (select id from public.topics where slug = 'gcexamen-2022-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Réplica 2022-2 (n.º 13) · Art. 44.1 Ley 31/1995', 'La empresa, sin perjuicio del cumplimiento inmediato de tal decisión, podrá impugnarla ante la autoridad laboral en el plazo de tres días hábiles', null, '59862a117481164a80c34fb0f8c04203d37c5dc2f7cc89c271987c9ea9cd6de9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '59862a117481164a80c34fb0f8c04203d37c5dc2f7cc89c271987c9ea9cd6de9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
