  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La ley garantizará a todos los grupos sociales y políticos el acceso a los medios de comunicación de titularidad privada.', false), ('B', 'Una ley orgánica podrá establecer supuestos excepcionales de censura previa.', false), ('C', 'El secuestro de publicaciones, grabaciones y otros medios de información solo puede acordarse mediante resolución judicial.', true), ('D', 'La libertad de cátedra se reconoce en el artículo 27, junto al derecho a la educación.', false)) as v(label, body, ok)
)
