with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 31.1 de la Constitución, el sistema tributario justo mediante el que todos contribuyen al sostenimiento de los gastos públicos:', 'Art. 31.1 CE: igualdad y progresividad, sin alcance confiscatorio.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2022-3 (n.º 17) · Art. 31.1 CE', 'Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad y progresividad que, en ningún caso, tendrá alcance confiscatorio.', null, '7b902ce297036ed84c40f606a765bd275639813010556bcec99c4ebbd1f1c72d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b902ce297036ed84c40f606a765bd275639813010556bcec99c4ebbd1f1c72d')
