), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El estado de alarma lo declara el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días.', true), ('B', 'El estado de excepción lo declara el Congreso por mayoría absoluta, a propuesta exclusiva del Gobierno.', false), ('C', 'Disuelto el Congreso, si se produce alguna de las situaciones que dan lugar a estos estados, sus competencias las asume el Senado.', false), ('D', 'La declaración del estado de sitio permite modificar el principio de responsabilidad del Gobierno si lo acuerda el Congreso.', false)) as v(label, body, ok)
)
