with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 del Código Penal, si la pena, por su extensión, puede incluirse a la vez entre las graves y las menos graves, el delito se considera:', 'Art. 13.4 CP: en ese caso el delito es grave; si la pena puede ser leve y menos grave, el delito es leve.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2022-3 (n.º 35) · Art. 13.4 Código Penal', '4. Cuando la pena, por su extensión, pueda incluirse a la vez entre las mencionadas en los dos primeros números de este artículo, el delito se considerará, en todo caso, como grave.', null, 'afb8ff796c505f59d67fde2691dc669968a216eda8abaf5f4832b6a4453c2c92', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'afb8ff796c505f59d67fde2691dc669968a216eda8abaf5f4832b6a4453c2c92')
  returning id
