with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Carta Social Europea (revisada), ¿cuál de los siguientes compromisos asumen las Partes para garantizar el ejercicio efectivo del derecho de negociación colectiva?', 'El art. 6 de la Carta (negociación colectiva) incluye, en su apartado 3, el fomento de la conciliación y el arbitraje voluntarios; las demás opciones corresponden a otros artículos (condiciones de trabajo, menores y remuneración).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-9719'), 'Réplica 2022-3 (n.º 3) · Art. 6.3 Carta Social Europea revisada', 'Artículo 6. Derecho de negociación colectiva. Para garantizar el ejercicio efectivo del derecho de negociación colectiva, las Partes se comprometen: […] 3. a fomentar el establecimiento y la utilización de procedimientos adecuados de conciliación y arbitraje voluntarios para la solución de conflictos laborales', null, 'e6ef1f07d5b52a34954dfa57ff99559a0079458daabebee11df23420431e1b47', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e6ef1f07d5b52a34954dfa57ff99559a0079458daabebee11df23420431e1b47')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conceder a los trabajadores vacaciones anuales pagadas de una duración mínima de cuatro semanas.', false), ('B', 'Fijar en quince años la edad mínima de admisión al trabajo.', false), ('C', 'Reconocer el derecho de los trabajadores a un plazo razonable de preaviso en caso de terminación del empleo.', false), ('D', 'Fomentar procedimientos adecuados de conciliación y arbitraje voluntarios para resolver los conflictos laborales.', true)) as v(label, body, ok)
)
