with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Carta de las Naciones Unidas, la Organización no limitará la elegibilidad de hombres y mujeres para participar en condiciones de igualdad en las funciones de:', 'El art. 8 de la Carta extiende la igualdad de elegibilidad a todos los órganos de la ONU, tanto principales como subsidiarios, y en cualquier carácter.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/un-charter/full-text'), 'Réplica 2022-3 (n.º 1) · Art. 8 Carta de las Naciones Unidas', 'La Organización no establecerá restricciones en cuanto a la elegibilidad de hombres y mujeres para participar en condiciones de igualdad y en cualquier caracter en las funciones de sus órganos principales y subsidiarios.', null, '1103e29b7c875aadc5301aee6cbc04cf5da72b6546a8eed812feb9f81df35be6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1103e29b7c875aadc5301aee6cbc04cf5da72b6546a8eed812feb9f81df35be6')
  returning id
), o as (
