  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sus órganos principales y subsidiarios.', true), ('B', 'Únicamente la Asamblea General y el Consejo de Seguridad.', false), ('C', 'Sus órganos principales, pero no los subsidiarios.', false), ('D', 'Los organismos especializados vinculados a la Organización.', false)) as v(label, body, ok)
)
