with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 4 de la Convención contra la tortura, ¿qué debe asegurar todo Estado Parte en su legislación?', 'El art. 4.1 obliga a tipificar como delito la tortura, la tentativa y la complicidad o participación; el 4.2 exige penas adecuadas a su gravedad.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-1987-25053'), 'Réplica 2022-3 (n.º 7) · Art. 4.1 Convención contra la tortura', '1. TODO ESTADO PARTE VELARA PARA QUE TODOS LOS ACTOS DE TORTURA CONSTITUYAN DELITOS CONFORME A SU LEGISLACION PENAL. LO MISMO SE APLICARA A TODA TENTATIVA DE COMETER TORTURA Y A TODO ACTO DE CUALQUIER PERSONA QUE CONSTITUYA COMPLICIDAD O PARTICIPACION EN LA TORTURA.', null, '63525a71b1e46247c1baa2be63c3d4b0ecc8ba5c8d3604dc63424bf8966a2c75', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '63525a71b1e46247c1baa2be63c3d4b0ecc8ba5c8d3604dc63424bf8966a2c75')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que la tortura pueda sancionarse indistintamente por la vía penal o por la administrativa.', false), ('B', 'Que la complicidad en actos de tortura se castigue como infracción disciplinaria.', false), ('C', 'Que los actos de tortura, su tentativa y la complicidad o participación en ellos constituyan delito conforme a su legislación penal.', true), ('D', 'Que solo la tortura consumada constituya delito, quedando la tentativa al arbitrio de cada Estado.', false)) as v(label, body, ok)
)
