with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Señale la respuesta CORRECTA acerca del Consejo de Derechos Humanos de la ONU:', 'Según la ONU, el Consejo tiene 47 Estados miembros elegidos por la Asamblea General, sustituyó a la Comisión de Derechos Humanos, cada año se renueva un tercio y el mandato es de tres años, con un límite de dos mandatos consecutivos.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.ohchr.org/es/hr-bodies/hrc/about-council'), 'Réplica 2022-3 (n.º 6) · Consejo de Derechos Humanos de la ONU (composición)', 'cada año se renueva un tercio de los miembros. Cada miembro tiene un mandato de tres años. Su mandato está limitado a dos mandatos consecutivos.', null, '638c9977af91418aa4b516a923fc9606e37f159f37ddee88364a976289553a34', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '638c9977af91418aa4b516a923fc9606e37f159f37ddee88364a976289553a34')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Está integrado por 54 Estados elegidos por el Consejo de Seguridad.', false), ('B', 'Fue creado por la antigua Comisión de Derechos Humanos, de la que sigue dependiendo.', false), ('C', 'Cada año se renueva la mitad de sus miembros.', false), ('D', 'Cada miembro tiene un mandato de tres años, y no puede ejercer más de dos mandatos consecutivos.', true)) as v(label, body, ok)
)
