with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Protocolo Facultativo de la Convención contra la tortura, ¿quién aporta el personal y los servicios que el Subcomité para la Prevención necesita para ejercer eficazmente sus funciones?', 'El art. 25.2 del Protocolo atribuye esa obligación al Secretario General.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Réplica 2022-3 (n.º 8) · Art. 25.2 Protocolo Facultativo de la Convención contra la tortura', '2. El Secretario General de las Naciones Unidas proporcionará el personal y los servicios necesarios para el desempeño eficaz de las funciones asignadas al Subcomité para la Prevención en virtud del presente Protocolo.', null, 'e2a33b7f2a723f57a01a638f99af5ee1794cc826c66f687894c89962af2ed437', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e2a33b7f2a723f57a01a638f99af5ee1794cc826c66f687894c89962af2ed437')
  returning id
