with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La digitalización de documentos en soporte papel por las Administraciones públicas se ajustará a la norma técnica de interoperabilidad en varios aspectos. ¿Cuál de los siguientes NO figura entre ellos en el artículo 24 del Real Decreto 4/2010?', 'El art. 24.1 enumera formatos y compresión, resolución, imagen fiel e íntegra y metadatos mínimos.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331'), 'Réplica 2022-3 (n.º 89) · Art. 24.1 RD 4/2010', 'a) Formatos estándares de uso común para la digitalización de documentos en soporte papel y técnica de compresión empleada, de acuerdo con lo previsto en el artículo 11. b) Nivel de resolución. c) Garantía de imagen fiel e íntegra. d) Metadatos mínimos obligatorios y complementarios, asociados al proceso de digitalización.', null, '5389d3f0a435a3f208cf5daaffeff307487b050cbe05f54c55fbf9c1a297d4db', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5389d3f0a435a3f208cf5daaffeff307487b050cbe05f54c55fbf9c1a297d4db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El nivel de resolución.', false), ('B', 'La garantía de imagen fiel e íntegra.', false), ('C', 'Los formatos estándares de uso común y la técnica de compresión empleada.', false), ('D', 'El número máximo de páginas por documento.', true)) as v(label, body, ok)
)
