with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos de la Directiva 2012/27/UE, la cantidad de energía ahorrada, determinada midiendo o estimando el consumo antes y después de aplicar una medida de mejora de la eficiencia energética, se denomina:', 'Art. 2.5) de la Directiva; la eficiencia energética es la relación entre la producción de un rendimiento, servicio, bien o energía y el gasto de energía (art. 2.4).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504'), 'Réplica 2022-3 (n.º 83) · Art. 2 Directiva 2012/27/UE', '5) "ahorro de energía": la cantidad de energía ahorrada, determinada mediante la medición y/o estimación del consumo antes y después de la aplicación de alguna medida de mejora de la eficiencia energética', 'El temario vigente sigue citando la Directiva 2012/27/UE (texto consolidado a 4.5.2023 en la carpeta), que la Directiva (UE) 2023/1791 ha refundido; revisar si conviene actualizar la fuente.', '017be927b0758db57ea252fe79d9922c74e727b981ebb4bcea16e7c7177c60fb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '017be927b0758db57ea252fe79d9922c74e727b981ebb4bcea16e7c7177c60fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ahorro de energía.', true), ('B', 'Eficiencia energética.', false), ('C', 'Servicio energético.', false), ('D', 'Mejora de la eficiencia energética.', false)) as v(label, body, ok)
)
