with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Directiva 2012/27/UE, al licitar contratos de servicios con una componente energética importante, los Estados miembros animarán a los organismos públicos a evaluar la posibilidad de celebrar contratos de rendimiento energético:', 'Art. 6.3 de la Directiva 2012/27/UE.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504'), 'Réplica 2022-3 (n.º 84) · Art. 6.3 Directiva 2012/27/UE', 'Los Estados miembros animarán a los organismos públicos a evaluar, en los procedimientos de licitación para contratos de servicios con una componente energética importante, la posibilidad de celebrar contratos de rendimiento energético a largo plazo que ofrezcan un ahorro de energía a largo plazo.', 'El temario vigente sigue citando la Directiva 2012/27/UE (texto consolidado a 4.5.2023 en la carpeta), que la Directiva (UE) 2023/1791 ha refundido; revisar si conviene actualizar la fuente.', '6cc41da27d64da2c78a1ea6311d213f727a8cb3873e970318bdbaeba9cffebd4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6cc41da27d64da2c78a1ea6311d213f727a8cb3873e970318bdbaeba9cffebd4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A corto plazo, que ofrezcan un ahorro de energía a largo plazo.', false), ('B', 'A medio plazo, que ofrezcan un ahorro de energía inmediato.', false), ('C', 'A largo plazo, que ofrezcan un ahorro de energía a largo plazo.', true), ('D', 'A largo plazo, que ofrezcan un ahorro de energía a corto plazo.', false)) as v(label, body, ok)
)
