with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Tratado de Funcionamiento de la Unión Europea, en los ámbitos de la cooperación para el desarrollo y de la ayuda humanitaria:', 'Art. 4.4 TFUE: competencia compartida de tipo paralelo, que no impide a los Estados ejercer la suya.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016E/TXT'), 'Réplica 2022-3 (n.º 26) · Art. 4.4 TFUE', '4. En los ámbitos de la cooperación para el desarrollo y de la ayuda humanitaria, la Unión dispondrá de competencia para llevar a cabo acciones y una política común, sin que el ejercicio de esta competencia pueda tener por efecto impedir a los Estados miembros ejercer la suya.', null, '84c28d9f3446a1abd67bf1f86667b6da26bae974bd5a38793f4cc6adde734a64', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '84c28d9f3446a1abd67bf1f86667b6da26bae974bd5a38793f4cc6adde734a64')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Unión dispone de competencia exclusiva, de modo que los Estados miembros solo pueden actuar si ella los faculta.', false), ('B', 'La Unión dispone de competencia para llevar a cabo acciones y una política común, sin que ello impida a los Estados miembros ejercer la suya.', true), ('C', 'La Unión solo puede llevar a cabo acciones de apoyo, coordinación o complemento de las acciones de los Estados.', false), ('D', 'La Unión solo puede actuar si el Consejo Europeo lo acuerda por unanimidad caso por caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Señale la respuesta INCORRECTA sobre los actos jurídicos de la Unión que regula el TFUE:', 'El art. 290.1 TFUE solo permite delegar actos no legislativos que completen o modifiquen elementos no esenciales; los elementos esenciales quedan reservados al acto legislativo.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016E/TXT'), 'Réplica 2022-3 (n.º 27) · Arts. 289-291 TFUE', 'La regulación de los elementos esenciales de un ámbito estará reservada al acto legislativo y, por lo tanto, no podrá ser objeto de una delegación de poderes.', null, 'be118026d0a126672e7516fe7e42c7c66ec696638b2122a58a72d0d4afb82d34', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'be118026d0a126672e7516fe7e42c7c66ec696638b2122a58a72d0d4afb82d34')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un acto legislativo puede delegar en la Comisión la regulación de los elementos esenciales de un ámbito.', true), ('B', 'Los actos jurídicos adoptados mediante procedimiento legislativo constituyen actos legislativos.', false), ('C', 'El procedimiento legislativo ordinario consiste en la adopción conjunta por el Parlamento Europeo y el Consejo, a propuesta de la Comisión, de un reglamento, una directiva o una decisión.', false), ('D', 'Los Estados miembros adoptan las medidas de Derecho interno necesarias para ejecutar los actos jurídicamente vinculantes de la Unión.', false)) as v(label, body, ok)
)
