with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el Parlamento Europeo (artículo 14 del Tratado de la Unión Europea), señale la respuesta INCORRECTA:', 'El art. 14.2 TUE fija el máximo en setecientos cincuenta diputados, más el Presidente.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Réplica 2022-3 (n.º 25) · Art. 14.2 TUE', 'ero no excederá de setecientos cincuenta, más el Presidente. La representación de los ciudadanos será decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro. No se asignará a ningún Estado miembro más de noventa y seis escaños.', null, '3a120d55dc9ed1274817a46ca2caafa26cddadef82c644cf4b70ade452163a47', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3a120d55dc9ed1274817a46ca2caafa26cddadef82c644cf4b70ade452163a47')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La representación de los ciudadanos será decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro.', false), ('B', 'Ningún Estado miembro tendrá asignados más de noventa y seis escaños.', false), ('C', 'El número de diputados no excederá de setecientos, más el Presidente.', true), ('D', 'Los diputados se eligen por sufragio universal directo, libre y secreto, para un mandato de cinco años.', false)) as v(label, body, ok)
)
