with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con los principios que rigen las competencias de la Unión Europea (artículo 5 del Tratado de la Unión Europea), señale la respuesta CORRECTA:', 'Art. 5.1 TUE. El límite de «lo necesario» define la proporcionalidad (5.4); toda competencia no atribuida corresponde a los Estados (5.2); la subsidiariedad opera en los ámbitos que no son de competencia exclusiva (5.3).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016M/TXT'), 'Réplica 2022-3 (n.º 24) · Art. 5 TUE', '1. La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad.', null, '15253cfcac143499de0f92a322ec176a2afdb65c911cdec3c0663da372130c0d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '15253cfcac143499de0f92a322ec176a2afdb65c911cdec3c0663da372130c0d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En virtud del principio de subsidiariedad, el contenido y la forma de la acción de la Unión no excederán de lo necesario para alcanzar los objetivos de los Tratados.', false), ('B', 'En virtud del principio de atribución, la Unión actúa en todos los ámbitos que los Estados miembros no se hayan reservado expresamente.', false), ('C', 'La delimitación de las competencias se rige por el principio de atribución, y su ejercicio por los de subsidiariedad y proporcionalidad.', true), ('D', 'El principio de subsidiariedad se aplica sobre todo en los ámbitos de competencia exclusiva de la Unión.', false)) as v(label, body, ok)
)
