  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la historia oficial de la Guardia Civil, ¿qué fuerza reunificaron los progresistas de las Cortes de Cádiz para combatir la inseguridad creciente?', 'La Milicia Nacional fue disuelta por Fernando VII en 1814, reconstituida en 1820 y desapareció en 1823 con el fin del Trienio Liberal.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'Réplica 2022-3 (n.º 94) · Historia de la Guardia Civil (Cortes de Cádiz)', 'Los progresistas de las Cortes de Cádiz reunifican la Milicia Nacional para combatir la inseguridad creciente.', null, '4dcfe2742dc7e3715e60e0b10c838b59962ba1b0a8fa49d8c14727bbcf84caa4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4dcfe2742dc7e3715e60e0b10c838b59962ba1b0a8fa49d8c14727bbcf84caa4')
  returning id
), o as (
