with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la localización de elementos en un mapa según el Atlas Didáctico del IGN, señale la respuesta INCORRECTA:', 'El Atlas muestra la longitud en el eje de abscisas (horizontal) y la latitud en el de ordenadas (vertical).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/cartografia-bach/representacin_del_relieve.html'), 'Réplica 2022-3 (n.º 98) · Atlas Didáctico IGN (cuadrícula y coordenadas)', 'La ubicación de un objeto en un mapa se articula a través de las coordenadas. El eje de abscisas y ordenadas, visibles sobre el marco del mapa, permite localizar un elemento sobre el mismo. En la siguiente imagen se muestra la Longitud en el eje de abscisas y la Latitud en el eje de ordenadas.', null, '4cc2ad322353fa01b3e60afdd180a262d9662d7558dd93ddcd61ad9e0a74d3d3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4cc2ad322353fa01b3e60afdd180a262d9662d7558dd93ddcd61ad9e0a74d3d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La ubicación de un objeto en un mapa se articula a través de las coordenadas.', false), ('B', 'Los ejes de abscisas y ordenadas, visibles sobre el marco del mapa, permiten localizar un elemento.', false), ('C', 'En la representación que muestra el Atlas, la latitud figura en el eje de abscisas y la longitud en el de ordenadas.', true), ('D', 'En un mapa a escala 1:25.000, cada centímetro medido en el mapa equivale a 250 metros en el terreno.', false)) as v(label, body, ok)
)
