with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una misma distancia del terreno mide 0,05 m en un plano a escala 1/20.000 y 0,04 m en otro plano. ¿Cuál es la escala del segundo plano?', 'Distancia real = 0,05 m × 20.000 = 1.000 m. Escala del segundo plano = 0,04 / 1.000 = 1/25.000 (a menor medida en el plano para la misma distancia real, menor escala).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.ign.es/web/resources/cartografiaEnsenanza/conceptosCarto/descargas/Conceptos_Cartograficos_def.pdf'), 'Réplica 2022-3 (n.º 91) · Escala cartográfica (IGN)', 'La relación existente entre las distancias medidas en un plano o mapa y las correspondientes en la realidad se denomina escala. Por tanto, la escala es una proporción entre dos magnitudes lineales, independientemente del sistema de unidades de longitud que se utilice.', null, 'c420c18b361d9be7207aeaf2f40fe4c8b60d649a978a5846f55c30b1fe5fb5fa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c420c18b361d9be7207aeaf2f40fe4c8b60d649a978a5846f55c30b1fe5fb5fa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '1/25.000.', true), ('B', '1/16.000.', false), ('C', '1/20.000.', false), ('D', '1/30.000.', false)) as v(label, body, ok)
)
