with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cómo se denomina la circunferencia imaginaria paralela al Ecuador, cuyo perímetro se reduce hacia los polos y que sirve de referencia para medir la latitud?', 'Todos los puntos de un mismo paralelo tienen la misma latitud; el paralelo máximo es el Ecuador (0º).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'Réplica 2022-3 (n.º 90) · Glosario IGN (paralelo)', 'Paralelo (Términos genéricos) Circunferencia imaginaria paralela al Ecuador cuyo perímetro se reduce hacia los polos. Son la referencia para la medida de la latitud.', null, '3b426668f8e1b91996e70569e19882dac828983743080ae201bc34066b079035', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3b426668f8e1b91996e70569e19882dac828983743080ae201bc34066b079035')
