with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la meseta, tal como la define el glosario del Instituto Geográfico Nacional, señale la respuesta INCORRECTA:', 'La cadena de montañas enlazadas, de dirección predominantemente lineal, es la definición IGN de cordillera, no de meseta.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'Réplica 2022-3 (n.º 92) · Glosario IGN (meseta)', 'Cordillera (Relieve) Cadena de montañas enlazadas entre sí y cuyo conjunto forma una individualidad geográfica. Tienen dirección predominantemente lineal […] Meseta (Relieve) Superficie llana o ligeramente inclinada, cortada por valles y situada a una cierta altitud con respecto al nivel del mar. En la península ibérica constituye la unidad fundamental del relieve.', null, 'ad974c45bff0a1f1d3d2bb99f59050ae87b9e498e0a16dcc16c76d227c9eb116', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad974c45bff0a1f1d3d2bb99f59050ae87b9e498e0a16dcc16c76d227c9eb116')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es una superficie llana o ligeramente inclinada.', false), ('B', 'Está cortada por valles y situada a cierta altitud respecto del nivel del mar.', false), ('C', 'Es una cadena de montañas enlazadas entre sí, de dirección predominantemente lineal.', true), ('D', 'En la península ibérica constituye la unidad fundamental del relieve.', false)) as v(label, body, ok)
)
