with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las acciones que nacen del delito según la Ley de Enjuiciamiento Criminal, señale la respuesta CORRECTA:', 'Art. 100 LECrim; la acción penal es pública (art. 101).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 40) · Art. 100 LECrim', 'De todo delito o falta nace acción penal para el castigo del culpable, y puede nacer también acción civil para la restitución de la cosa, la reparación del daño y la indemnización de perjuicios causados por el hecho punible.', null, 'b033fe287b6f55d125f403d5c781f5c02187267e00923277ff32ae73e99cb25d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b033fe287b6f55d125f403d5c781f5c02187267e00923277ff32ae73e99cb25d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De todo delito nace acción penal para el castigo del culpable, y puede nacer también acción civil para la restitución de la cosa, la reparación del daño y la indemnización de perjuicios.', true), ('B', 'De todo delito nacen siempre, a la vez, la acción penal y la acción civil.', false), ('C', 'De todo delito nace la acción civil para el castigo del culpable.', false), ('D', 'La acción penal es privada y solo puede ejercerla el ofendido.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
