with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando la querella se refiere a un delito perseguible solo a instancia de parte, debe acompañarse la certificación de haberse celebrado o intentado el acto de conciliación, salvo en el delito de:', 'El art. 278 LECrim exceptúa la violación y el rapto.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 41) · Art. 278 LECrim', 'Si la querella tuviere por objeto algún delito de los que solamente pueden perseguirse a instancia de parte, excepto el de violación o rapto, acompañará también la certificación que acredite haberse celebrado o intentado el acto de conciliación entre querellante y querellado.', null, '5ad35f0e6cbf85fdde857863f68739344577e4a9d1159d47ff9b3e56d28f781c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ad35f0e6cbf85fdde857863f68739344577e4a9d1159d47ff9b3e56d28f781c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Calumnia.', false), ('B', 'Injuria.', false), ('C', 'Violación.', true), ('D', 'Descubrimiento y revelación de secretos.', false)) as v(label, body, ok)
)
