with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos de la actuación del agente encubierto, ¿cuál de los siguientes supuestos constituye delincuencia organizada según la Ley de Enjuiciamiento Criminal?', 'El art. 282 bis.4 exige tres o más personas, actuación permanente o reiterada y alguno de los delitos de la lista (entre ellos, la falsificación de moneda).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 42) · Art. 282 bis.4 LECrim', 'se considerará como delincuencia organizada la asociación de tres o más personas para realizar, de forma permanente o reiterada, conductas que tengan como fin cometer alguno o algunos de los delitos siguientes: […] l) Delitos de falsificación de moneda', null, '6459fdebfaa5c0862a6345ad12ddc557b27085406dae362fcad5e8926dcfa589', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6459fdebfaa5c0862a6345ad12ddc557b27085406dae362fcad5e8926dcfa589')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La asociación de cuatro personas para cometer, de forma reiterada, delitos de falsificación de moneda.', true), ('B', 'La asociación de dos personas para cometer, de forma permanente, delitos de trata de seres humanos.', false), ('C', 'La asociación de tres o más personas para cometer, de forma reiterada, delitos leves de lesiones.', false), ('D', 'La reunión ocasional de cinco personas para cometer un único robo con fuerza.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto del tratamiento de detenidos y presos en la Ley de Enjuiciamiento Criminal, señale la respuesta INCORRECTA:', 'El art. 525 LECrim exige que la medida extraordinaria sea temporal y dure solo el tiempo estrictamente necesario.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 43) · Arts. 521-525 LECrim', 'No se adoptará contra el detenido o preso ninguna medida extraordinaria de seguridad sino en caso de desobediencia, de violencia o de rebelión, o cuando haya intentado o hecho preparativos para fugarse. Esta medida deberá ser temporal, y sólo subsistirá el tiempo estrictamente necesario.', null, '61faf7e4b0a8b8443781597388664d1641c6b5ca9b27f2ad28986936603b0b2a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '61faf7e4b0a8b8443781597388664d1641c6b5ca9b27f2ad28986936603b0b2a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los detenidos estarán, a ser posible, separados unos de otros.', false), ('B', 'Las medidas extraordinarias de seguridad adoptadas contra un detenido pueden mantenerse durante toda la detención.', true), ('C', 'Mientras el detenido esté en comunicación, no puede impedírsele la relación con su abogado defensor.', false), ('D', 'En ningún caso puede impedirse a los detenidos o presos escribir a los funcionarios superiores del orden judicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos de la entrada y registro en lugar cerrado, ¿cuál de los siguientes NO se reputa edificio o lugar público?', 'La vivienda de cualquier español o extranjero residente se reputa domicilio (art. 554.2); los demás son lugares públicos (art. 547).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 44) · Arts. 547 y 554 LECrim', 'Se reputarán edificios o lugares públicos para la observancia de lo dispuesto en este capítulo: 1.º Los que estuvieren destinados a cualquier servicio oficial, militar o civil del Estado, de la Provincia o del Municipio, aunque habiten allí los encargados de dicho servicio o los de la conservación y custodia del edificio o lugar. 2.º Los que estuvieren destinados a cualquier establecimiento de reunión o recreo, fueren o no lícitos. […] 4.º Los buques del Estado. […] Se reputan domicilio, para los efectos de los artículos anteriores: 1.º Los Palacios Reales, estén o no habitados por el Monarca al tiempo de la entrada o registro. 2.º El edificio o lugar cerrado, o la parte de él destinada principalmente a la habitación de cualquier español o extranjero residente en España y de su familia', null, '1fde4775f264932b3bf28d19e8b17cd7bca3dae3cef24011ab6bf2fa504a5547', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1fde4775f264932b3bf28d19e8b17cd7bca3dae3cef24011ab6bf2fa504a5547')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los buques del Estado.', false), ('B', 'Los establecimientos de reunión o recreo, sean o no lícitos.', false), ('C', 'El edificio destinado a un servicio oficial del Municipio, aunque habite en él su conserje.', false), ('D', 'El edificio destinado principalmente a la vivienda de un extranjero residente en España y su familia.', true)) as v(label, body, ok)
)
