with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si, por urgencia en una investigación sobre bandas armadas o elementos terroristas, el Ministro del Interior ordena la medida del artículo 579 LECrim, ¿en qué plazo máximo debe comunicarla al juez competente?', 'Art. 579.3 LECrim: comunicación en 24 horas como máximo; el juez revoca o confirma en 72 horas desde que se ordenó la medida.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2022-3 (n.º 45) · Art. 579.3 LECrim', 'Esta medida se comunicará inmediatamente al juez competente y, en todo caso, dentro del plazo máximo de veinticuatro horas', null, '77dcf6553a75c94bad9727f67ee40209f44d3c292ea3c3aa03a8c2cda7012f54', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '77dcf6553a75c94bad9727f67ee40209f44d3c292ea3c3aa03a8c2cda7012f54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inmediatamente y, en todo caso, dentro de las veinticuatro horas.', true), ('B', 'Dentro de las setenta y dos horas siguientes.', false), ('C', 'Dentro de las cuarenta y ocho horas siguientes.', false), ('D', 'Dentro de las doce horas siguientes.', false)) as v(label, body, ok)
)
