with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Defensor del Pueblo, ¿quién acredita con su firma el nombramiento del Defensor del Pueblo que se publica en el «Boletín Oficial del Estado»?', 'El art. 4.1 LO 3/1981 atribuye la acreditación a los Presidentes de ambas Cámaras conjuntamente.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Réplica 2022-3 (n.º 23) · Art. 4 LO 3/1981', 'Senado acreditarán conjuntamente con sus firmas el nombramiento del Defensor del Pueblo que se publicará en el "Boletín Oficial del Estado".', null, '99fe2c6fd744857945e625dec05bc7c11c36db3630555f1194702d060626baf6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '99fe2c6fd744857945e625dec05bc7c11c36db3630555f1194702d060626baf6')
  returning id
), o as (
