with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2000, ¿qué necesita un extranjero para permanecer en España una vez agotado el período de estancia?', 'Art. 30.2 LO 4/2000; la estancia no puede superar 90 días (30.1).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-3 (n.º 62) · Art. 30.2 LO 4/2000', '2. Transcurrido dicho tiempo, para permanecer en España será preciso obtener o una prórroga de estancia o una autorización de residencia.', null, '697f7f7181c9970075654d10eb5c29b0790e6ed389484323f1778446f8a37894', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '697f7f7181c9970075654d10eb5c29b0790e6ed389484323f1778446f8a37894')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obtener una prórroga de estancia o una autorización de residencia.', true), ('B', 'Obtener un nuevo visado de tránsito.', false), ('C', 'Obtener una autorización de regreso.', false), ('D', 'Solicitar la inscripción en el padrón municipal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las infracciones en materia de extranjería, señale la respuesta INCORRECTA:', 'Solo el retraso de hasta tres meses en solicitar la renovación es leve (art. 52.b); con la autorización caducada más de tres meses y sin solicitud en plazo, la estancia es irregular, infracción grave (art. 53.1.a).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-3 (n.º 63) · Arts. 52 y 53 LO 4/2000', 'a) Encontrarse irregularmente en territorio español, por no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tener caducada más de tres meses la mencionada autorización, y siempre que el interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente.', null, '35726bc11894eca77699a21a02397db7d5153f42d39ebd1b0ad1706d572bf836', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '35726bc11894eca77699a21a02397db7d5153f42d39ebd1b0ad1706d572bf836')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Constituye infracción leve la omisión o el retraso en comunicar los cambios de domicilio a las autoridades españolas.', false), ('B', 'Constituye infracción leve tener caducada más de tres meses la autorización de residencia sin haber solicitado su renovación en plazo.', true), ('C', 'Constituye infracción grave encontrarse trabajando en España sin autorización de trabajo ni autorización de residencia válida.', false), ('D', 'Constituye infracción grave que el titular de una vivienda consienta la inscripción en el padrón de un extranjero que no reside realmente en ella.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
