with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los plazos máximos de resolución de expedientes de la disposición adicional primera de la Ley Orgánica 4/2000, señale la respuesta INCORRECTA:', 'En el plazo general el silencio es desestimatorio (DA 1.ª.1); el positivo opera en prórrogas, renovaciones y larga duración (DA 1.ª.2) y en las modificaciones de limitación (DA 1.ª.3).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2022-3 (n.º 64) · Disposición adicional primera LO 4/2000', 'Transcurrido el plazo para notificar las resoluciones de las solicitudes, salvo lo dispuesto en el apartado siguiente, éstas podrán entenderse desestimadas.', null, '177522ffdfbbd747060d7844da0fd962c30ecaae33a995245ddb5f49bfc6dd8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '177522ffdfbbd747060d7844da0fd962c30ecaae33a995245ddb5f49bfc6dd8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El plazo general máximo para notificar las resoluciones de las solicitudes de autorizaciones es de tres meses.', false), ('B', 'Las solicitudes de prórroga de la autorización de residencia se entienden concedidas si no se resuelven en tres meses.', false), ('C', 'Transcurrido el plazo general sin notificar la resolución, las solicitudes de autorización se entienden estimadas.', true), ('D', 'Las solicitudes de modificación de la limitación territorial o de ocupación de las autorizaciones iniciales de residencia y trabajo se resuelven en el plazo máximo de un mes.', false)) as v(label, body, ok)
)
