with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las disposiciones estatutarias comunes de los miembros de las Fuerzas y Cuerpos de Seguridad, señale la respuesta INCORRECTA:', 'El art. 6.7 LO 2/1986 establece la incompatibilidad con cualquier otra actividad pública o privada, salvo las exceptuadas por la legislación de incompatibilidades.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2022-3 (n.º 73) · Art. 6 LO 2/1986', '7. La pertenencia a las fuerzas y Cuerpos de Seguridad es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada, salvo aquellas actividades exceptuadas de la legislación sobre incompatibilidades.', null, '525763e3626f321eb3e49b6919dd6fec08f7eea71307371955a1c89a599cd585', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '525763e3626f321eb3e49b6919dd6fec08f7eea71307371955a1c89a599cd585')
  returning id
), o as (
