  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué principio de la Ley Orgánica de «Habeas Corpus» supone, entre otras cosas, legitimar a una pluralidad de personas para instar el procedimiento, en particular al Ministerio Fiscal y al Defensor del Pueblo?', 'La generalidad implica que nadie escapa al control judicial de la detención y que se legitima a una pluralidad de personas para instarlo.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Réplica 2022-3 (n.º 47) · Exposición de motivos LO 6/1984 (principios)', 'el procedimiento establecido por esta ley se caracteriza por la generalidad que implica, por un lado, que ningún particular o agente de la autoridad pueda sustraerse al control judicial de la legalidad de la detención de las personas sin que quepa en este sentido excepción de ningún género, ni siquiera en lo referente a la Autoridad Militar, y que supone, por otro lado, la legitimación de una pluralidad de personas para instar el procedimiento', null, 'fc7d3609a93b4d22c51916f8e9bfc1c39e7356404eeb9032062ba43052f5273b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fc7d3609a93b4d22c51916f8e9bfc1c39e7356404eeb9032062ba43052f5273b')
  returning id
