with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El artículo 3 de la Ley Orgánica 3/2007, al definir el principio de igualdad de trato entre mujeres y hombres, menciona especialmente la ausencia de discriminaciones:', 'El art. 3 LO 3/2007 destaca expresamente la maternidad, las obligaciones familiares y el estado civil.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2022-3 (n.º 11) · Art. 3 LO 3/2007', 'El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.', null, '41d84988d53142798b56451e22710cd3b744b5d66acd188d6e0d535ab0c9329e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '41d84988d53142798b56451e22710cd3b744b5d66acd188d6e0d535ab0c9329e')
