with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la ONU, en la Asamblea General las decisiones sobre cuestiones distintas de las de vital importancia (paz y seguridad, admisión de nuevos miembros y asuntos presupuestarios) se adoptan por:', 'Las cuestiones de vital importancia requieren dos tercios; las demás, mayoría simple.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/main-bodies'), 'Réplica 2022-3 (n.º 28) · ONU, Asamblea General (toma de decisiones)', 'La toma de decisiones en la Asamblea General requiere una mayoría de dos tercios cuando se trata de asuntos de vital importancia; como aquellos referidos a la paz y la seguridad, la admisión de nuevos miembros y los asuntos presupuestarios. Las decisiones en otras cuestiones se toman por mayoría simple.', null, '3287b3eb3e70d835731d7c26c3d06a5096d8465efe9f1e9e486b59351f389910', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3287b3eb3e70d835731d7c26c3d06a5096d8465efe9f1e9e486b59351f389910')
