with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el Comité de Derechos Humanos del Pacto Internacional de Derechos Civiles y Políticos, señale la respuesta CORRECTA:', 'Art. 39.1 PIDCP. El informe anual va a la Asamblea General por conducto del Consejo Económico y Social (art. 45), el quórum es de doce miembros (art. 39.2.a) y el Pacto se aplica a los Estados federales sin limitación ni excepción alguna (art. 50).', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10733'), 'Réplica 2022-3 (n.º 5) · Art. 39.1 PIDCP', '1. El Comité elegirá su Mesa por un período de dos años Los miembros de la Mesa podrán ser reelegidos.', null, 'c45b7f24aad7ec85f0b9c4b29f26cb4fc3657c92a70ab53f8f754df44f827d73', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c45b7f24aad7ec85f0b9c4b29f26cb4fc3657c92a70ab53f8f754df44f827d73')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Comité presenta cada año su informe a la Asamblea General por conducto del Consejo de Seguridad.', false), ('B', 'El Comité elige su Mesa por un período de dos años y los miembros de la Mesa pueden ser reelegidos.', true), ('C', 'El reglamento del Comité fija el quórum en ocho miembros.', false), ('D', 'Las disposiciones del Pacto se aplican a los Estados federales con las excepciones que estos declaren al ratificarlo.', false)) as v(label, body, ok)
)
