with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 16 del Pacto Internacional de Derechos Económicos, Sociales y Culturales, los informes de los Estados Partes sobre las medidas adoptadas y los progresos realizados se presentan:', 'El art. 16.2.a) PIDESC: los informes van al Secretario General, que transmite copias al Consejo Económico y Social.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10734'), 'Réplica 2022-3 (n.º 4) · Art. 16.2 PIDESC', 'a) Todos los informes serán presentados al Secretario general de las Naciones Unidas, quien transmitirá copias al Consejo Económico y Social para que las examine, conforme a lo dispuesto en el presente Pacto.', null, '4fadef99331bd6a6c63f72bf36c1fc184e2185d99fc01b6b92d309f05fa084ea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4fadef99331bd6a6c63f72bf36c1fc184e2185d99fc01b6b92d309f05fa084ea')
