with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Prevención de Riesgos Laborales, ante infracciones de excepcional gravedad en seguridad y salud en el trabajo, ¿quién puede acordar la suspensión temporal de las actividades o, en caso extremo, el cierre del centro de trabajo?', 'El art. 53 de la Ley 31/1995 atribuye la suspensión o el cierre al Gobierno o a los órganos de gobierno autonómicos competentes.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Réplica 2022-3 (n.º 13) · Art. 53 Ley 31/1995', 'El Gobierno o, en su caso, los órganos de gobierno de las Comunidades Autónomas con competencias en la materia, cuando concurran circunstancias de excepcional gravedad en las infracciones en materia de seguridad y salud en el trabajo, podrán acordar la suspensión de las actividades laborales por un tiempo determinado o, en caso extremo, el cierre del centro de trabajo correspondiente', null, '5ae1000cad17bb8bb00a4c5cbe1c309e9601f9bac11bb0bd421890a1974e843e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ae1000cad17bb8bb00a4c5cbe1c309e9601f9bac11bb0bd421890a1974e843e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Inspección de Trabajo y Seguridad Social, mediante acta de infracción.', false), ('B', 'El Gobierno o, en su caso, los órganos de gobierno de las Comunidades Autónomas con competencias en la materia.', true), ('C', 'El Instituto Nacional de Seguridad y Salud en el Trabajo.', false), ('D', 'El Juzgado de lo Social, a instancia de los delegados de prevención.', false)) as v(label, body, ok)
)
