with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 67/2010, un Departamento de la Administración General del Estado con varios centros de trabajo que tengan Comité de Seguridad y Salud puede acordar con su personal la creación de:', 'El art. 6.6 RD 67/2010 prevé el Comité Intercentros por acuerdo con el personal.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-2161'), 'Réplica 2022-3 (n.º 14) · Art. 6.6 RD 67/2010', '6. Los Departamentos y organismos públicos que cuenten con varios centros de trabajo dotados de Comité de Seguridad y Salud podrán acordar con su personal la creación de un Comité Intercentros, con las funciones que el acuerdo le atribuya.', null, 'dee501132fa224b0810dc4c9b6a11595ccc1ba7a10622c2f7e8322eade2409ee', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dee501132fa224b0810dc4c9b6a11595ccc1ba7a10622c2f7e8322eade2409ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un Comité Central de Seguridad y Salud, con las funciones que fije la Subsecretaría.', false), ('B', 'Una Comisión Delegada de Prevención, presidida por el titular del Departamento.', false), ('C', 'Un Comité Coordinador de Prevención, con funciones fijadas por real decreto.', false), ('D', 'Un Comité Intercentros, con las funciones que le atribuya el acuerdo.', true)) as v(label, body, ok)
)
