with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 179/2005, sobre prevención de riesgos laborales en la Guardia Civil, ¿de qué plazo dispone la Dirección General de la Guardia Civil, a través de su Servicio de Prevención, para formular alegaciones a la propuesta de requerimiento de la Inspección de Personal y Servicios de Seguridad?', 'El RD 179/2005 fija 30 días hábiles; si no hay alegaciones, la propuesta adquiere carácter definitivo automáticamente.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-3241'), 'Réplica 2022-3 (n.º 15) · RD 179/2005 (control externo por la Inspección de Personal y Servicios de Seguridad)', 'a través del Servicio de Prevención de la Dirección General de la Guardia Civil, que podrá formular alegaciones en el plazo de 30 días hábiles desde su notificación.', null, 'c21caa105126bd1c2dba79baf2cbce946fbc007019394a503fa0305da6d0f0fd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c21caa105126bd1c2dba79baf2cbce946fbc007019394a503fa0305da6d0f0fd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '30 días hábiles desde su notificación.', true), ('B', '15 días hábiles desde su notificación.', false), ('C', '10 días naturales desde su notificación.', false), ('D', 'Un mes desde su notificación.', false)) as v(label, body, ok)
)
