with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el cuantificador «sendos», según el Diccionario panhispánico de dudas, señale la respuesta INCORRECTA:', 'El DPD advierte que sendos no debe usarse como equivalente de dos o ambos.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 2, 'es', true, (select id from public.sources where url = 'https://www.rae.es/dpd/'), 'Réplica 2022-3 (n.º 96) · DPD, «sendos»', '1. Cuantificador distributivo que funciona como determinante antecediendo siempre a un sustantivo plural y significa ''uno (a o para) cada una de las personas o cosas que se mencionan''. […] 2. No debe emplearse como equivalente de dos o ambos', null, '528ae6ad80d3d5316253a51be2bf6dbc0b92063771322f918f6774e1433a6d24', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '528ae6ad80d3d5316253a51be2bf6dbc0b92063771322f918f6774e1433a6d24')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Funciona como determinante.', false), ('B', 'Puede emplearse como equivalente de «ambos» o «los dos».', true), ('C', 'Antecede siempre a un sustantivo plural.', false), ('D', 'Significa ''uno para cada una de las personas o cosas que se mencionan''.', false)) as v(label, body, ok)
