  select 'Según la ITC 13 del Reglamento de Explosivos, el equipamiento eléctrico que debe seguir funcionando para prevenir un peligro adicional en zonas con presencia de explosivos:', 'La ITC exige uno o varios medios de desconexión del suministro eléctrico a las áreas clasificadas, salvo para el equipamiento que debe seguir funcionando, que irá en un circuito separado.', 'gcexamen_2022_3', (select id from public.topics where slug = 'gcexamen-2022-3'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-2313'), 'Réplica 2022-3 (n.º 100) · Reglamento de Explosivos, ITC 13 (instalaciones eléctricas)', 'El equipamiento eléctrico que debe continuar funcionando para prevenir un peligro adicional debe pertenecer a un circuito separado del resto de la instalación y no debe combinarse', null, 'ffd765648da839e31cfd19929ba64babde98a0c7ada4e2042589e9f4fb4bf3df', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ffd765648da839e31cfd19929ba64babde98a0c7ada4e2042589e9f4fb4bf3df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe conectarse al mismo circuito que el resto de la instalación para no interrumpirse.', false), ('B', 'Debe pertenecer a un circuito separado del resto de la instalación.', true), ('C', 'Debe desconectarse junto con el resto de la instalación en caso de peligro.', false), ('D', 'Puede combinarse con cualquier otro circuito si dispone de toma de tierra.', false)) as v(label, body, ok)
)
