with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes supuestos NO figura en el artículo 152 del Código Civil como causa de cese de la obligación de dar alimentos?', 'El art. 152 CC enumera: muerte del alimentista, reducción de la fortuna del obligado, que el alimentista pueda ejercer un oficio o haya mejorado de fortuna, falta que dé lugar a desheredación y necesidad derivada de mala conducta del descendiente. El matrimonio del alimentista no está en la lista.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2026 (n.º 35) · Art. 152 Código Civil', 'Cesará también la obligación de dar alimentos: 1.º Por muerte del alimentista. 2.º Cuando la fortuna del obligado a darlos se hubiere reducido hasta el punto de no poder satisfacerlos sin desatender sus propias necesidades y las de su familia. 3.º Cuando el alimentista pueda ejercer un oficio, profesión o industria', null, '52599d32ab6ffec771d57ee17b9fbbb26d3002a2173e2dafa64895a7aa375372', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '52599d32ab6ffec771d57ee17b9fbbb26d3002a2173e2dafa64895a7aa375372')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el alimentista contraiga matrimonio.', true), ('B', 'La muerte del alimentista.', false), ('C', 'Que la fortuna del obligado se reduzca hasta no poder satisfacerlos sin desatender sus propias necesidades y las de su familia.', false), ('D', 'Que el alimentista pueda ejercer un oficio, profesión o industria, de modo que la pensión no le sea necesaria para su subsistencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 267 del Código Civil, la guarda de hecho de las personas con discapacidad se extingue en los casos siguientes. Señale la afirmación INCORRECTA:', 'La extinción por decisión ajena al guardador corresponde a la autoridad judicial, a solicitud del Ministerio Fiscal o de quien se interese por ejercer el apoyo; a la entidad pública solo hay que comunicarle previamente el desistimiento del guardador.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Réplica 2026 (n.º 36) · Art. 267 Código Civil', 'La guarda de hecho se extingue: 1.º Cuando la persona a quien se preste apoyo solicite que este se organice de otro modo. 2.º Cuando desaparezcan las causas que la motivaron. […] 4.º Cuando, a solicitud del Ministerio Fiscal o de quien se interese por ejercer el apoyo de la persona bajo guarda, la autoridad judicial lo considere conveniente.', null, 'ab5498dba7d0e83477daffbb0c3e1aa610d0be793471e6d79edb2415bc78ab3f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ab5498dba7d0e83477daffbb0c3e1aa610d0be793471e6d79edb2415bc78ab3f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando la persona a quien se preste apoyo solicite que este se organice de otro modo.', false), ('B', 'Cuando desaparezcan las causas que la motivaron.', false), ('C', 'Cuando, a solicitud del Ministerio Fiscal, la autoridad judicial lo considere conveniente.', false), ('D', 'Cuando así lo acuerde de oficio la entidad pública de asistencia a las personas con discapacidad.', true)) as v(label, body, ok)
)
