with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Entre los valores fundamentales del Código de Conducta del personal de la Guardia Civil, ¿cuál de las siguientes pautas corresponde a la dignidad?', 'El art. 8 (Dignidad) recoge el sentido de la trascendencia de la función y el buen nombre de la Institución, y la responsabilidad, seriedad y respeto; las otras opciones corresponden al espíritu de sacrificio (art. 9), la imparcialidad y neutralidad (art. 6) y la lealtad (art. 3).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477'), 'Réplica 2026 (n.º 87) · Art. 8 Código de Conducta (RD 176/2022)', 'Artículo 8. Dignidad. 1. Prestarán su servicio con el mayor sentido de la trascendencia de su función y velarán por el buen nombre de la Institución', null, '0a61d325fa46bce89c2b05611e86713a0402b3a251959798af855001d905e109', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0a61d325fa46bce89c2b05611e86713a0402b3a251959798af855001d905e109')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Antepondrán el bien común al suyo propio, aceptando con abnegación las exigencias del deber.', false), ('B', 'Prestarán su servicio con el mayor sentido de la trascendencia de su función y velarán por el buen nombre de la Institución.', true), ('C', 'Actuarán sin prejuicios ni trato discriminatorio hacia ninguna persona o colectivo.', false), ('D', 'Mostrarán fidelidad, respeto y sinceridad hacia los demás componentes del Cuerpo, cualquiera que sea su empleo.', false)) as v(label, body, ok)
)
