with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto del artículo 30 de la Constitución, sobre derechos y deberes de los ciudadanos, ¿qué afirmación es INCORRECTA?', 'El art. 30.3 CE permite establecer un servicio civil para fines de interés general; los apartados 2 y 4 recogen el resto de opciones.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2026 (n.º 17) · Art. 30 CE', '2. La ley fijará las obligaciones militares de los españoles y regulará, con las debidas garantías, la objeción de conciencia […] 3. Podrá establecerse un servicio civil para el cumplimiento de fines de interés general. 4. Mediante ley podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.', null, 'e157696f362839908e4886901d3006fe0ba0af3c1a487cd35dfcec6541ae2ad2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e157696f362839908e4886901d3006fe0ba0af3c1a487cd35dfcec6541ae2ad2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Corresponde a la ley fijar las obligaciones militares de los españoles.', false), ('B', 'La ley regula, con las debidas garantías, la objeción de conciencia.', false), ('C', 'Una ley puede regular los deberes de los ciudadanos en casos de grave riesgo, catástrofe o calamidad pública.', false), ('D', 'Para el cumplimiento de fines de interés general solo puede establecerse un servicio de carácter militar.', true)) as v(label, body, ok)
)
