  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Constitución, la imposibilidad del Rey para ejercer su autoridad, para que entre a ejercer la Regencia el Príncipe heredero mayor de edad, debe ser reconocida por:', 'El art. 59.2 CE exige que la inhabilitación sea reconocida por las Cortes Generales.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2026 (n.º 19) · Art. 59.2 CE', '2. Si el Rey se inhabilitare para el ejercicio de su autoridad y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero de la Corona, si fuere mayor de edad.', null, '5408f46627d76d6926e16d014fcd47e5e95bd68a195d0a28745d94fe7fdfb978', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5408f46627d76d6926e16d014fcd47e5e95bd68a195d0a28745d94fe7fdfb978')
