with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto del Congreso de los Diputados, según el artículo 68 de la Constitución, señale la afirmación CORRECTA:', 'El art. 68 CE fija la representación proporcional (68.3), el pleno uso de los derechos políticos (68.5), elecciones entre 30 y 60 días tras el fin del mandato y convocatoria del Congreso electo dentro de los 25 días siguientes (68.6).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2026 (n.º 20) · Art. 68 CE', '3. La elección se verificará en cada circunscripción atendiendo a criterios de representación proporcional. […] 5. Son electores y elegibles todos los españoles que estén en pleno uso de sus derechos políticos. […] 6. Las elecciones tendrán lugar entre los treinta días y sesenta días desde la terminación del mandato. El Congreso electo deberá ser convocado dentro de los veinticinco días siguientes a la celebración de las elecciones.', null, '1b7220ff2169a524694da82d9c3087b85f4e25742be89dc167d45c3d3988ffb4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1b7220ff2169a524694da82d9c3087b85f4e25742be89dc167d45c3d3988ffb4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Congreso electo debe ser convocado dentro de los quince días siguientes a la celebración de las elecciones.', false), ('B', 'En cada circunscripción la elección atiende a criterios de representación mayoritaria.', false), ('C', 'Las elecciones tendrán lugar entre los treinta y los sesenta días desde la terminación del mandato.', true), ('D', 'Son electores y elegibles los españoles en pleno uso de sus derechos civiles y sociales.', false)) as v(label, body, ok)
)
