with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para que el Gobierno adopte las medidas del artículo 155 de la Constitución frente a una Comunidad Autónoma que, desoyendo su requerimiento, atenta gravemente contra el interés general de España, ¿qué se exige?', 'El art. 155.1 CE exige requerimiento previo al Presidente autonómico y, si no es atendido, la aprobación por mayoría absoluta del Senado.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Réplica 2026 (n.º 21) · Art. 155.1 CE', 'el Gobierno, previo requerimiento al Presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, podrá adoptar las medidas necesarias', null, 'd57c716a7969b4a8adce960077b7d062a9e6debcf7b64e6f2a96b83d8ec22a79', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd57c716a7969b4a8adce960077b7d062a9e6debcf7b64e6f2a96b83d8ec22a79')
  returning id
), o as (
