with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con la motivación de las opiniones consultivas del Tribunal Europeo de Derechos Humanos (art. 49 del Convenio), señale la afirmación INCORRECTA:', 'El art. 49 CEDH exige motivación, permite opiniones separadas y ordena comunicar la opinión al Comité de Ministros (órgano del Consejo de Europa), no a una institución de la Unión Europea.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-10148'), 'Réplica 2026 (n.º 3) · Art. 49 CEDH', 'Artículo 49. Motivación de las opiniones consultivas. 1. La opinión del Tribunal estará motivada. 2. Si la opinión no expresa en todo o en parte la opinión unánime de los jueces, todo juez tendrá derecho a unir a ellas su opinión por separado. 3. La opinión del Tribunal será comunicada al Comité de Ministros.', null, '45f25c150aeadd7351164eb93d466f70c39b3d72aa46cae1138a39acfc3bb479', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '45f25c150aeadd7351164eb93d466f70c39b3d72aa46cae1138a39acfc3bb479')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La opinión del Tribunal debe estar motivada.', false), ('B', 'Cualquier juez puede unir su opinión por separado si la opinión no refleja, en todo o en parte, el parecer unánime de los jueces.', false), ('C', 'La opinión del Tribunal se comunicará al Consejo de la Unión Europea.', true), ('D', 'La opinión del Tribunal se comunicará al Comité de Ministros.', false)) as v(label, body, ok)
)
