with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Código Penal, si en el hecho participan varias personas, ¿quiénes quedan exentos de responsabilidad penal por el delito intentado?', 'El art. 16.3 CP exige, además del desistimiento, que el sujeto impida o intente impedir seriamente la consumación, sin perjuicio de responder por los actos ya ejecutados si constituyen otro delito.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2026 (n.º 37) · Art. 16.3 Código Penal', '3. Cuando en un hecho intervengan varios sujetos, quedarán exentos de responsabilidad penal aquél o aquéllos que desistan de la ejecución ya iniciada, e impidan o intenten impedir, seria, firme y decididamente, la consumación', null, '037ff4c3abfa473658075e2bfd98d48281e493d028734948598a4e1111da52e0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '037ff4c3abfa473658075e2bfd98d48281e493d028734948598a4e1111da52e0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Todos los intervinientes, en cuanto uno solo de ellos desista de la ejecución.', false), ('B', 'Quienes desistan de la ejecución ya iniciada e impidan o intenten impedir, seria, firme y decididamente, la consumación.', true), ('C', 'Solo quienes desistan antes de que haya comenzado la ejecución.', false), ('D', 'Quienes desistan de la ejecución ya iniciada, aunque no hagan nada para impedir la consumación.', false)) as v(label, body, ok)
)
