select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Por su naturaleza y duración, la pena de prohibición de aproximarse a la víctima o a sus familiares u otras personas que determine el juez, impuesta por tiempo de un mes a menos de seis meses, es una pena:', 'El art. 33 CP clasifica esta prohibición como grave si supera cinco años, menos grave de seis meses a cinco años y leve de un mes a menos de seis meses.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Réplica 2026 (n.º 40) · Art. 33.4.e) Código Penal', 'e) La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas que determine el juez o tribunal, por tiempo de un mes a menos de seis meses.', null, 'b411f05b58f3a8c1d530cb689b2b0ac51ed217cf099f0572f9f9f1ff205ca546', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b411f05b58f3a8c1d530cb689b2b0ac51ed217cf099f0572f9f9f1ff205ca546')
  returning id
