  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En cuanto a las visitas del Subcomité para la Prevención a los lugares de privación de libertad, según el Protocolo Facultativo de la Convención contra la Tortura, señale la afirmación CORRECTA:', 'El art. 13 del Protocolo prevé un programa de visitas fijado primeramente por sorteo, notificado para que los Estados adopten las disposiciones prácticas sin demora, y visitas realizadas por dos miembros como mínimo, con posibles expertos acompañantes.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Réplica 2026 (n.º 8) · Art. 13 Protocolo Facultativo de la Convención contra la Tortura', '1. El Subcomité para la Prevención establecerá, primeramente por sorteo, un programa de visitas periódicas […] para que éstos puedan, sin demora, adoptar las disposiciones prácticas necesarias para la realización de las visitas. 3. Las visitas serán realizadas por dos miembros como mínimo del Subcomité para la Prevención. Estos miembros podrán ir acompañados, si fuere necesario, de expertos', null, 'e868dc7597705390a80f08a5c64a2cc1600e1f0d00b694d41e71553a1454c130', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e868dc7597705390a80f08a5c64a2cc1600e1f0d00b694d41e71553a1454c130')
  returning id
