with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Aduanero de la Unión, la «notificación de reexportación» es el acto por el que una persona expresa la voluntad de sacar del territorio aduanero de la Unión mercancías no pertenecientes a la Unión que se encuentran:', 'El art. 5.14 define la notificación de reexportación para mercancías en zona franca o depósito temporal; la declaración de reexportación (5.13) se usa para las demás mercancías no pertenecientes a la Unión.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02013R0952-20221212'), 'Réplica 2026 (n.º 98) · Art. 5.14 Código Aduanero de la Unión', '14) «notificación de reexportación» : el acto por el que una persona expresa, en la forma y el modo establecidos, la voluntad de sacar del territorio aduanero de la Unión mercancías no pertenecientes a la Unión en régimen de zona franca o en depósito temporal;', null, '8908def8aef96393691536cac4ff18507a04d989b859fc50a48ca438bdd23e8f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8908def8aef96393691536cac4ff18507a04d989b859fc50a48ca438bdd23e8f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Despachadas a libre práctica.', false), ('B', 'En régimen de perfeccionamiento pasivo.', false), ('C', 'En régimen de exportación definitiva.', false), ('D', 'En régimen de zona franca o en depósito temporal.', true)) as v(label, body, ok)
)
