with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Tratado de Funcionamiento de la Unión Europea prevé que sea el Presidente del Consejo quien lo convoque. ¿Quién de los siguientes NO puede promover esa convocatoria?', 'El art. 237 TFUE solo prevé la convocatoria a iniciativa del Presidente, de uno de los miembros del Consejo o de la Comisión.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016E/TXT'), 'Réplica 2026 (n.º 27) · Art. 237 TFUE', 'El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión.', null, 'b883537b7a7ed4084059bb9520bf2ccdd0d0f5cad3d6e18e0c18df1730bb8deb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b883537b7a7ed4084059bb9520bf2ccdd0d0f5cad3d6e18e0c18df1730bb8deb')
