with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el procedimiento legislativo ordinario previsto en el Tratado de Funcionamiento de la Unión Europea, señale la afirmación INCORRECTA:', 'El art. 289.1 TFUE define el procedimiento legislativo ordinario como la adopción conjunta por el Parlamento Europeo y el Consejo, a propuesta de la Comisión, de un reglamento, una directiva o una decisión.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:12016E/TXT'), 'Réplica 2026 (n.º 26) · Art. 289.1 TFUE', '1. El procedimiento legislativo ordinario consiste en la adopción conjunta por el Parlamento Europeo y el Consejo, a propuesta de la Comisión, de un reglamento, una directiva o una decisión.', null, 'a93df53df0aee4d3359f95743e7312e102ac4a8f484deebe4d3d72ed908adb68', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a93df53df0aee4d3359f95743e7312e102ac4a8f484deebe4d3d72ed908adb68')
  returning id
), o as (
