  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Consiste en la adopción conjunta del acto por el Parlamento Europeo y el Consejo.', false), ('B', 'Consiste en la adopción del acto por el Parlamento Europeo en solitario, previa consulta a la Comisión.', true), ('C', 'Se sigue a propuesta de la Comisión.', false), ('D', 'Puede concluir con la adopción de un reglamento, una directiva o una decisión.', false)) as v(label, body, ok)
)
