with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO es una de las instituciones de la Unión enumeradas en el artículo 13 del Tratado de la Unión Europea?', 'El art. 13 TUE enumera siete instituciones: Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas. El Comité Económico y Social es un órgano consultivo.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Réplica 2026 (n.º 24) · Art. 13.1 TUE', 'Las instituciones de la Unión son: El Parlamento Europeo, El Consejo Europeo, El Consejo, La Comisión Europea (denominada en lo sucesivo «Comisión»), El Tribunal de Justicia de la Unión Europea, El Banco Central Europeo, El Tribunal de Cuentas.', null, '977d1fa18db993dc21bf6b609df95fe104cd855aaa77168b10c4c4cbb9f72d6b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '977d1fa18db993dc21bf6b609df95fe104cd855aaa77168b10c4c4cbb9f72d6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Tribunal de Cuentas.', false), ('B', 'El Comité Económico y Social Europeo.', true), ('C', 'El Consejo Europeo.', false), ('D', 'El Parlamento Europeo.', false)) as v(label, body, ok)
)
