with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Estatuto de la víctima del delito, el acceso de las víctimas a los servicios de justicia restaurativa exige una serie de requisitos. Señale el INCORRECTO:', 'El art. 15.1 exige reconocimiento de los hechos, consentimiento informado de la víctima, consentimiento del infractor, ausencia de riesgo o de nuevos perjuicios para la víctima y que la mediación no esté prohibida por la ley para el delito cometido.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Réplica 2026 (n.º 50) · Art. 15.1 Ley 4/2015', 'a) el infractor haya reconocido los hechos esenciales de los que deriva su responsabilidad; […] c) el infractor haya prestado su consentimiento; d) el procedimiento de mediación no entrañe un riesgo para la seguridad de la víctima […] e) no esté prohibida por la ley para el delito cometido.', null, '8f3c526e5bd9465f18b3935d3894229cf1f7b80e6ab2b101f18b703f21d4bb2d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8f3c526e5bd9465f18b3935d3894229cf1f7b80e6ab2b101f18b703f21d4bb2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el infractor haya reconocido los hechos esenciales de los que deriva su responsabilidad.', false), ('B', 'Que tanto la víctima como el infractor hayan prestado su consentimiento.', false), ('C', 'Que el procedimiento de mediación no entrañe un riesgo para la seguridad de la víctima.', false), ('D', 'Que el delito cometido sea de los que la ley excluye expresamente de la mediación.', true)) as v(label, body, ok)
)
