with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando no exista autor conocido del delito, la Policía Judicial conserva el atestado sin enviarlo al Ministerio Fiscal ni a la autoridad judicial, salvo en determinados casos. Señale el supuesto INCORRECTO:', 'El art. 284.2 LECrim fija en setenta y dos horas, no en cuarenta y ocho, el plazo tras el cual una diligencia con resultado obliga a remitir el atestado.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2026 (n.º 42) · Art. 284.2 LECrim', 'a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción; b) Que se practique cualquier diligencia después de transcurridas setenta y dos horas desde la apertura del atestado y éstas hayan tenido algún resultado; o c) Que el Ministerio Fiscal o la autoridad judicial soliciten la remisión.', null, '56108bba2e62f9c8538219c9bdaa29208b170ce8950fa3d7b83a4debeecd8dc9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '56108bba2e62f9c8538219c9bdaa29208b170ce8950fa3d7b83a4debeecd8dc9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que se trate de delitos contra la vida, la integridad física o la libertad e indemnidad sexuales.', false), ('B', 'Que se trate de delitos relacionados con la corrupción.', false), ('C', 'Que el Ministerio Fiscal o la autoridad judicial soliciten la remisión.', false), ('D', 'Que se practique alguna diligencia, con resultado, transcurridas cuarenta y ocho horas desde la apertura del atestado.', true)) as v(label, body, ok)
)
