with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si una persona muere a consecuencia de un accidente en la vía férrea ocurrido con un tren en marcha, la Ley de Enjuiciamiento Criminal dispone que:', 'El art. 354 LECrim limita la detención del tren al tiempo preciso para separar los cadáveres, dejando constancia previa de su situación; se avisa a la Autoridad que deba instruir sin perjuicio de que el tren siga su marcha.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2026 (n.º 43) · Art. 354 LECrim', 'únicamente se detendrá éste el tiempo preciso para separar el cadáver o cadáveres de la vía, haciéndose constar previamente su situación y estado', null, 'fcee0b24c10d6e506e420660c3eef3bec199961922495761b74893a1589e3114', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fcee0b24c10d6e506e420660c3eef3bec199961922495761b74893a1589e3114')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El tren no podrá reanudar la marcha hasta que el Juez practique el levantamiento del cadáver.', false), ('B', 'El tren se detendrá únicamente el tiempo preciso para separar el cadáver o cadáveres de la vía, haciendo constar previamente su situación y estado.', true), ('C', 'El tren no se detendrá en ningún caso, y el cadáver se retirará en la estación siguiente.', false), ('D', 'El tren permanecerá detenido hasta la llegada de la Policía Judicial de la demarcación.', false)) as v(label, body, ok)
)
