with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 490 de la Ley de Enjuiciamiento Criminal, cualquier persona puede detener:', 'El art. 490 LECrim enumera, entre otros, al que intente cometer un delito en el momento de ir a cometerlo, al delincuente in fraganti, a los fugados y al procesado o condenado en rebeldía.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Réplica 2026 (n.º 45) · Art. 490 LECrim', 'Cualquier persona puede detener: […] 6.º Al que se fugare estando detenido o preso por causa pendiente.', null, '6ddf9ae7d90c3633a3b4ad3ce7422c492d100c929262522a7645fd2a6fba2d70', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6ddf9ae7d90c3633a3b4ad3ce7422c492d100c929262522a7645fd2a6fba2d70')
  returning id
), o as (
