with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley General de Telecomunicaciones, las medidas sobre el acceso o el uso de servicios y aplicaciones por los usuarios finales respetarán los derechos y libertades fundamentales tal como se garantizan en varios textos. ¿Cuál de los siguientes NO se menciona?', 'El art. 56.1 de la Ley 11/2022 cita el CEDH, la Carta de Derechos Fundamentales de la UE, los principios generales del Derecho comunitario y la Constitución Española.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757'), 'Réplica 2026 (n.º 80) · Art. 56.1 Ley 11/2022', 'como queda garantizado en el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales, en la Carta de Derechos Fundamentales de la Unión Europea, en los principios generales del Derecho comunitario y en la Constitución Española.', null, '060e23b4754c4ff09cd68bed30c45a300e9c335808c89ecb495a4390a9efc607', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '060e23b4754c4ff09cd68bed30c45a300e9c335808c89ecb495a4390a9efc607')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales.', false), ('B', 'La Carta de Derechos Fundamentales de la Unión Europea.', false), ('C', 'La Declaración Universal de Derechos Humanos.', true), ('D', 'La Constitución Española.', false)) as v(label, body, ok)
)
