insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 12/1995, de 12 de diciembre, de Represión del Contrabando (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
