with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la investigación, persecución y represión de los delitos de contrabando, el Servicio de Vigilancia Aduanera actúa en coordinación con las Fuerzas y Cuerpos de Seguridad del Estado y tiene, a todos los efectos legales, carácter de:', 'La disposición adicional primera de la LO 12/1995 le atribuye carácter colaborador de las FCSE.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Réplica 2026 (n.º 96) · Disposición adicional primera LO 12/1995', 'El Servicio de Vigilancia Aduanera, en la investigación, persecución y represión de los delitos de contrabando, actuará en coordinación con las Fuerzas y Cuerpos de Seguridad del Estado y tendrá, a todos los efectos legales, carácter colaborador de los mismos.', null, 'd9e939bcbab4e122b2d63c0a9294d1f2341da9aaa7752f727bfdeaadf004a805', false
