with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 18/2003, de Cooperación con la Corte Penal Internacional, ¿cuál de los siguientes es autoridad competente para su aplicación?', 'El art. 4 enumera como autoridades competentes al Gobierno, los Ministerios de Justicia, Asuntos Exteriores, Defensa e Interior, los órganos judiciales ordinarios (en particular, la Audiencia Nacional), los militares (en particular, el Tribunal Militar Central) y el Ministerio Fiscal.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-22715'), 'Réplica 2026 (n.º 11) · Art. 4 LO 18/2003', 'Son autoridades competentes para la aplicación de esta ley: a) El Gobierno. b) El Ministerio de Justicia. […] e) Los órganos judiciales de la jurisdicción ordinaria y, en particular, la Audiencia Nacional. f) Los órganos judiciales militares y, en particular, el Tribunal Militar Central. g) El Ministerio Fiscal.', null, '8a901c7e1db68db97a8e1b8f1b98570776b57d6077f88217a35f86509919313e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8a901c7e1db68db97a8e1b8f1b98570776b57d6077f88217a35f86509919313e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consejo General del Poder Judicial.', false), ('B', 'El Tribunal Constitucional.', false), ('C', 'El Defensor del Pueblo.', false), ('D', 'Los órganos judiciales militares y, en particular, el Tribunal Militar Central.', true)) as v(label, body, ok)
)
