with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre las reuniones de las asociaciones profesionales en centros oficiales de la Guardia Civil, señale la afirmación CORRECTA:', 'El art. 47 LO 11/2007: reuniones fuera de las horas de trabajo, solicitud escrita con setenta y dos horas de antelación, posible denegación por afectar al servicio y celebración si no hay objeción expresa antes de las veinticuatro horas anteriores.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Réplica 2026 (n.º 75) · Art. 47 LO 11/2007', 'Estas reuniones se realizarán fuera de las horas de trabajo y sin perturbar la marcha de los servicios. Su celebración requerirá solicitud previa al jefe de la unidad, centro u órgano, quien podrá denegarla, cuando considere que el servicio pueda verse afectado. 2. La autorización deberá solicitarse por escrito, con una antelación mínima de setenta y dos horas', null, 'e1b6383b80883e5dd45d0cf41955de9f9084953f982de896994cf8b7c108d026', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e1b6383b80883e5dd45d0cf41955de9f9084953f982de896994cf8b7c108d026')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jefe de la unidad, centro u órgano puede denegarlas cuando considere que el servicio pueda verse afectado.', true), ('B', 'Pueden celebrarse durante las horas de trabajo si así lo decide la asociación.', false), ('C', 'Deben solicitarse por escrito con una antelación mínima de veinticuatro horas.', false), ('D', 'Pueden celebrarse sin otro requisito si no hay objeciones expresas antes de las cuarenta y ocho horas anteriores.', false)) as v(label, body, ok)
)
