with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la LO 11/2007, ¿cuándo puede un guardia civil saltarse el cauce ordinario y llevar su queja al órgano competente en materia de personal y, como último recurso, a la inspección dependiente de la Secretaría de Estado de Seguridad?', 'El art. 33.2 LO 11/2007 exige el cauce reglado y permite acudir directamente al órgano de personal y, en última instancia, a la inspección de la Secretaría de Estado de Seguridad cuando la queja no se atienda debidamente o se refiera al mando inmediato superior.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Réplica 2026 (n.º 76) · Art. 33.2 LO 11/2007', '2. Las quejas se presentarán por el cauce reglado. Si no fueran debidamente atendidas o se refiriesen al mando inmediato superior, podrán presentarse directamente ante el órgano responsable de personal', null, '33210129a555f0c0f64e039d2e0884c6d722deee9f095849df336cb8fcbf644c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '33210129a555f0c0f64e039d2e0884c6d722deee9f095849df336cb8fcbf644c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente cuando los hechos puedan ser constitutivos de delito.', false), ('B', 'En cualquier caso, a elección del interesado, sin seguir el cauce reglado.', false), ('C', 'Solo cuando lo autorice el Jefe de la Zona correspondiente.', false), ('D', 'Cuando no sean debidamente atendidas por el cauce reglado o se refieran al mando inmediato superior.', true)) as v(label, body, ok)
)
