with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Defensor del Pueblo, una vez propuesto el candidato o candidatos, el Pleno del Congreso se convocará para su elección:', 'El art. 2.4 LO 3/1981 fija un término no inferior a diez días; el candidato necesita tres quintos del Congreso y, en un plazo máximo de veinte días, la ratificación del Senado por la misma mayoría.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Réplica 2026 (n.º 22) · Art. 2.4 LO 3/1981', 'Cuatro. Propuesto el candidato o candidatos, se convocará en término no inferior a diez días al Pleno del Congreso para que proceda a su elección.', null, 'eee771cf8ac4f9d84eaeee57934182aa846da30cb85cf969df0170bbdfd8444a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eee771cf8ac4f9d84eaeee57934182aa846da30cb85cf969df0170bbdfd8444a')
