with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre los efectos de la reagrupación familiar en circunstancias especiales (art. 19 de la Ley Orgánica 4/2000), señale la afirmación CORRECTA:', 'El art. 19 LOEX permite la residencia independiente del cónyuge con medios suficientes (o víctima de violencia de género con orden de protección o informe fiscal), de los hijos al alcanzar la mayoría de edad con medios suficientes y de los familiares si muere el reagrupante; la autorización del cónyuge e hijos en edad laboral habilita para trabajar.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Réplica 2026 (n.º 57) · Art. 19 LO 4/2000', '5. En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen.', null, 'ae85d313108791fce5ef83786f0a7ce7d320be512b1b61cf902680859783fed0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae85d313108791fce5ef83786f0a7ce7d320be512b1b61cf902680859783fed0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En caso de muerte del reagrupante, los familiares reagrupados podrán obtener una autorización de residencia independiente en las condiciones que se determinen.', true), ('B', 'El cónyuge reagrupado no puede obtener nunca una autorización de residencia independiente.', false), ('C', 'Los hijos reagrupados obtienen residencia independiente al cumplir dieciséis años, sin otros requisitos.', false), ('D', 'La autorización de residencia por reagrupación del cónyuge no le habilita para trabajar.', false)) as v(label, body, ok)
)
