with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica de Fuerzas y Cuerpos de Seguridad, ¿cuál de los siguientes tiene la consideración de Fuerza y Cuerpo de Seguridad?', 'El art. 2 LOFCS enumera las FCSE dependientes del Gobierno de la Nación, los Cuerpos de Policía de las Comunidades Autónomas y los de las Corporaciones Locales.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Réplica 2026 (n.º 68) · Art. 2 LO 2/1986', 'Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.', null, '341287e93a313ab64e89b3a07f09717acd5a91abb4eaceed7dd4001c4dc1e2ed', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '341287e93a313ab64e89b3a07f09717acd5a91abb4eaceed7dd4001c4dc1e2ed')
  returning id
