  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los Cuerpos de Policía dependientes de las Comunidades Autónomas.', true), ('B', 'El Servicio de Vigilancia Aduanera.', false), ('C', 'El personal de las empresas de seguridad privada.', false), ('D', 'La Armada.', false)) as v(label, body, ok)
)
