with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 9.2 de la Ley Orgánica 1/1982, la tutela judicial frente a intromisiones ilegítimas comprende las medidas necesarias para poner fin a la intromisión. Señale la afirmación INCORRECTA:', 'En la intromisión en el honor, el restablecimiento incluye la publicación total o parcial de la sentencia a costa del condenado, sin perjuicio del derecho de réplica (art. 9.2.a).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11196'), 'Réplica 2026 (n.º 23) · Art. 9.2 LO 1/1982', 'la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida. b) Prevenir intromisiones inminentes o ulteriores. c) La indemnización de los daños y perjuicios causados. d) La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.', null, '1b163cafcb4cf7047a5b806bf025a1b497f633c45dd592834c88bc45231e7ac0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1b163cafcb4cf7047a5b806bf025a1b497f633c45dd592834c88bc45231e7ac0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comprende las medidas necesarias para prevenir intromisiones inminentes o ulteriores.', false), ('B', 'Comprende la indemnización de los daños y perjuicios causados.', false), ('C', 'La publicación de la sentencia condenatoria por intromisión en el honor se hará siempre a costa del perjudicado.', true), ('D', 'Comprende la apropiación por el perjudicado del lucro obtenido con la intromisión.', false)) as v(label, body, ok)
)
