with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con el principio de igualdad y la tutela contra la discriminación en la Ley Orgánica 3/2007, señale la afirmación INCORRECTA:', 'La inversión de la carga de la prueba del art. 13.1 opera en los procedimientos en que la parte actora alegue discriminación por razón de sexo, pero el art. 13.2 la excluye expresamente en los procesos penales.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Réplica 2026 (n.º 13) · Arts. 4, 11, 12 y 13 LO 3/2007', 'corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad. […] 2. Lo establecido en el apartado anterior no será de aplicación a los procesos penales.', null, 'e3926124736fde3eadfda41dac488fd57c2c762c950ad12b30d78d031f90eda8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e3926124736fde3eadfda41dac488fd57c2c762c950ad12b30d78d031f90eda8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los Poderes Públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.', false), ('B', 'La tutela del derecho a la igualdad entre mujeres y hombres puede recabarse ante los tribunales incluso tras terminar la relación en la que se produjo la discriminación.', false), ('C', 'La igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico.', false), ('D', 'En los procesos penales por discriminación por razón de sexo corresponde a la persona acusada probar la ausencia de discriminación.', true)) as v(label, body, ok)
)
