with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica de protección de la seguridad ciudadana, el volante que se expide a quien ha sido trasladado a dependencias policiales para su identificación, a su salida, acredita:', 'El art. 16.4 LOPSC exige que el volante acredite tres extremos: tiempo de permanencia, causa e identidad de los agentes.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2026 (n.º 60) · Art. 16.4 LO 4/2015', 'se les deberá expedir a su salida un volante acreditativo del tiempo de permanencia en ellas, la causa y la identidad de los agentes actuantes.', null, '09c256e120e57738f4bd07959d1583963925a90204b1f0ee1b6b372af59eb0c6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '09c256e120e57738f4bd07959d1583963925a90204b1f0ee1b6b372af59eb0c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo el tiempo de permanencia en las dependencias.', false), ('B', 'La causa de la identificación y el resultado de la consulta de antecedentes.', false), ('C', 'La identidad de los agentes actuantes y la autoridad judicial informada.', false), ('D', 'Cuánto tiempo ha permanecido allí, por qué motivo se le identificó y quiénes fueron los agentes que intervinieron.', true)) as v(label, body, ok)
)
