with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relación con los registros corporales externos regulados en la Ley Orgánica 4/2015, señale la afirmación CORRECTA:', 'El art. 20 LOPSC: la persona será informada de inmediato de las razones (20.3); pueden realizarse contra su voluntad conforme a idoneidad, necesidad y proporcionalidad (20.4); la regla del agente del mismo sexo cede en situación de urgencia por riesgo grave e inminente (20.2).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2026 (n.º 61) · Art. 20 LO 4/2015', 'que será informada de modo inmediato y comprensible de las razones de su realización.', null, '66325336e98e1d8955c4c3f76cffa6c9c0b2bf028ff0cb0f8cb1cfcee806493a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '66325336e98e1d8955c4c3f76cffa6c9c0b2bf028ff0cb0f8cb1cfcee806493a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La persona afectada será informada de modo inmediato y comprensible de las razones de su realización.', true), ('B', 'Requieren siempre autorización judicial previa.', false), ('C', 'Nunca pueden practicarse contra la voluntad del afectado.', false), ('D', 'Se realizan por un agente del mismo sexo en todo caso, incluso ante un riesgo grave e inminente para los agentes.', false)) as v(label, body, ok)
)
