with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos de las medidas de seguridad extraordinarias de la Ley Orgánica 4/2015, la situación de riesgo sobrevenida por un evento que pone en peligro inminente a personas o bienes y exige una actuación rápida de la autoridad o sus agentes se denomina:', 'El art. 21 LOPSC define así la emergencia, que habilita el cierre o desalojo de locales, la prohibición del paso o la evacuación de inmuebles.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Réplica 2026 (n.º 62) · Art. 21 LO 4/2015', 'se entiende por emergencia aquella situación de riesgo sobrevenida por un evento que pone en peligro inminente a personas o bienes y exige una actuación rápida por parte de la autoridad o de sus agentes para evitarla o mitigar sus efectos.', null, 'ad2449b637ee6c2250209bfac1ea9596902d2418f00f9806bfc16b46036abd86', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad2449b637ee6c2250209bfac1ea9596902d2418f00f9806bfc16b46036abd86')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Catástrofe.', false), ('B', 'Alarma.', false), ('C', 'Calamidad pública.', false), ('D', 'Emergencia.', true)) as v(label, body, ok)
