  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la delegación de competencias en la Ley 40/2015, señale la afirmación CORRECTA:', 'El art. 9 LRJSP: las resoluciones por delegación indican esta circunstancia y se consideran dictadas por el delegante (9.4); salvo autorización legal no se delega lo delegado (9.5); la delegación es revocable en cualquier momento (9.6).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Réplica 2026 (n.º 53) · Art. 9 Ley 40/2015', '4. Las resoluciones administrativas que se adopten por delegación indicarán expresamente esta circunstancia y se considerarán dictadas por el órgano delegante. 5. Salvo autorización expresa de una Ley, no podrán delegarse las competencias que se ejerzan por delegación.', null, 'cebbda0df3d1cf864d7b8c0d1aa98836c74d3c93cf40e5b7f15b0f8a4fb3e6ec', false
