with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el Comité de Derechos Humanos creado por el Pacto Internacional de Derechos Civiles y Políticos, señale la afirmación INCORRECTA:', 'El art. 28.2 PIDCP exige personas de gran integridad moral y reconocida competencia en materia de derechos humanos (valorándose la experiencia jurídica), no diplomáticos; las demás opciones recogen los arts. 28.1, 28.3 y 29.2.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10733'), 'Réplica 2026 (n.º 6) · Arts. 28 y 29 PIDCP', 'Se compondrá de dieciocho miembros […] deberán ser personas de gran integridad moral, con reconocida competencia en materia de derechos humanos […] 3. Los miembros del Comité serán elegidos y ejercerán sus funciones a título personal. […] 2. Cada Estado Parte en el presente Pacto podrá proponer hasta dos personas. Estas personas serán nacionales del Estado que las proponga.', null, '478d1c5473c6fb459bff5dfe3fca1c4174a2d7cff316405de31fcf4a3d9d71e7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '478d1c5473c6fb459bff5dfe3fca1c4174a2d7cff316405de31fcf4a3d9d71e7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Está compuesto por dieciocho miembros.', false), ('B', 'Sus miembros deben ser diplomáticos de carrera con experiencia en política exterior.', true), ('C', 'Sus miembros son elegidos y ejercen sus funciones a título personal.', false), ('D', 'Cada Estado Parte puede proponer un máximo de dos personas, nacionales suyas.', false)) as v(label, body, ok)
)
