with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Pacto Internacional de Derechos Económicos, Sociales y Culturales, la especial protección que se debe conceder a las madres abarca:', 'El art. 10.2 PIDESC no fija un número de semanas: habla de un período de tiempo razonable antes y después del parto, con licencia remunerada o prestaciones adecuadas para las madres que trabajen.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-10734'), 'Réplica 2026 (n.º 5) · Art. 10.2 PIDESC', '2. Se debe conceder especial protección a las madres durante un período de tiempo razonable antes y después del parto.', null, '97000d57dd8f54484029356441d0c1c015d35c99db42ec167c235e47afb3ac17', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '97000d57dd8f54484029356441d0c1c015d35c99db42ec167c235e47afb3ac17')
