with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Prevención de Riesgos Laborales, ante infracciones de excepcional gravedad en materia de seguridad y salud en el trabajo, la suspensión de actividades o, en caso extremo, el cierre del centro de trabajo podrá acordarse por:', 'El art. 53 de la Ley 31/1995 atribuye la medida al Gobierno o a los órganos de gobierno autonómicos competentes, sin perjuicio del pago de salarios o indemnizaciones.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Réplica 2026 (n.º 14) · Art. 53 Ley 31/1995', 'El Gobierno o, en su caso, los órganos de gobierno de las Comunidades Autónomas con competencias en la materia, cuando concurran circunstancias de excepcional gravedad en las infracciones en materia de seguridad y salud en el trabajo, podrán acordar la suspensión de las actividades laborales por un tiempo determinado o, en caso extremo, el cierre del centro de trabajo correspondiente', null, '813cc482c371f4efd8538d756d881e98bd7d3e6a52acbd325659c4cdcf85f298', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '813cc482c371f4efd8538d756d881e98bd7d3e6a52acbd325659c4cdcf85f298')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Inspección de Trabajo y Seguridad Social, exclusivamente.', false), ('B', 'El Gobierno o, en su caso, los órganos de gobierno de las Comunidades Autónomas con competencias en la materia.', true), ('C', 'El Juez de lo Social, a instancia de los Delegados de Prevención.', false), ('D', 'El Comité de Seguridad y Salud de la empresa.', false)) as v(label, body, ok)
)
