with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 67/2010, el documento en que se refleja el Plan de Prevención de Riesgos Laborales de un Departamento u organismo de la Administración General del Estado se conservará a disposición de:', 'El art. 3.3 del RD 67/2010 enumera los tres destinatarios: autoridad laboral, autoridades sanitarias y representantes de los trabajadores.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-2161'), 'Réplica 2026 (n.º 15) · Art. 3.3 RD 67/2010', '3. El Plan de Prevención de Riesgos Laborales habrá de reflejarse en un documento que se conservará a disposición de la autoridad laboral, de las autoridades sanitarias y de los representantes de los trabajadores', null, 'a2cd1c172ff44d001242d24941193604d37af4195a806a09cef0bf4b617792bc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a2cd1c172ff44d001242d24941193604d37af4195a806a09cef0bf4b617792bc')
