with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el Real Decreto 179/2005, sobre prevención de riesgos laborales en la Guardia Civil, el derecho del personal a formular propuestas a los órganos de prevención para mejorar la protección de su seguridad y salud se enuncia como principio de:', 'El art. 8 («Principio de participación») reconoce el derecho a efectuar propuestas a los órganos de prevención, que analiza y valora el Consejo de la Guardia Civil; el art. 7 regula el principio de información.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-3241'), 'Réplica 2026 (n.º 16) · Art. 8 RD 179/2005', 'Artículo 8. Principio de participación. El personal incluido en el ámbito de aplicación de este real decreto tendrá derecho a efectuar propuestas a los órganos de prevención', null, '85654ac0bd18d3b6ff997b4037d1bcf0fb8fc0d63ae47bb0100c636ff456991e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '85654ac0bd18d3b6ff997b4037d1bcf0fb8fc0d63ae47bb0100c636ff456991e')
  returning id
), o as (
