with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Armas, ¿cuál de los siguientes supuestos NO se considera modificación sustancial de una fábrica de armas?', 'El art. 13.3 del Reglamento de Armas solo considera modificación sustancial la ampliación de instalaciones que suponga un aumento de la producción.', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Réplica 2026 (n.º 92) · Art. 13.3 Reglamento de Armas', '3. Se estimará como modificación sustancial de una fábrica la sustitución de la fabricación de unas armas por otras ; la extensión de la fabricación a otros tipos o clases de armas; y la ampliación de sus instalaciones siempre que suponga un aumento de su producción.', null, '92f8f6f6398eac344f2f1e5032bdcd93c5a417ab8020a9b1b90ed503860ff0dc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '92f8f6f6398eac344f2f1e5032bdcd93c5a417ab8020a9b1b90ed503860ff0dc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sustitución de la fabricación de unas armas por otras.', false), ('B', 'La extensión de la fabricación a otros tipos de armas.', false), ('C', 'La ampliación de sus instalaciones cuando no suponga un aumento de su producción.', true), ('D', 'Que la producción se extienda a armas de clases distintas.', false)) as v(label, body, ok)
)
