with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto de la revista de armas en el Reglamento de Armas, señale la afirmación CORRECTA:', 'Art. 90: revista cada cinco años al renovar la licencia (90.1); servicio exterior en abril ante el Jefe de Misión (90.2.b); licencia C en mayo (90.2.c); el arma puede presentarse por tercero autorizado por escrito (90.4).', 'gcexamen_2026', (select id from public.topics where slug = 'gcexamen-2026'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Réplica 2026 (n.º 93) · Art. 90 Reglamento de Armas', 'c) Los poseedores de licencia C pasarán revista durante el mes de mayo ante la Intervención de Armas correspondiente.', null, '82690d55b2652ffd635007bbc32f208f97fde845c7bcc5135ed60d92ff85654e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '82690d55b2652ffd635007bbc32f208f97fde845c7bcc5135ed60d92ff85654e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los funcionarios afectos al servicio exterior pasan revista durante el mes de mayo ante el Jefe de Misión.', false), ('B', 'Las armas que precisen guía de pertenencia pasan revista cada tres años.', false), ('C', 'Es inexcusable presentar el arma personalmente, sin que quepa hacerlo por medio de tercero.', false), ('D', 'Los poseedores de licencia C pasan revista durante el mes de mayo ante la Intervención de Armas correspondiente.', true)) as v(label, body, ok)
