with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la DGT, entre los factores externos que facilitan que el conductor pierda la atención se encuentran:', 'La DGT cita como factores externos las vías familiares o monótonas, la señalización excesiva, la publicidad, el móvil o los accidentes; entre los personales, el sueño, la fatiga, el alcohol y las drogas.', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.dgt.es/muevete-con-seguridad/'), 'Examen tipo 1 (n.º 99, tema P45) · DGT, «Distracciones al volante»', 'Hay factores externos que facilitan que el conductor pierda su atención, por ejemplo: las vías que nos son muy familiares o que nos resultan monótonas, pues estas hacen que bajemos la guardia y no prestemos atención, una señalización excesiva', null, '107642e4d8067b5ff21f2a6bc2354911702444ed3b1af5d5439aa18732801b8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '107642e4d8067b5ff21f2a6bc2354911702444ed3b1af5d5439aa18732801b8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las vías muy familiares o monótonas y una señalización excesiva.', true), ('B', 'Solo el uso del teléfono móvil.', false), ('C', 'Únicamente las condiciones meteorológicas adversas.', false)) as v(label, body, ok)
)
