with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Declaración Universal de Derechos Humanos, en caso de persecución, toda persona tiene derecho:', 'El art. 14.1 DUDH reconoce el derecho de asilo, que no puede invocarse frente a acciones judiciales por delitos comunes (art. 14.2).', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Examen tipo 1 (n.º 62, tema P27) · Art. 14.1 DUDH', '1. En caso de persecución, toda persona tiene derecho a buscar asilo, y a disfrutar de él, en cualquier país.', null, 'b6d40042d1ddb50306871799bbe767e7cc2832a0ba944e0636794af55e8606f9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b6d40042d1ddb50306871799bbe767e7cc2832a0ba944e0636794af55e8606f9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A obtener la nacionalidad del país que la acoja.', false), ('B', 'A buscar asilo, y a disfrutar de él, en cualquier país.', true), ('C', 'A ser extraditada a un tercer país de su elección.', false)) as v(label, body, ok)
)
