with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Declaración Universal de Derechos Humanos, toda persona tiene deberes respecto a la comunidad, puesto que:', 'El art. 29.1 DUDH une libertad y responsabilidad: los deberes hacia la comunidad se justifican porque solo en ella se desarrolla plenamente la personalidad.', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.un.org/es/about-us/universal-declaration-of-human-rights'), 'Examen tipo 1 (n.º 68, tema P30) · Art. 29.1 DUDH', '1. Toda persona tiene deberes respecto a la comunidad, puesto que sólo en ella puede desarrollar libre y plenamente su personalidad.', null, 'feab977408da4a44aa8946049b6ea6ee7283bef40cb274a3ffac337b01006027', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'feab977408da4a44aa8946049b6ea6ee7283bef40cb274a3ffac337b01006027')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Así lo exige la soberanía de cada Estado.', false), ('B', 'Los derechos humanos solo se reconocen a quien cumple sus deberes.', false), ('C', 'Solo en ella puede desarrollar libre y plenamente su personalidad.', true)) as v(label, body, ok)
)
