  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Diccionario panhispánico de dudas, en las palabras con hiato de vocal cerrada tónica, una hache intercalada:', 'El DPD establece que la h intercalada no impide el hiato ni dispensa de la tilde: búho, ahíto, prohíbe, rehén.', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.rae.es/dpd/'), 'Examen tipo 1 (n.º 83, tema P37) · DPD, tilde 2.3.2', 'La presencia de una hache intercalada no exime de la obligación de tildar la vocal tónica del hiato: búho, ahíto, prohíbe, alcohólico, rehén, turbohélice.', null, '9960a31c48dc40e7ac408728f3f52abfdfbff0cbc1a7af101cf5cdc46b0cbe0d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9960a31c48dc40e7ac408728f3f52abfdfbff0cbc1a7af101cf5cdc46b0cbe0d')
