  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el TREBEP, el nombramiento de funcionarios interinos para la ejecución de programas de carácter temporal no podrá tener una duración superior a:', 'El art. 10.1.c) TREBEP limita los programas temporales a tres años, ampliables doce meses; los nueve meses en dieciocho corresponden al exceso o acumulación de tareas (letra d).', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Examen tipo 1 (n.º 13, tema P06) · Art. 10.1.c) TREBEP', 'c) La ejecución de programas de carácter temporal, que no podrán tener una duración superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública que se dicten en desarrollo de este Estatuto.', null, '2549062add95103282000ab70211425133781d3821d9226d4603f7094a0bf98c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2549062add95103282000ab70211425133781d3821d9226d4603f7094a0bf98c')
