  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres años, ampliable hasta doce meses más por las leyes de Función Pública.', true), ('B', 'Nueve meses dentro de un periodo de dieciocho meses.', false), ('C', 'Dos años, ampliable hasta seis meses más por las leyes de Función Pública.', false)) as v(label, body, ok)
)
