  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el TREBEP, es personal laboral el que presta servicios retribuidos por las Administraciones Públicas en virtud de:', 'El art. 11.1 TREBEP define al personal laboral por el contrato de trabajo escrito; el nombramiento es propio de funcionarios y del personal eventual.', 'pnexamen_tipo_1', (select id from public.topics where slug = 'pnexamen-tipo-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Examen tipo 1 (n.º 14, tema P06) · Art. 11.1 TREBEP', '1. Es personal laboral el que en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Públicas.', null, '680f79670448a59c3c5244d5f88d36436eb4ccd13c8f0d421ff1f21ec02fd473', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '680f79670448a59c3c5244d5f88d36436eb4ccd13c8f0d421ff1f21ec02fd473')
  returning id
