with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, la circunstancia de parentesco (ser el agraviado cónyuge, ascendiente, descendiente o hermano del ofensor, entre otros supuestos):', 'El art. 23 CP configura el parentesco como circunstancia mixta: puede atenuar o agravar según la naturaleza, los motivos y los efectos del delito.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 37, tema P16) · Art. 23 CP', 'Es circunstancia que puede atenuar o agravar la responsabilidad, según la naturaleza, los motivos y los efectos del delito', null, '53bc303357c53ddc0170bc1ddb219db38cf9d199db508d6879a7e0cd902ec8d1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '53bc303357c53ddc0170bc1ddb219db38cf9d199db508d6879a7e0cd902ec8d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede atenuar o agravar la responsabilidad, según la naturaleza, los motivos y los efectos del delito.', true), ('B', 'Es siempre una circunstancia agravante.', false), ('C', 'Es siempre una circunstancia atenuante.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, para que la reparación del daño ocasionado a la víctima opere como circunstancia atenuante, debe haberse producido:', 'El art. 21.5.ª CP exige que la reparación o disminución de los efectos del daño se haga en cualquier momento del procedimiento y antes del juicio oral. El requisito de no conocer que el procedimiento se dirige contra él corresponde a la atenuante de confesión (21.4.ª).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 38, tema P16) · Art. 21.5.ª CP', '5.ª La de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral.', null, '53853c6b7d833ab5ec73cfc54615a71be36b9c2097fef18e6d390b4c757b832a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '53853c6b7d833ab5ec73cfc54615a71be36b9c2097fef18e6d390b4c757b832a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Antes de que el culpable conozca que el procedimiento judicial se dirige contra él.', false), ('B', 'En cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral.', true), ('C', 'En cualquier momento, incluso después de dictada la sentencia firme.', false)) as v(label, body, ok)
)
