with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, hay reincidencia cuando, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito:', 'El art. 22.8.ª CP exige condena ejecutoria por delito del mismo título y de la misma naturaleza; no computan los antecedentes cancelados o que debieran serlo ni los delitos leves (salvo multirreincidencia).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 39, tema P16) · Art. 22.8.ª CP', 'Hay reincidencia cuando, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito comprendido en el mismo título de este código, siempre que sea de la misma naturaleza.', null, '2bd558b1e3942ae953d5002c80712960f058ca88189b27150a6b0a49ade72551', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2bd558b1e3942ae953d5002c80712960f058ca88189b27150a6b0a49ade72551')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De cualquier naturaleza, siempre que la condena se haya dictado en los cinco años anteriores.', false), ('B', 'Castigado con pena grave, aunque sus antecedentes penales estén cancelados.', false), ('C', 'Comprendido en el mismo título del Código, siempre que sea de la misma naturaleza.', true)) as v(label, body, ok)
)
