with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, la amenaza de causar a otro un mal constitutivo de delito de lesiones, cuando la amenaza no haya sido condicional, se castiga con la pena de prisión de:', 'El art. 169.2.º CP castiga la amenaza no condicional con prisión de seis meses a dos años; la condicional se castiga con uno a cinco años si el culpable consigue su propósito y con seis meses a tres años si no lo consigue (169.1.º).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 40, tema P17) · Art. 169.2.º CP', '2.º Con la pena de prisión de seis meses a dos años, cuando la amenaza no haya sido condicional.', null, '20ab261328c1e0e1d957b1df8e5953c0dc6d46990cb1dabf905af152c57514e4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '20ab261328c1e0e1d957b1df8e5953c0dc6d46990cb1dabf905af152c57514e4')
  returning id
), o as (
