with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 183.1 del Código Penal, comete delito quien, a través de internet, del teléfono o de otra tecnología de la información, contacte con un menor y le proponga concertar un encuentro para cometer delitos sexuales, siempre que la propuesta se acompañe de actos materiales de acercamiento, si el menor tiene menos de:', 'El art. 183.1 CP castiga con uno a tres años de prisión o multa de doce a veinticuatro meses ese contacto con un menor de dieciséis años, si la propuesta va acompañada de actos materiales encaminados al acercamiento.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 41, tema P17) · Art. 183.1 CP', '1. El que a través de internet, del teléfono o de cualquier otra tecnología de la información y la comunicación contacte con un menor de dieciséis años y proponga concertar un encuentro con el mismo', null, '9acbf3ceccf4ac7894237eadc2ebe07a329dcf537f7ced12ec03761b43bc3577', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9acbf3ceccf4ac7894237eadc2ebe07a329dcf537f7ced12ec03761b43bc3577')
