with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, quien, fuera de los supuestos de apropiación indebida del artículo 253, se apropiare de una cosa mueble ajena sin valor artístico, histórico, cultural o científico y de cuantía superior a 400 euros, será castigado con:', 'El art. 254.1 CP castiga con multa de tres a seis meses la apropiación de cosa mueble ajena (prisión de seis meses a dos años si tiene valor artístico, histórico, cultural o científico); si la cuantía no excede de 400 euros, multa de uno a dos meses (254.2).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 43, tema P18) · Art. 254.1 CP', '1. Quien, fuera de los supuestos del artículo anterior, se apropiare de una cosa mueble ajena, será castigado con una pena de multa de tres a seis meses.', null, 'bc5b91d08310806d8669372c819f9331db10359541e9bf2e766536b21de1c8db', false
