with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, los Jueces o Tribunales podrán rebajar en un grado las penas por tenencia ilícita de armas siempre que, por las circunstancias del hecho y del culpable, se evidencie:', 'El art. 565 CP permite rebajar en un grado las penas de los artículos anteriores cuando se evidencie la falta de intención de usar las armas con fines ilícitos.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 45, tema P19) · Art. 565 CP', 'Los Jueces o Tribunales podrán rebajar en un grado las penas señaladas en los artículos anteriores, siempre que por las circunstancias del hecho y del culpable se evidencie la falta de intención de usar las armas con fines ilícitos.', null, 'b8bdc67cf34b2e146f823eaf55ebde9ab3ab692a3b5047a562f3bc17b747b04c', false
