  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, se entiende por organización criminal la agrupación formada por:', 'El art. 570 bis CP define la organización criminal por la pluralidad (más de dos personas), la estabilidad o duración indefinida y el reparto concertado y coordinado de tareas para cometer delitos.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Examen tipo 2 (n.º 74, tema P33) · Art. 570 bis.1 CP', 'A los efectos de este Código se entiende por organización criminal la agrupación formada por más de dos personas con carácter estable o por tiempo indefinido, que de manera concertada y coordinada se repartan diversas tareas o funciones con el fin de cometer delitos.', null, '9ee0ec8baec585f5dd594bf1f3e483d7c258d2b7a62573b1e60fbca823f0787c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9ee0ec8baec585f5dd594bf1f3e483d7c258d2b7a62573b1e60fbca823f0787c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos o más personas que se unan ocasionalmente para cometer un único delito.', false), ('B', 'Más de cinco personas con una estructura jerárquica y fines exclusivamente económicos.', false), ('C', 'Más de dos personas con carácter estable o por tiempo indefinido que, de manera concertada y coordinada, se repartan diversas tareas o funciones con el fin de cometer delitos.', true)) as v(label, body, ok)
)
