  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Protocolo facultativo de la Convención contra la Tortura, cada Estado Parte mantendrá, designará o creará uno o varios mecanismos nacionales independientes para la prevención de la tortura a más tardar:', 'El art. 17 del Protocolo facultativo fija el plazo de un año para establecer los mecanismos nacionales de prevención, que pueden ser también de entidades descentralizadas. En España esa función la ejerce el Defensor del Pueblo.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2006-11128'), 'Examen tipo 2 (n.º 63, tema P27) · Art. 17 Protocolo facultativo de la Convención contra la Tortura', 'Cada Estado Parte mantendrá, designará o creará, a más tardar un año después de la entrada en vigor del presente Protocolo o de su ratificación o adhesión, uno o varios mecanismos nacionales independientes para la prevención de la tortura a nivel nacional.', null, 'a5a54f4ddb95d062f0a1a04203fc2678633086c6b048399a7d9f00627f7381c8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a5a54f4ddb95d062f0a1a04203fc2678633086c6b048399a7d9f00627f7381c8')
