  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Estatuto Orgánico del Ministerio Fiscal, las diligencias de investigación del Fiscal, con carácter general y salvo prórroga acordada por decreto motivado del Fiscal General del Estado, no podrán exceder de:', 'El art. 5.2 de la Ley 50/1981 limita las diligencias a seis meses (doce para los delitos del art. 19.4), salvo prórroga por decreto motivado del Fiscal General del Estado. Esas diligencias no pueden suponer medidas cautelares o limitativas de derechos, aunque el Fiscal puede ordenar la detención preventiva.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-837'), 'Examen tipo 2 (n.º 51, tema P21) · Art. 5.2 Ley 50/1981', 'sin que pueda exceder de seis meses, salvo prórroga acordada mediante decreto motivado del Fiscal General del Estado.', null, '434ba9dfd5897813d37a35ef384bfdb6c1058f99ffcabf3e35940d4c073a7086', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '434ba9dfd5897813d37a35ef384bfdb6c1058f99ffcabf3e35940d4c073a7086')
