with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, cuando los agentes de la Policía Judicial tengan acceso a una dirección IP utilizada para cometer un delito y no conste la identificación del usuario, para obtener los datos que permitan identificar al sospechoso:', 'El art. 588 ter k LECrim obliga a la Policía Judicial a solicitar al juez de instrucción que requiera a los sujetos con deber de colaboración (art. 588 ter e) la cesión de los datos de identificación y localización del terminal y del sospechoso.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Examen tipo 2 (n.º 47, tema P20) · Art. 588 ter k LECrim', 'solicitarán del juez de instrucción que requiera de los agentes sujetos al deber de colaboración según el artículo 588 ter e, la cesión de los datos que permitan la identificación y localización del terminal o del dispositivo de conectividad y la identificación del sospechoso.', null, '688c45d6b550f7b99a0a3da03093fb8a18d75fa70533fb5124dd42fb76da3802', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '688c45d6b550f7b99a0a3da03093fb8a18d75fa70533fb5124dd42fb76da3802')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solicitarán del juez de instrucción que requiera la cesión de esos datos a los sujetos obligados a colaborar.', true), ('B', 'Requerirán directamente los datos al prestador de servicios, dando cuenta al juez en veinticuatro horas.', false), ('C', 'Solicitarán los datos al Ministerio Fiscal, que los requerirá mediante decreto.', false)) as v(label, body, ok)
)
