with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, la discriminación que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas se denomina:', 'El art. 3.e) de la Ley 4/2023 define la discriminación por asociación (por la relación con otra persona sobre la que concurre una causa de discriminación) y la discriminación por error (basada en una apreciación incorrecta de las características de la persona).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Examen tipo 2 (n.º 55, tema P23) · Art. 3.e) Ley 4/2023', 'La discriminación por error es aquella que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas.', null, '3feab322f9731f8935ca0541cc6a762bca2493a08f73c6b32af111cf2846c8af', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3feab322f9731f8935ca0541cc6a762bca2493a08f73c6b32af111cf2846c8af')
