with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 7/2021, las decisiones basadas únicamente en un tratamiento automatizado, incluida la elaboración de perfiles, que produzcan efectos jurídicos negativos para el interesado:', 'El art. 14.1 LO 7/2021 prohíbe estas decisiones salvo autorización expresa por norma con rango de ley o por el Derecho de la UE, que debe incluir garantías como el derecho a obtener intervención humana.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806'), 'Examen tipo 2 (n.º 60, tema P26) · Art. 14.1 LO 7/2021', '1. Están prohibidas las decisiones basadas únicamente en un tratamiento automatizado, incluida la elaboración de perfiles, que produzcan efectos jurídicos negativos para el interesado o que le afecten significativamente, salvo que se autorice expresamente por una norma con rango de ley o por el Derecho de la Unión Europea.', null, 'e6162dbf57034b65fd0f25634ee7ea4d604db54d0e2545580de88be74c10b494', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e6162dbf57034b65fd0f25634ee7ea4d604db54d0e2545580de88be74c10b494')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Están permitidas siempre que las autorice el responsable del tratamiento.', false), ('B', 'Están prohibidas, salvo que se autoricen expresamente por una norma con rango de ley o por el Derecho de la Unión Europea.', true), ('C', 'Están permitidas si las acuerda la autoridad policial competente, dando cuenta al juez.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 7/2021, las infracciones administrativas leves, graves y muy graves que tipifica prescriben, respectivamente, a:', 'El art. 63.1 LO 7/2021 fija la prescripción de las infracciones en seis meses (leves), dos años (graves) y tres años (muy graves). Las sanciones prescriben al año, a los dos y a los tres años (art. 63.2).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806'), 'Examen tipo 2 (n.º 61, tema P26) · Art. 63.1 LO 7/2021', '1. Las infracciones administrativas tipificadas en esta Ley Orgánica prescribirán a los seis meses, a los dos o a los tres años de haberse cometido, según sean leves, graves o muy graves, respectivamente.', null, '1435989af331488446ecb2e0a4eb1a294f737ce8fa7add4d649151dd6e6eaa5c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1435989af331488446ecb2e0a4eb1a294f737ce8fa7add4d649151dd6e6eaa5c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El año, a los dos años y a los tres años.', false), ('B', 'Los seis meses, al año y a los dos años.', false), ('C', 'Los seis meses, a los dos años y a los tres años.', true)) as v(label, body, ok)
)
