with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/1981, del Defensor del Pueblo, ¿qué hará el Defensor del Pueblo con las quejas anónimas?', 'El art. 17.3 LO 3/1981 obliga a rechazar las quejas anónimas y permite rechazar las formuladas con mala fe, sin fundamento o sin pretensión; esas decisiones no son susceptibles de recurso.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Examen tipo 2 (n.º 4, tema P02) · Art. 17.3 LO 3/1981', 'Tres. El Defensor del Pueblo rechazará las quejas anónimas y podrá rechazar aquellas en las que advierta mala fe, carencia de fundamento, inexistencia de pretensión', null, 'f1cd76032e20dc21b533d5da1503e3420cc5a6d6a568133e1b8d5f4ef79796ec', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f1cd76032e20dc21b533d5da1503e3420cc5a6d6a568133e1b8d5f4ef79796ec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las tramitará solo si afectan a derechos fundamentales.', false), ('B', 'Las remitirá al Ministerio Fiscal.', false), ('C', 'Las rechazará.', true)) as v(label, body, ok)
)
