  select 'Admitida una queja, el Defensor del Pueblo dará cuenta de ella al organismo afectado para que su jefe remita informe escrito en el plazo máximo de:', 'El art. 18.1 LO 3/1981 fija un plazo máximo de quince días para el informe escrito, ampliable a juicio del Defensor del Pueblo. No confundir con los diez días mínimos que el art. 20.2 da al funcionario afectado para responder.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Examen tipo 2 (n.º 5, tema P02) · Art. 18.1 LO 3/1981', 'con el fin de que por su Jefe en el plazo máximo de quince días, se remita informe escrito. Tal plazo será ampliable cuando concurran circunstancias que lo aconsejen a juicio del Defensor del Pueblo.', null, 'b336a87197644b16551454856fbdecfd8ce852f6636975498c779f36ec92a0a0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b336a87197644b16551454856fbdecfd8ce852f6636975498c779f36ec92a0a0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quince días, ampliable cuando concurran circunstancias que lo aconsejen.', true), ('B', 'Diez días, improrrogable.', false), ('C', 'Un mes, ampliable por otro mes.', false)) as v(label, body, ok)
)
