with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2000, los extranjeros residentes podrán encontrarse en la situación de:', 'El art. 30 bis LO 4/2000 define a los residentes como los extranjeros titulares de una autorización para residir y distingue dos situaciones: residencia temporal y residencia de larga duración.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Examen tipo 2 (n.º 23, tema P10) · Art. 30 bis.2 LO 4/2000', '2. Los residentes podrán encontrarse en la situación de residencia temporal o de residencia de larga duración.', null, 'bb286590773695f69cb60ac91ab2393860f0a48f7a0ffae328ab99bc067f870a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bb286590773695f69cb60ac91ab2393860f0a48f7a0ffae328ab99bc067f870a')
