with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2000, tendrán derecho a residencia de larga duración, reuniendo las condiciones reglamentarias, quienes hayan tenido residencia temporal en España de forma continuada durante:', 'El art. 32.2 LO 4/2000 exige cinco años de residencia temporal continuada. La residencia de larga duración autoriza a residir y trabajar en España indefinidamente en las mismas condiciones que los españoles (art. 32.1).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Examen tipo 2 (n.º 24, tema P10) · Art. 32.2 LO 4/2000', '2. Tendrán derecho a residencia de larga duración los que hayan tenido residencia temporal en España durante cinco años de forma continuada, que reúnan las condiciones que se establezcan reglamentariamente.', null, 'd82ad9ae5794fd55a3bc038a3f0ca73293b6f173762c61856b53e6a06618792a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd82ad9ae5794fd55a3bc038a3f0ca73293b6f173762c61856b53e6a06618792a')
  returning id
), o as (
