  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No empieza a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución, con un máximo de diez años.', true), ('B', 'Empieza a contar desde la notificación de la resolución de expulsión y se produce a los cinco años.', false), ('C', 'Empieza a contar desde que el extranjero abandona el territorio español y se produce a los dos años.', false)) as v(label, body, ok)
