with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2000, los lugares de internamiento para extranjeros a los que se ha denegado la entrada:', 'El art. 60.2 LO 4/2000 dispone que esos lugares no tienen carácter penitenciario, están dotados de servicios sociales, jurídicos, culturales y sanitarios y los extranjeros solo quedan privados del derecho ambulatorio.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'Examen tipo 2 (n.º 27, tema P11) · Art. 60.2 LO 4/2000', '2. Los lugares de internamiento para extranjeros no tendrán carácter penitenciario, y estarán dotados de servicios sociales, jurídicos, culturales y sanitarios. Los extranjeros internados estarán privados únicamente del derecho ambulatorio.', null, 'ec01c18912ddf9c32606900e4075afc039848708502aea87fc0989cf0d11a41d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ec01c18912ddf9c32606900e4075afc039848708502aea87fc0989cf0d11a41d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tienen carácter penitenciario y dependen de la Secretaría General de Instituciones Penitenciarias.', false), ('B', 'No tienen carácter penitenciario y los internados están privados únicamente del derecho ambulatorio.', true), ('C', 'No tienen carácter penitenciario, pero los internados quedan privados del derecho a comunicarse con el exterior.', false)) as v(label, body, ok)
)
