with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, cuando en un servicio concurran simultáneamente unidades de las Fuerzas y Cuerpos de Seguridad del Estado y de la Policía de una Comunidad Autónoma, fuera del supuesto de auxilio solicitado por la Comunidad, la dirección de la operación corresponde a:', 'El art. 46.2 LO 2/1986 atribuye la dirección de la operación a los Mandos de las Fuerzas y Cuerpos de Seguridad del Estado cuando concurren simultáneamente con la Policía autonómica.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Examen tipo 2 (n.º 21, tema P09) · Art. 46.2 LO 2/1986', 'concurran, simultáneamente, miembros o Unidades de las Fuerzas y Cuerpos de Seguridad del Estado y de la Policía de la Comunidad Autónoma, serán los Mandos de los primeros los que asuman la dirección de la operación.', null, 'bbaaed8f158e622d5706ccf338d44728815fcc5b1b40fd50f1274ce1a4f7d377', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bbaaed8f158e622d5706ccf338d44728815fcc5b1b40fd50f1274ce1a4f7d377')
  returning id
