with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 6/1984, el procedimiento de habeas corpus, salvo cuando se incoe de oficio, se iniciará por medio de escrito o comparecencia:', 'El art. 4 LO 6/1984 permite iniciar el habeas corpus por escrito o comparecencia sin necesidad de Abogado ni Procurador; deben constar los datos del solicitante, el lugar de custodia y el motivo concreto.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Examen tipo 2 (n.º 49, tema P21) · Art. 4 LO 6/1984', 'El procedimiento se iniciará, salvo cuando se incoe de oficio, por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador.', null, '2240a1e345f8e71db26b24e316362a82b12790c724645b92481aff7feb9c61ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2240a1e345f8e71db26b24e316362a82b12790c724645b92481aff7feb9c61ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siendo preceptiva la intervención de Abogado, pero no de Procurador.', false), ('B', 'No siendo preceptiva la intervención de Abogado ni de Procurador.', true), ('C', 'Siendo preceptiva la intervención de Abogado y de Procurador.', false)) as v(label, body, ok)
)
