with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2015, la proyección de haces de luz sobre los pilotos o conductores de medios de transporte que pueda deslumbrarles y provocar accidentes es una infracción:', 'El art. 35.4 LO 4/2015 la tipifica como muy grave. En cambio, proyectar haces de luz sobre miembros de las FCS para dificultar sus funciones es leve (art. 37.6).', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Examen tipo 2 (n.º 32, tema P14) · Art. 35.4 LO 4/2015', '4. La proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre los pilotos o conductores de medios de transporte que puedan deslumbrarles o distraer su atención y provocar accidentes.', null, 'a4f934aa3d230a0bf6db0446e81b9ddae038130dd1be2f85753c6b843b764e10', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a4f934aa3d230a0bf6db0446e81b9ddae038130dd1be2f85753c6b843b764e10')
  returning id
