with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2010, los funcionarios sancionados con traslado forzoso no podrán obtener nuevo destino en el centro, unidad o plantilla de la que fueron trasladados durante el período que fije la resolución sancionadora, que será de:', 'El art. 11 LO 4/2010 fija ese período entre uno y tres años, computados desde que se efectúa el traslado.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-8115'), 'Examen tipo 2 (n.º 17, tema P08) · Art. 11.1 LO 4/2010', 'en el período de uno a tres años determinado en la resolución sancionadora', null, 'd514755fa3f010e8e664a2238dd9dbde297116a2ac543d28a976086164e8d521', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd514755fa3f010e8e664a2238dd9dbde297116a2ac543d28a976086164e8d521')
