with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, la suspensión provisional por expediente disciplinario, por hechos que no son objeto de procedimiento penal, no podrá exceder, salvo paralización imputable al interesado, de:', 'El art. 65.2 LO 9/2015 limita la suspensión provisional a tres meses (faltas graves) y seis meses (faltas muy graves), salvo paralización del procedimiento imputable al interesado.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Examen tipo 2 (n.º 18, tema P08) · Art. 65.2 LO 9/2015', 'no podrá exceder de tres meses en caso de faltas graves, y de seis meses, en caso de faltas muy graves, salvo paralización del procedimiento imputable al interesado.', null, 'b58542b1151ba96215970d2ef7d2c59cee0b3fe76ade65163d636960ef6752a2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b58542b1151ba96215970d2ef7d2c59cee0b3fe76ade65163d636960ef6752a2')
  returning id
), o as (
