  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes en caso de faltas graves y tres meses en caso de faltas muy graves.', false), ('B', 'Tres meses en caso de faltas graves y seis meses en caso de faltas muy graves.', true), ('C', 'Seis meses en caso de faltas graves y un año en caso de faltas muy graves.', false)) as v(label, body, ok)
)
