with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, los funcionarios de la Policía Nacional podrán pasar a segunda actividad por petición propia tras haber cumplido:', 'El art. 67 LO 9/2015 prevé tres causas de segunda actividad: insuficiencia de aptitudes psicofísicas, petición propia al cumplir las edades del art. 69 y petición propia tras veinticinco años efectivos en servicio activo, servicios especiales o excedencia forzosa.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Examen tipo 2 (n.º 19, tema P08) · Art. 67.c) LO 9/2015', 'c) Por petición propia, tras haber cumplido veinticinco años efectivos en las situaciones de servicio activo, servicios especiales o excedencia forzosa en la Policía Nacional', null, 'f25ebf6b73f64482c3c2eef0a9b98c371bb64ffa59fc4e3c51b519b09de224f1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f25ebf6b73f64482c3c2eef0a9b98c371bb64ffa59fc4e3c51b519b09de224f1')
  returning id
), o as (
