  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veinticinco años efectivos en las situaciones de servicio activo, servicios especiales o excedencia forzosa.', true), ('B', 'Veinte años efectivos en cualquier situación administrativa.', false), ('C', 'Treinta años de servicios, siempre que tengan cincuenta y cinco años de edad.', false)) as v(label, body, ok)
)
