with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 5/2014, de Seguridad Privada, los detectives privados:', 'El art. 48.3 de la Ley 5/2014 prohíbe en todo caso investigar la vida íntima que transcurra en domicilios o lugares reservados y utilizar medios que atenten contra el honor, la intimidad, la propia imagen, el secreto de las comunicaciones o la protección de datos.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Examen tipo 2 (n.º 30, tema P13) · Art. 48.3 Ley 5/2014', '3. En ningún caso se podrá investigar la vida íntima de las personas que transcurra en sus domicilios u otros lugares reservados', null, 'ebfe3302ef0c3f951a5bde9db52e78596d8b8bf27ade702298d7337f2d448b65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ebfe3302ef0c3f951a5bde9db52e78596d8b8bf27ade702298d7337f2d448b65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En ningún caso podrán investigar la vida íntima de las personas que transcurra en sus domicilios u otros lugares reservados.', true), ('B', 'Podrán investigar la vida íntima en domicilios cuando lo encargue un tercero legitimado.', false), ('C', 'Podrán investigar en domicilios con autorización de la Delegación del Gobierno.', false)) as v(label, body, ok)
)
