with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 5/2014, cuando así se decida por el órgano competente y cumpliendo estrictamente las órdenes de las Fuerzas y Cuerpos de Seguridad, podrá prestarse por seguridad privada:', 'El art. 41.3 de la Ley 5/2014 permite, por decisión del órgano competente y bajo las órdenes de las FCS, la vigilancia perimetral de centros penitenciarios y de centros de internamiento de extranjeros y la vigilancia de otros edificios de organismos públicos.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Examen tipo 2 (n.º 31, tema P13) · Art. 41.3 Ley 5/2014', 'a) La vigilancia perimetral de centros penitenciarios.', null, '267e522031651159013f02c22fe3e84b4b09a503fe17e4e1ad2fb03ce25591d0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '267e522031651159013f02c22fe3e84b4b09a503fe17e4e1ad2fb03ce25591d0')
