with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley sobre Tráfico, tienen preferencia de paso sobre los demás vehículos, además de los de servicio de urgencia en servicio de tal carácter:', 'El art. 27 de la Ley sobre Tráfico da preferencia a los vehículos de servicio de urgencia en servicio, a los equipos de mantenimiento de la vía y a los vehículos que acudan a un servicio de auxilio en carretera.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'Examen tipo 2 (n.º 96, tema P43) · Art. 27 RDLeg 6/2015, Ley sobre Tráfico', 'Tienen preferencia de paso sobre los demás vehículos y otros usuarios de la vía los vehículos de servicio de urgencia, cuando se hallen en servicio de tal carácter, así como los equipos de mantenimiento de las instalaciones y de la infraestructura de la vía y los vehículos que acudan a realizar un servicio de auxilio en carretera.', null, '14132ac42b223f6d5cf7022ad572c9aad142c72a1998591d1de96093698ead76', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '14132ac42b223f6d5cf7022ad572c9aad142c72a1998591d1de96093698ead76')
  returning id
), o as (
