  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los vehículos de transporte escolar.', false), ('B', 'Los autobuses de transporte público urbano.', false), ('C', 'Los vehículos que acudan a realizar un servicio de auxilio en carretera.', true)) as v(label, body, ok)
)
