  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el RD 773/1997, el tiempo durante el cual haya de llevarse un equipo de protección individual se determinará, entre otros factores, en función de:', 'El art. 7.2 del RD 773/1997 fija las condiciones de uso de los EPI, en particular el tiempo de uso, según la gravedad del riesgo, el tiempo o frecuencia de exposición, las condiciones del puesto, las prestaciones del equipo y los riesgos adicionales de su utilización.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Examen tipo 2 (n.º 100, tema P45) · Art. 7.2 RD 773/1997, equipos de protección individual', 'Las condiciones en que un equipo de protección deba ser utilizado, en particular, en lo que se refiere al tiempo durante el cual haya de llevarse, se determinarán en función de: […] a) La gravedad del riesgo.', null, '7c1e099be8f5371ee6be22422b8f9b922b4150204b8e397d831f570d2dbbdda9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7c1e099be8f5371ee6be22422b8f9b922b4150204b8e397d831f570d2dbbdda9')
