  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al apercibirse de las señales ópticas o acústicas de un vehículo prioritario, los peatones deberán:', 'El art. 122.5 del Reglamento General de Circulación obliga a los peatones a despejar la calzada y permanecer en refugios o zonas peatonales o, en su defecto, alejarse de la zona de circulación.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Examen tipo 2 (n.º 95, tema P43) · Art. 122.5 RD 1428/2003, Reglamento General de Circulación', '5. Al apercibirse de las señales ópticas o acústicas de los vehículos prioritarios, los peatones deberán despejar la calzada y permanecer en los refugios o zonas peatonales, si existen, o, en su defecto, alejarse de la zona de circulación de los vehículos.', null, '1cca722433e377b3f6c107b7385ea3cc3d2561156be9f256db4213de6732da5a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1cca722433e377b3f6c107b7385ea3cc3d2561156be9f256db4213de6732da5a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Despejar la calzada y permanecer en los refugios o zonas peatonales, si existen.', true), ('B', 'Detenerse en el lugar en que se encuentren, aunque sea la calzada.', false), ('C', 'Cruzar la calzada lo más rápido posible por el lugar más próximo.', false)) as v(label, body, ok)
)
