with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el TREBEP, la renuncia a la condición de funcionario:', 'El art. 64.3 TREBEP aclara que quien renuncia puede volver a ingresar superando el procedimiento de selección establecido.', 'pnexamen_tipo_2', (select id from public.topics where slug = 'pnexamen-tipo-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Examen tipo 2 (n.º 13, tema P06) · Art. 64.3 TREBEP', '3. La renuncia a la condición de funcionario no inhabilita para ingresar de nuevo en la Administración Pública a través del procedimiento de selección establecido.', null, 'cfb6f9df0f6bbab0ab1916156246ffcd2ecc328fc9b5247278b5e31e9a1d3de5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cfb6f9df0f6bbab0ab1916156246ffcd2ecc328fc9b5247278b5e31e9a1d3de5')
  returning id
